BEGIN IMMEDIATE;
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory',NULL,'行测','政治理论','政治理论','module',1,1,'gongkao.xingce.political_theory','依据冯泽政治理论11讲主课、6讲时政加课及配套知识库组织。政策事实以课程年份为准。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 10217, "end_char": 10517, "line": 1, "excerpt": "后紧接着再往下进一步形成人才辈出，人尽其才，人尽其用的生动局面，这就不说了，同学们啊，这三个词。看一看就可以了啊，可出题的点其实不是特别的多，然后往下第二个建设教育强国啊，科技强国，人才强国，必须坚持什么呢？正确的办学方向先理解这个。同学们，还记不记得正确的办学方向是什么方向？同学们非常好，我看到了花生不识数，同学对吧？唉，是社会主义的办学方向。啊，社会主义办学方向千万记住啊，这是我们后面讲新思想的时候，其实会讲到的啊，也就是本身关于正确的办学方向的问题，哪个方向其实就是我们。啊，这个整个大的层面上是要坚持社会主义的办学方向，这个就是啥意思呢？也就是你不要在这个培养人才的过程当中，对不对？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 8508, "end_char": 8808, "line": 3, "excerpt": "一点儿。那么，往下第三个啊，我们强调深入实施科教兴国战略，提升国家创新体系的整体效能，那怎么实行科科教兴国呢？首先，第一个强调了一个数字啊。数字这块说，制定实施教育强国建设的三年行动计划啊，我们之前啊，给大家也说过这个问题，就是如果说在一整道题当中，你会发现啊。呵呵呵，是别骂了，题是我出的，同学们别骂了好吗？哈哈哈，题是我出的啊。就是呃，如果啊，在一个题当中，他所有的一些这个选项都没有去提到这个呃年份的这个问题，知道吗？哎，都没有提到这个年份数字的问题而。只有一个选项提到了年份的问题，你就要重点关注了，知道了吗？同学们哎，那他很有可能，你看把这个三年就改成五年对不对？哎，等等，类似于这种啊，所", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 73, "end_char": 373, "line": 1, "excerpt": "给大家讲到了第三章对不对哎？第三章呢？然后我们把这个重要的文件。前两个也就是政府工作报告以及中央一号文件给大家讲完了，那么今天呢？我们继续开始讲啊，就是讲第三个教育强国建设规划纲要二零二四到二零。二零三五年，所以之前的时候，如果大家啊没没及时跟课的对吧？然后今天来了那把这个讲义啊，打到咱们这个章节好吧？那么来看啊，在这个章节当中，其实你会发现啊，关于教育强国的很多问题，我们在之前的时候给大家多多少少讲到新思想的时候，其实有一些问题是强调过的，对吧？哎，那先来看第一个啊，在这个规划纲要当中，第一个需要大家掌握的知识点就在这儿了，看到了吧？哎，也就是坚持什么样的一种办学方向，那么我们前面在讲到这个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250921 政治理论(时政)加课6.doc.txt", "source_sha256": "862757d3895e3eb6851995aeed8aa859c9f6e438490910fcff7e4a59da6f6037", "start_char": 186, "end_char": 240, "line": 1, "excerpt": "加快建设农业强国，规划二零二四到二零。二零三五年，那么首先第一个啊，大家先明确的就是我们未来所要建成的这个农", "policy_id": "FENGZE_POL_041", "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 508, "end_char": 538, "line": 1, "excerpt": "坚持社会主义的办学方向。那么，同样啊，落实立德树人的根本任务", "policy_id": "FENGZE_POL_040", "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 32313, "end_char": 32613, "line": 3, "excerpt": "紧接着往下两个确保，确保是啥呢？这是过去我们在讲到呃二四年一号文件的时候说到的，我们要确保两条底线。啊，所以我们经常叫两个底线嘛，哪两个底线一个强调的是确保国家粮食安全底线，另外一个是确保不发生规模性返贫置贫底线。看到了吧？哎，这是两条底线啊，也要从整个的这个农业发展上对不对？哎，从三农的这个角度上，我们强调两条底线，一个是粮食安全，一个是哎，不发生规模性返贫置贫的底线。那么，三个提升，三个提升，提升啥？同学们，其实这是过去在二四年一号文件当中提出的，叫三项重点工作。啊三项重点工作，那我们后面讲的很多的举措，同学们，你会发现它都是围绕着两个确保和三个提升来的啊，哪三项重点工作呢？第一个强调。提", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 10062, "end_char": 10362, "line": 1, "excerpt": "之外，剩下的同学们都是一样的，和我们之前讲的一号文件的说法是完全一样的，你看比如说我们。之前给大家强调的两条底线，对吧？哎，哪两条底线啊？同学们，一个是确保国家粮食安全底线，另外一个就是确保农业呃，农村人口不发生规模性返贫底线啊。啊，然后紧接着再往下三项重点工作，哪三项重点工作呀？是不是哎？以提升乡村产业发展，乡村建设，乡村治理水平啊？那你可以记按照之前的这个记啊。叫什么叫产建制？看到了吗？产建制啊，你可以按照这个去记好不好？哎，好了啊，这是在这一块儿，然后最后这五个振兴了解就行了，好吧，哎，这个不作为重点啊，产业人才。文化生态组织振兴，这提了太久了啊，提了太久了好了，这是在这儿啊，我们给大家", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 8886, "end_char": 8962, "line": 1, "excerpt": "锚定建设农业强国目标，哎，同学们来啊。重点内容一定要回过神儿来了啊，重点内容看我们这一块儿讲到的内容，你会发现它和我们前面讲一号文件的一些表述就不一样了", "policy_id": "FENGZE_POL_039", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 49249, "end_char": 49326, "line": 1, "excerpt": "降低财政赤字率错了吧？哎，刚才是说的是提高财政赤字率对不对？哎，然后说停止超长期特别国债，那也错了啊，应该是增发超长期特别国债。哎，然后其他两个这个都对了", "policy_id": "FENGZE_POL_038", "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 626, "end_char": 714, "line": 3, "excerpt": "国内生产总值增长5%左右，这个是不是和去年是持平的，对吧？哎，因为去年的时候我们强调二零二四年它的国内生产总值增长是一百三十四点九万亿。对不对诶？然后增长是多少？增长不就5%嘛", "policy_id": "FENGZE_POL_037", "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 329, "end_char": 412, "line": 3, "excerpt": "扩大内需，那既然是扩大内需，之前给大家讲过内需。它包括两个方面，哪两个方面？一个是消费，另外一个就是投资，看到了吗？同学们，唉，所以在这里面啊，首先你要先了解国内需求", "policy_id": "FENGZE_POL_036", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 47395, "end_char": 47465, "line": 1, "excerpt": "第11题选b选项啊。然后往下同学们，我们把这个四和五就是把这个政策给大家讲完好吗？同学们把四和五政策讲完啊，因为我知道你们中午还有课啊，但是", "policy_id": "FENGZE_POL_035", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 7667, "end_char": 7967, "line": 1, "excerpt": "全称是什么？看它的这个称呼啊，叫中国共产党第20次全国代表大会。这也就是我们简单意义上来说的什么，同学们。就是党代会。啊，就是党代会，我们所有的党员，我们之前学历史的时候是不是学了，对吧？还记得吗？同学们在一九二一年的时候，中共一大是不是召开了那个一大就是我们现在20大对吧？不断延伸过来的啊。从这开始，那么党代会注意它一般是多少？五年开一次啊，五年开一次，大家注意，这是从我们建国之后啊，建国之后也就是从一九八二年那个时候开始，其实才形成这样的一个。比较规律的啊，时间的啊，因为之前的时间大家学那个历史，我们学党代会的时候，大家也发现了那个时间不是很规律，对不对？哎，所以在这块儿大家知知道，就每五", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 38335, "end_char": 38635, "line": 3, "excerpt": "命这一重大问题上认识更加清醒，行动更加坚定。因为我们之前说过自我革命，这是第几个答案，同学们。之前是不是讲了对吧？前面刚讲完啊，自我革命，这是我们党跳出治乱兴衰历史周期律的第二个答案，对吧？唉，前面说过就不再多说啊，所以你看我们坚持把它作为第二个答案。所以我们对于自我革命这个问题认识更加先行，更加坚定啊，那第二个就是我们在扎实开展党纪学习教育。啊，党纪学习教育那么全党同志遵守唉，遵规守纪的意识更加增强了啊，好，这是党纪，然后紧接着第三。持续加大反腐败力度，铲除腐败滋生的土壤和条件。同学们啊，这个反腐败力度大不大？你就看我们每天的新闻就行了，对吧？哎，每天你看，无论是我们的这个央央视新闻，还是新", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 18988, "end_char": 19288, "line": 1, "excerpt": "国企业，中国公民一样的这种待遇。那你来不来？对吧？唉，是要来的啊，那么往下第八个第八个呢？强调多边主义是解决世界面临困难挑战的必然选择，而经济全球化是不可阻挡的历史潮流。这个注意别。别让这两个词互换位置就行了啊，因为之前我们在强调世界经济发展的时候，一直在说经济全球化，它是一种潮流，对吧？哎，因为现在你看没有哪个国家真正的能够独立于现代经济全球化的。潮流之外啊，没有哪个国家能真正的独立，任何国家的发展对吧？你看或者说有一些，尤其是做这种进出口企业的，它更加依赖于这种经济的发展啊。啊，那么还有就是前面说的多边主义，它是解决世界面临困难挑战的必然选择。当有一些问题出现的时候，对吧？各个国家之间我们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 24520, "end_char": 24820, "line": 1, "excerpt": "是遭遇了四一二和七一五的反革命政变之后。啊，然后我们开始南昌对吧？哎，然后这个秋收起义和广州起义等等，他在这些起义最终结果都失败之后。想一想毛主席，他就转战到了井冈山，建立了井冈山革命根据地，然后由此提出了一个非常重要的革命时期的理论什么。农村包围城市武装夺取政权呀，对吧？他为什么提这个？就是因为毛主席当时意识到了。既然我们要让人民群众站在我们这边，对不对？那当时中国社会而言，我们最广大的人民群众就是谁同学们？那不就是在农村待着的农民吗？我们当时中国80%都是农民啊，同学们哎，所以你看我们扎根农村，取得了农民的广泛信任，就代表我们真正的走到了人民群众的心里。对不对？所以你看到最后我们在解放战争", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 6304, "end_char": 6604, "line": 1, "excerpt": "神。啊，就这三个方面，其实你主要联系前面就行了，也就是开天辟地，对不对？敢为人先首创嘛，毕竟红船精神是我们党创建的时候啊，创建的时候。然后紧接着后面其他的啊，像井冈山精神这个不做重点介绍啊啊，井冈山呢呃，这个我们之前强调的是在一九二七年还记得吗啊，秋收起义结束之后啊，然后呢？呃秋收起义最终的这个结果不是失败了吗？失败之后，然后啊，毛泽东同志带领着我们当时的起义队伍转战到井冈山，是不是哎？然后成立了井冈山根据地啊。好，这个大家知道，井冈山是我们的第一个革命根据地，其实就行了啊，然后它里面的这些内容简单，看看这个不做一个重点啊。然后往下。第二个重点呢，就是它看到了吗？同学们叫遵义会议精神啊，遵义会", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 4256, "end_char": 4314, "line": 1, "excerpt": "会当中，他说到的这么一个东西就是关于完善市场经济基础制度。这个当时我不知道有没有同学掉坑的，对吧？关于市场经济的基础", "policy_id": "FENGZE_POL_034", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11811, "end_char": 11912, "line": 1, "excerpt": "以经济体制改革为牵引，为什么是以经济体制改革为牵引？我刚才提到了一个问题，我没在书上写啊，你看我刚才说了，我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？", "policy_id": "FENGZE_POL_033", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15979, "end_char": 16069, "line": 1, "excerpt": "进一步全面深化改革的原则。啊，这个呢，大家听一听就行啊，虽然我们也给大家出题了，但是呢啊，不作为一个重点，为什么？因为从之前啊，我们呃，就是国省考它出题的这个内容上来看它很少。出这", "policy_id": "FENGZE_POL_032", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15837, "end_char": 15922, "line": 1, "excerpt": "错了呀？我们书上说的是建国80周年，对吧？哎，中华人民共和国建成80周年啊，所以在这里面注意啊。这道题选的是。b选项啊，也就是二和四错了啊，一个时间错了一个具体的表述错了", "policy_id": "FENGZE_POL_031", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15557, "end_char": 15857, "line": 1, "excerpt": "一体发展中特。啥意思呢？你看第一个党坚持党的领导，毕竟别的国家没有中国共产党的领导，对不对？哎，只有我们国家有，然后其次。人强调的是什么？强调的是后是后两个一个人类命运共同体，一个人类文明新形态，所以这是党人啊，然后按照五位一体同学们哪五位一体啊？看从这儿开始啊，第一个标一下经济是不是强调高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。紧接着，从这个社会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 56901, "end_char": 57201, "line": 1, "excerpt": "化是更基础，更广泛，更深厚的自信啊，它是最基本，最深沉，最持久的力量，明确它就行了啊。要不然的话，你想想同学们，你为什么现在习近平总书记在国际的讲话当中经常提叫人类命运共同体，对不对？他提这个东西啊，为什么很多人能信服？对不对？包括我们国家的很多的民众，你去向一些外国友人介绍这个东西的时候对不对？唉，你看你说我们现在正在创建人类命运共同体。你为什么能够很自信的把这个东西说出来，去向他介绍，不就是因为我们一直在说古代文化当中，中国一直在强调大同社会的理念，对吧？唉，这是古人就已经有的这样一种啊观念，我们只不过是现在把它拿出来了，对不对？唉，拿出来介绍给你，这就是中国古人的东西啊。所以你看最后他说", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 29255, "end_char": 29555, "line": 1, "excerpt": "？对不对？哎，所有的外交工作其实实际上都是为了啥呀？同学们。不就是为了主权，安全，发展利益嘛，对不对？哎，说了太多遍了啊，好了，然后紧接着往下同学们看第三个构建人类命运共同体的问题。这个人类命共同体这一块儿呢，大家可以看啊呃，首先啊，他提到了说这个构建人类命共同体呢，是当代中国共产党人回答和解决人类前途命运的时代之问的中国方案。哎，也是我们新时代对外工作的一个总目标，了解就行，同学们啊，了解就行，那么往下第一个啊，先明确构建人类命运共同体。它是世界各国人民的前途所在，那什么叫人类命运共同体啊？同学们记住这五个词要有印象啊。五个词强调，持久和平，普遍安全，共同繁荣，开放包容和清洁美丽。看到了吗？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 0, "end_char": 233, "line": 1, "excerpt": "14章节啊，我们的这个强大人民军队啊，所以如果之前没有跟着课的同学啊，今天呢呃，这个过来听课对吧？咱们把这个讲义啊打到第14章节好吧？好了，来看啊，在第14章节这一块儿呢，强调这个关于建设巩固国防和强大人民军队的问题。呃，那么今年呢？呃，针对于军队国防的这个问题呃，因为这个九三阅兵的问题是不是呃，所以呢，它呃会是我们在考试过程当中的一个重点内容。能理解吧，好，所以接下来啊啊，接下来我们来看一看啊，首先第一个就是关于这个军队建设，它对于我们的这个重要性在哪？那首先", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11443, "end_char": 11743, "line": 1, "excerpt": "域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没有说直接全部给你放开啊，所以这个时候你要保证一定的国家安全啊，因为你有很多行业，一旦啊，给它完全放开之后。它这个时候就会受到冲击，那就会就会出现这个问题，而最后一个就是我们一直在说的我们国家的经济体制，对吧？社会主义市场经济体制一方面要发挥市场的决定性作用，对不对？另外一个方面要发挥什么？发挥政府的宏观调控作用啊好，你看其实实际上你这样前后去对着去记，我感觉还是相对来说比较简单的，对不对？哎，还是比较简单的啊，哎呀，我非常我非常欣慰，我看到有一个同学说说，今天听着听着课好像开悟了，是不", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 46954, "end_char": 47254, "line": 1, "excerpt": "对不对哎？以国家公园为主体，然后三生道路，这不都是刚才说的吗？啊，好了，这是在这儿啊，第二题选的是c好吧嗯。然后紧接着同学们来往下看啊，往下看第13章维护和塑造国家安全啊，那么关于国家安全的问题啊，国家安全的问题来看啊来看。脑子塞不下了呀，塞不下也得塞，同学们啊，咱现在也不能下课，知道吧，还有半个小时呢啊，实在不行了，对吧，站起来啊。啊，那个拍拍自己的脸是不是如果感觉还不清醒，那就用点儿力啊，再不清醒再用点儿力是不是到最后你真的把自己？啪一下子对不对哎？就给打醒了，那个时候就行了啊，来吧，同学们先来看啊，总体国家安全观这一块，他说到的这个。坚持总体国家安全观。那安全观到底是什么？咱是不是得了解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 13225, "end_char": 13525, "line": 1, "excerpt": "后紧接着再往下第二个四体啊，我说了这个东西一般它不会挖坑，对不对哎？所以你大概读完之后没有什么错误的，你就默认它是对的就行了啊。紧接着再往下第二个二零二四年总体国家安全观提出十周年，是不是啊？同学们二零一四年啊，不是二零二四年啊，二零二四年。是不是啊？嗯，是不是啊？是呀，同学们嗯，哎呀。你回去啊，回去去看一看啊，回去去看一看，我们当时说的那个十周年是什么十周年，对吧？而我们当时明确给大家说的是二零一四年的时候，当时习近平总书记提出的。总体的国家安全观能理解吗？哎，然后他把二零呃，这个把那个4月15日哎，二四月十五日在二零一五年的时候，然后给他确定为了这个全民国家安全教育日。能理解吗？然后二五年", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15789, "end_char": 16089, "line": 1, "excerpt": "会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？经济，政治，文化，社会，生态文明，按照这个方向去思考，你也不用把这几句话完全背下来，对吧？唉，你也能知道他到底在说什么？然后紧接着发展中特儿就只剩最后一个了，中国特色社会主义对吧？唉，所以我们强调本质要求，强调的是党人按照五位一体发展中特儿。好吧，唉，按照这个去记就可以了啊，好了，这是本质要求，那么回过头来看下面第第三个问题就是重大原则啊。重大原则，这个东西呢，你注意，一般我们后面在讲到关于原则性的问题的时候，就是在实现中国式现代化的过程当中，这些东西是不能变", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 34913, "end_char": 35213, "line": 1, "excerpt": "一定要抓住这些题里面能够出题挖坑的点，然后去思考它有没有挖坑，对不对？有没有改啊？这是主要的。好，这是第二个啊，然后紧接着同学们往下咱们来看第12章建设社会主义生态文明啊，那么生态文明建设这一块呢，来看一下啊，第一个。说到他的地位，这个地位一定要记住的啊，生态文明建设是关系中华民族永续发展的根本大计啊，根本大计，你看你就直接记生根就行了，对吧？哎，正好和这个生态环境相关嘛。而且你直接去理解也行，同学们啊，为什么说生态文明它是永续发展的根本大计啊？其实很简单啊，我们之前多次给大家说到过，就是生态环境问题，它不仅仅关系的是我们一代人的问题，能理解吗？哎。它关系到的是我们子孙后代代代人的问题，所以在", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 4571, "end_char": 4871, "line": 1, "excerpt": "，你就要时刻的把人民放在心里，把国家放在心里啊。好了，这是在这儿啊，这个点就讲到这儿好吧，唉，多余的咱就不讲了啊，好，那紧接着往下来看啊，第三个就是关于社会主义核心价值观的问题了。这个点呢，我只能说它很重要，但是我们现在考试考的少，能理解吗？同学们啊，因为关于社会主义核心价值观的问题啊，我们在前些年的考试当中。啊，尤其是在很多事业单位考试当中啊，他把这个东西基本上考烂了啊，就直接问你啊，考的也非常简单，就直接问你说社会主义核心价值观，它在国家层面的表述是什么？同学们啊，其实就这12个词，你对应记清楚就行了，很简单，国家层面叫什么叫富强，民主，文明，和谐。啊，你多记多背几遍，其实这个马上啊就就记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 16554, "end_char": 16854, "line": 1, "excerpt": "这个情况之下，你看强化我们的内外联通啊，内外联通啊。啊，那内联外通啊，内联外通内联外通啊，好，这是在这儿啊，往下第四个弘扬核心价值，促进包容和谐，还有我们的这种核心价值观的问题啊。好了，这是在这儿，同学们，你看呃这几句话呢，你可以这样去记啊，叫依法内心啊，依法内心一强调的叫一国之本，对不对？哎，发强调高质量发展，高水平安全嘛。啊，然后内强调内廉外通对不对？新强调弘扬核心价值啊，所以在这一块的时候，同学们你注意啊，因为这这两句话说实话，它四句话加到一起比较长嘛，是不是？所以你就。啊，记一些关键词，把它能够记住就行了啊，所以叫一发内心啊，一发内心好，这是四条经验，那紧接着往下又对新一届的这个澳门特", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 53787, "end_char": 53894, "line": 1, "excerpt": "几章就是14，15，16和17讲完啊呃，我估计如果明天要能讲快点儿的话，没准儿明天能提前下课啊，同学们，因为后面剩下的这几章呢？呃，其实最重要的就是最后一章全面从严治党啊，其他那几个章节其实也不是特别的重要好吧哎。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34912, "end_char": 35212, "line": 1, "excerpt": "政策沟通设施连同贸易畅通，资金融通，民心相通啊，好，这是在这儿，所以这道题选的就是啥呀，选的就是b选项啊，选的就是b选项。好了，来，同学们往下来看。第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关，也就是我们常提的党建问题，对不对？哎，尤其是从我们啊这个习近平总书记开始啊。他一直在强调加强党的自身建设的这个问题啊，后期你看他还提出了自我革命这个跳出历史周期律的第二个答案，对不对？哎，那到底在新时代，我们应该如何？进行党的建设呢，对不对？来往下看啊，同学们，首先第一个他说到全面建设社会主义现代", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34986, "end_char": 35062, "line": 1, "excerpt": "第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关", "policy_id": "FENGZE_POL_030", "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 48717, "end_char": 49017, "line": 1, "excerpt": "是我们依法治国的主体，然后其次等国际强调等第三个法律面前人人平等，是不是在之前给大家说的我们？这个法律对不对？宪法的原则嘛啊？宪法的原则啊，然后国强调依法治国和以德治国相结合，最后记。从中国的实际出发，这就是我们全面依法治国的基本的原则。好吧，唉，基本的原则啊。好，那么这几个点前面两个一个党，一个人民其实就在强调这个呃，我们主体的问题是不是然后第三个强调的法律面前人人平等，也就是法律上我们的人际关系的问题？紧接着注意，后面他说的这个依法治国和以德治国的问题，给大家说一下啊，为什么在强调法治的时候，它还在强调叫以德治国的问题呢，同学们？其实很简单，你看法律这个东西啊，它是以这种就是成文的法规的形", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10003, "end_char": 10303, "line": 1, "excerpt": "先先看就是我们关和这个基本实现社会主义现代化相对应的，它是不是都带了一个基本？看到了吗？同学们，我们讲义当中有很多的内容，说基本实现四化，对吧？哎，基本实现啊，国家治理体系治理能力现代化基本建成法治国家法治政府法治社会。以及后面你看第六个啊和第七个啊，第七个它说美丽中国目标基本实现以及基本实现国防军队现代化，因为我们强调了。二零三五年的时候，它是不是要基本实现社会主义现代化呀？对不对哎？所以很多的目标前面它都带了一个基本。但是在这里面回过头来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 31725, "end_char": 32025, "line": 1, "excerpt": "社区治理，这里强调的一个点，一定要记住这个啊，包括大家之前学申论的时候应该也学过这个词，对不对？也就是最后一公里的问题啊，什么叫最后一公里啊，你看。说基层治理是国家治理的基石，城乡社区，这是关键啊，是社会治理最基本的单元。是党和政府联系服务群众的最后一公里，因为大家想呀，我们现在是不是很多的人啊？很多的人你是不是都。再不就是生活在我们乡村的农村，对不对？哎，或者说生活在城市的社区里面啊，你都是在这个里面，所以在这种情况之下啊，我们强调它是。党和政府联系服务群众的最后一公里，所以现在你看我们不是经常说嘛，要打通最后一公里对不对？哎，打通最后一公里啊，也就是在强调啥，要密切和人民群众之间的这种联系", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 35732, "end_char": 35822, "line": 1, "excerpt": "党的领导是人民当家作主和依法治国的根本保证，说了太多遍了吧，党的领导就是根本保证对吧，因为你想啊，同学们没有党的领导，我们会我们大家会使。实现人民当家作主吗？同学们会实现依法治国吗", "policy_id": "FENGZE_POL_029", "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 34155, "end_char": 34235, "line": 1, "excerpt": "主政治的本质属性就是全过程人民民主。啊，关于全过程人民民主这个词，我们一会儿会专门解释啊，大家先理解先知道这个词就行了，那么什么叫社会主义民主政治的本质属性呢？", "policy_id": "FENGZE_POL_028", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10225, "end_char": 10525, "line": 1, "excerpt": "来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强国，人才强国，文化强国，体育强国和健康中国。所以这两个比较特殊的，大家重点去记它，没带基本啊，没带基本好，那除了刚才给大家强调的，对吧？有一些带了基本有一些没带基本，那还有。一个考点非常重要的就是大家要把这六个国要记清楚，同学们，因为我们后面讲到政治理论的时候，经常会给大家强调，对吧？哎，教育强国呀啊，什么文化强国呀等等，这些什么时候建成呢？你看。我们强调，到二零三五年的时候，就要建成教育，科技，人才，文化，体育强国以及健康中国。那这个咋记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 14534, "end_char": 14834, "line": 1, "excerpt": "是啥呀？你既然想要让乡村振兴，你必须要坚持农业农村怎么样优先发展？这是很关键的，什么叫优先发展？同学们，比如说你要从资金的，对吧？这种配备上啊，资金的补充上，从人才的配备上，对不对？哎，从各种技术的这种支持上，你都要优先。去支持农业农村的发展，这才是我们强调的它的总方针。哎，好，那么来看第二个总要求是啥？总要求这几个词理解就行了，同学们也不要求大家去记了啊，因为也提了很早了。你看它的总要求是什么？你有没有发现其实这五个词也暗合了我们之前说到五位一体。对吧，你看一看同学们，咱们带着大家一起来看一下啊，说啥呢？第一个产业兴旺，是不是经济层面说的要产业兴旺，第二个生态宜居，那就是生态嘛。而乡风文明是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 7553, "end_char": 7853, "line": 1, "excerpt": "一个就是我们刚才说的军委主席的负责制，哎，把这两个点重点掌握就行了啊，二和三呢，这个理解就可以啊。好了，那么往下同学们第二个啊，关于这个政治建军改革强军科技强军人才强军和依法治军的这个问题。呃，这块儿呢，我先给大家说一下，就是过去它的一个发展啊，因为最早呢，我们提到这几个军的时候，其实没有这个人才强军。啊，然后过去的时候叫啥呢？叫科技兴军啊，科技兴军，所以过去提到这儿的时候，它强调的叫政治建军。改革强军，科技兴军，依法治军啊，但是你看现在我们把科技兴军改成了强军，对吧？哎，然后又多加了一个人才强军。唉，以及最后说的依法治军，所以现在变成五个了，这有一个改啊，改变了，那先来看第一个同学们政治建军", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10860, "end_char": 11160, "line": 1, "excerpt": "点，大家能够明确就行了，然后紧接着啊，和第二个本世纪中叶我们要实现的目标相对应的，有一个点同学们非常重要，我们后面也会讲到就是这个共识。同富裕看到了吗？哎，你看共同富裕的表述在这里面，哎，就不太一样了，因为我们刚才强调了，到二零三五年本世纪中叶的时候，我们的共同富裕要。应该按照正常来讲的话，它应该是基本实现共同富裕，对不对？但是你看他说的是取得更为明显的实质性进展。啊，而到本世纪中叶，他才强调全体人民共同富裕怎么样，基本实现这就是一个区别了，同学们。和大多数表述不一样的地方，是不是哎？所以同学们记住本共同富裕到什么时候才基本实现，是到本世纪中叶，为什么同学们？其实很简单啊，你想想共同富裕的实现", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11114, "end_char": 11414, "line": 1, "excerpt": "一大市场能理解吗？同学们唉，要建设我们全国的统一大市场啊，然后紧接着再往下，我们说到收入分配，那收入分配的咋样啊？现在是不是得？要公平啊，对不对？唉，我们之前讲共同富裕的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 20553, "end_char": 20853, "line": 1, "excerpt": "为我们在后面还会讲到一个地位和它有点像啊，两者有点像，所以先把它记住啊，收入分配是民生之源。是改善民生，实现发展成果由人民共享最重要最直接的方式分配制度，是促进共同富裕的基础性制度。那我们要来理解一下对不对我们国家现在的分配制度是什么样的？同学们，我们之前是不是在讲经济的时候，同学们还记得吗？唉，我们之前是在讲经济常识的时候，是不是给大家讲过关于我们国家的三次分配的这个问题，对不对？唉，三次分配的问题啊。好，那来看具体的这个收入分配到底怎么分配？初次再分配或第三次分配相协调的，这样的一个协调。协调配套的制度体系啊，那同学们来看一下啊，首先第一个它说要发挥初次分配的基础性作用。啊，因为大家想一想", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 46830, "end_char": 47130, "line": 1, "excerpt": "啊。截个图来a啊。好截个图啊，课下其实都会给大家发PPT的啊，大家可以直接看PPT，也更直观好不好嗯？来同学们那么往下来看啊，往下来看第一个完整准确全面的去贯彻新发展理念，新发展理念这一块呢，前面他先讲到了这个地位问题啊。地位问题这一块儿，他说到新发展理念是实现高质量发展的一个指导原则。一会儿，我们会重点去讲它啊，也就是到底什么是新发展理念。来看同学们第一个先理解我国进入新发展阶段啊，这块同学们所谓的新发展阶段不需要你背，你只需要理解就行了，我们过去考试的时候经常有这么一种说法，什么说法呢？他说了。我们的新发展阶段啊，是我们国家走出了社会主义初级阶段之后的一个阶段，同学们这个说法对不对？啊，同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11198, "end_char": 11498, "line": 1, "excerpt": "的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样要安全？因为你不能一味的开放，对不对？唉，我们国家在一些领域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 48951, "end_char": 49251, "line": 1, "excerpt": "决的是啥？解决的是保障问题啊。它是确保国家和民族行稳致远的一个坚强助石啊重点。其实记前面这个就行了，发展是动力，对不对？哎，安全是保障。啊，很简单呀，我们之前讲新发展理念，大家还记得吗？新发展理念当中，你看既然强调各个方面创新，协调，绿色，开放，共享，都是在强调如何发展的问题啊。包括习近平总书记之前也说过，这个点发展是解决一切问题的基础和关键，对不对？哎，那发展就是我们的动力啊，发展就是我们的动力。而安全呢？同学们，安全就是保障，对吧？唉，你看我们国家在当前最近这几十年，为什么能够发展的如此迅速？同学们不就是因为我们国家？这个环境是不是维持的非常安全，非常的稳定啊？对不对？唉，你看谁想谁敢对我", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 235, "end_char": 335, "line": 1, "excerpt": "以公有制为主体啊，因为书上有，所以这个呢，我就不写全了啊，大家有印象就行了，以公有制经济。为主体对不对唉？然后非公有制经济啊呃，这个共同发展，然后第二个也就是我们今天要给大家讲到的，强调按劳分配为主体", "policy_id": "FENGZE_POL_027", "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 7910, "end_char": 7980, "line": 3, "excerpt": "例15这道题选什么同学们啊？这道题选什么？直接打就行了啊，因为同学们，我这个我上这个政治理论课程的时候，我没有其他的教研老师帮助我发那个投票", "policy_id": "FENGZE_POL_026", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15702, "end_char": 15781, "line": 1, "excerpt": "高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。", "policy_id": "FENGZE_POL_025", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 119, "end_char": 209, "line": 1, "excerpt": "中国式现代化全面推进中华民族伟大复兴的这个问题啊。好了，来吧，同学们，今天晚上呢，咱们预计啊呃，讲到大概第六章结束啊，大家可以看一下你的讲义好吧嗯。好了啊，那先来看一下第一个问题，", "policy_id": "FENGZE_POL_024", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 17062, "end_char": 17362, "line": 1, "excerpt": "正和创新这个词说了很多遍了，是不是哎，守正有的一些东西是不能变的，像我们上上面提到的党的领导对吧，以人民为中心等等这些东西。都是不能变的，但是在发展的过程当中，必须坚持创新去带动发展好后面啊什么，还有就是效率和公平，因为你想。实现这种共同富裕，对吧？你要激发人民的这种效率啊啊，要让我们提升生产力，对不对？唉，但是同时还要强调什么？要注重公平，因为我们最后要实现共同富裕啊。那么，还有就是活力和秩序哎，你想想同学们这两个关系也很重要，对吧？唉，你想如果我们想要激发大家的活力，那你秩序上是不是可能稍微的就得放松一点儿？对吧哎，但是如果你秩序放的太松了，就你不管，那这个时候他可能太有活力了，同学们那就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 20661, "end_char": 20961, "line": 1, "excerpt": "理解也行好吗？同学们哎，直接去理解也行啊。那么，往下看，括号一教育是民族振兴，社会进步的基石，那怎么去发展教育？同学们，你看他说到啊，办好中国特色社会主义教育，必须坚持党对教育工作的全面领导。毋庸置疑，对不对？昨天刚讲到党是领导一切的啊，那必须坚持党的教育方针，我们党的教育方针是什么呢？大家可以看一下下面蓝色字体部分给大家拿出来的啊，这个了解就行，不用记同学们啊呃，我把这个划掉好吧，要不然有很多同学。容易引起误会啊，了解就行，你看他说教育必须以社会主义现代化建设服务，对吧？为人民服务必须以生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义阶。呃，社会主义建设者和接班人。唉，所以这个大家", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 19046, "end_char": 19346, "line": 1, "excerpt": "看我们书上具体是怎么表述的啊？好啊，稍微慢点儿是吧？好，稍微慢点儿啊，稍微慢点儿，首先第一个啊，我们在之前讲到关于党的领导的问题，给大家最讲呃，最刚开始的时候讲十个明确，不知道大家还记不记得啊？在讲十个明确的时候，那个时候我们强调第一个明确是不是明确中国特色社会主义最本质的特征是什么？是不是就是党的领导对吧？这也就是这个标题啊，其次它跟着是第二句话，也就是中国特色社会主义制度的最大优势是什么？同学们是不是也是党的领导啊？对吧？唉，那么。当时让大家记得叫本党是大党嘛，哎，本党是大党啊，那么除了这个之外，我们书上还说了两个比较特殊的，第一个强调党呢，是中国特色社会主义事业的坚强领导核心。啊，中国最", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 6243, "end_char": 6379, "line": 1, "excerpt": "关于两个结合的问题，那你得知道两个结合对吧？这里还是得需要你明确知道两个结合到底是啥的。两个结合，同学们来有没有同学记着的，之前我们说的两个结合是什么？它是经济工作吗？同学们，它是经济工作吗？不是唉，我们强调的两个结合与中国的传统文化相结合，与中国的具体实际相结合，对吧？", "policy_id": "FENGZE_POL_023", "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 13702, "end_char": 14002, "line": 3, "excerpt": "资本家通过个别劳动生产率来提高，然后实现的，所以它是个别上面那个是整个行业的社会劳动生产率。啊，好了，这是在这儿啊，就给大家讲这么些，那么往下同学们看第三个就是资本积累和资本的有机构成啊。资本积累这一块呢？先看第一个问题，也就是资本主义的再生产啊，资本主义再生产，说到资本家啊瓜分到剩余价值后，如果将其完全用于个人消费，则生产就在原有规模的基础上。重复进行，这叫资本主义的简单再生产。啥意思？同学们来给大家说个案例，大家就明确了啊，我刚才不是说了吗？我是100万投入，对不对？唉，然后我生产出来了150万的豆腐，我把它卖出去了啊，卖出去之后同学们这一段时间我生产出来的剩余价值有多少？是不是就花是就是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 41261, "end_char": 41561, "line": 1, "excerpt": "，那这种情况之下，它对于整个社会发展会起到一些延缓作用啊，那么同样的，当人口数量过少，同学们。其实他也不行哎，他也不行，因为那个时候对刚才有同学说了，那你就没有劳动力了，没劳动力你整个社会你怎么发展啊，对吧？哎，所以在这种情况之下啊，人口数量过多过少，其实都不行，要保持一个比较。适中的状态，那么再往下就是这个质量的问题了，同学们啊，人口质量这个最显然了，就是我们当然希望人口质量是越高越好了，对不对？唉，人口质量越高，它越能够促进社会的进步与发展。但是同样，如果人口质量哎，这个比较低的话，那它就会阻碍社会的发展啊，所以这个大家能理解就行，这就是第二个人口因素。第三个叫物质生产方式。注意同学们，这", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 4208, "end_char": 4508, "line": 1, "excerpt": "句话，我们把劳动资料和劳动对象二者合称为叫什么？合称为叫生产资料。所以你看同学们啊，我们现在是不是一直啊？我刚才也给大家说，就是我们在生产的过程当中，除了要投入劳动力之外，还要投入什么笼统的说，就是投入生产资料。啊，那两部分对不对？哎，一部分就是这个劳动资料，一部分就是劳动对象啊，好了，这是在这儿啊，我们给大家去。强调的这个问题啊，强调这个问题，那么来往下同学们看了解完了实体要素之后，紧接着再了解什么叫非实体？非实体要素呢，它主要包括的就是科学技术和经济管理等等，那尤其是科学技术，它的地位非常的重要，你看它说到了把这句话记住啊。科学技术，它是先进生产力的集中体现和主要标志。就记到这儿就行，同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 508, "end_char": 808, "line": 3, "excerpt": "所以来吧，同学们。这一节课啊，前半呃前半段的课程就带着大家去了解一下啊，大家之前所说的这种所谓的资本家到底是个什么东西？是不是哎？来看一下啊。首先，第一个先来看劳动力成为商品与货币转化为资本啊，那么劳动力成为商品，看它先说到了。资本主义经济制度是以资本家占有生产资料和以雇佣劳动为基础的经济制度。那么，资本主义雇佣劳动制度的形成，是以劳动力成为商品为前提的啥意思？同学们对吧？哎，掌握这个知识点啊，其实很好理解你，想一想，你既然要雇佣劳动。你是不是首先得有一个前提，就是这个劳动力，它必须是商品，对吧？如果它不是商品，你想想你怎么去雇佣劳动啊？你怎么花钱去雇佣他呀？对不对？唉，这就是一个字面意思上的", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 2721, "end_char": 3021, "line": 1, "excerpt": "时候会犯难啊，会犯难的，确实这个东西确实是很难的啊。你看，比如说像a选项，它不是问正确的吗？a说商品的价值量是由什么决定的？那肯定不是个别劳动时间决定的呀，它是社会必要劳动时间决定的啊，这个咱后面会讲。好吗？同学们哎，咱们这个具体知识点咱就不给大家解释了啊，然后往下b选项又说说货币的价值尺度，职能是通过实际的物质交换来实现的。同学们，首先你要知道什么叫价值尺度，是不是我用货币去衡量这个东西价值的多少啊？对吧？就这东西值多少钱？那你想想，我是通过实际的物质交换去实现的吗？同学们，我说这个商品值100块钱，我是通过实际的物质交换去那个实现的吗？不是，我就是跟他观念上我说了一下这个东西值100块钱。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 48219, "end_char": 48519, "line": 1, "excerpt": "的时间越多，那么我耗费的脑力和体力的量是不是就越多？能理解吗？同学们哎，所以啊，你看我们这个时候下面说了一个非常重要的知识点，就是商品的价值量是由生产商品的，叫社会必要劳动时间决定的。那注意了，这个社会必要劳动时间指的是啥呢？同学们，你看下面他说的这个概念，理解就可以了啊，指的是在社会现有的正常的生产条件下。在社会平均的劳动熟练程度和劳动强度下，制造某种使用价值所需要的劳动时间。那比如说看下面啊，同学们给大家拿了这么一个表格的案例，大家可以理解，这个你也不用记。在这个行业当中，假设有abcde五个厂商，他们是同时生产同一个商品的啊，那他们生产这个商品的时间包括方式方法都不一样a。生产一件商品用", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 1144, "end_char": 1444, "line": 3, "excerpt": "同学们也不需要你去掌握，你只需要理解就行了啊，知道劳动力的价值是用什么衡量出来的就可以了。那么，按照我们之前上一节课的思路说到，其实一个商品的价值是由这个商品的社会必要劳动时间所决定的，对不对？哎，那大家想一个问题。劳动力其实它指的是劳动者的一种工作能力，对不对？那这种工作能力你用这种社会必要劳动时间去决定，你怎么去衡量它呢？对吧，可能你会发现这个东西很难直接去衡量它，很抽象啊，那么在这里你看我们书上就给大家说了这样一个点。我们可以把这种社会必要劳动时间还原为生产出劳动者所消费的生活资料，所必须的社会必要劳动时间。啥意思啊？你这个劳动者对不对哎？你每天都要生活啊，你要生存下去，那我可以把生产和", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 4169, "end_char": 4256, "line": 3, "excerpt": "增值的价值，即剩余价值。看到了同学们这200块钱就是我们强调的叫剩余价值啊。所以你看他最后说到一旦货币所购买的劳动力带来了剩余价值，这个时候货币就不叫货币了，叫什么叫资本了？", "policy_id": "FENGZE_POL_022", "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 188, "end_char": 247, "line": 3, "excerpt": "商品的二因素，对吧？劳动的二重性以及商品价值量，它是由什么所决定的啊？价值规律等等，这些内容给大家做了一个简单的介绍。", "policy_id": "FENGZE_POL_021", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 46909, "end_char": 47209, "line": 1, "excerpt": "么往下最后一个，这个是稍微啊，需要大家还是费点儿脑子，要需要去理解一下的。你看他说的社会历史条件。啊，社会历史条件呢？强调的就是资本主义经济的高度发展和资本主义社会基本矛盾的充分暴露。啊，什么叫基本矛盾的充分暴露，对吧？是为什么资本主义经济又高度发展了？你考虑这个时期同学们。我们之前讲科技常识的时候，是不是给给大家讲过那个工业革命？还记得吗？同学们最早讲的在19世纪那个时候。工业革命，你想一想，那个就是我们之前说的那个第一次工业革命，对吧？哎，第一次工业革命，从呃18世纪，然后。就是末期的时候一直到19世纪，这个过程从一次工业革命，二次工业革命，对吧？唉，这个时间你看。借着这两次工业革命的东风", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 380, "end_char": 680, "line": 1, "excerpt": "就是。社会发展的基本规律看到了吗？啊，那么社会发展的基本规律是什么呢？大家要先明确这样一个问题，也就是我们书上第一段强调的啊，指的就是社会的基本矛盾运动。那么，社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个唉，这是第一个考点啊，同学们。那么，大家先来看这个词，为什么我们强调说这两个生产力，生产关系，经济基础和上层建筑的矛盾？它是属于叫社会的基本矛盾呢？大家要搞清楚啊，因为这种矛盾，它在任何的社会形态当中都是存在的。注意啊，在热任何的社会形态中都存在生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，那", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 4980, "end_char": 5280, "line": 1, "excerpt": "中啊，国外留学的过程当中，那个时候你看他接受到了我们所说到的就是这个共产党宣言的一些思想，对吧？也就是共产主义的一些思想。那这个过程当中好，为了能够让我们广大的人民群众都学习这种共产主义思想。所以啊，你看这就有一个翻译的人物，也就是陈望道就可以了啊，陈望道就可以了，好那么在这里面。记住它的翻译者是谁就可以了好吧，同学们唉，记住它就可以了啊。这个陈望道好。陈望道。作为翻译者，把它翻译成中文之后，那么它开始广泛的在我们中国去进行传播了啊，这个大家有个印象就可以了。我们之前的时候，习近平主席曾经说过一句话，说真理的味道是香甜的，对不对？唉，其实就是在说。陈王道，在翻译的过程当中啊，拿那个什么吃墨水儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 15689, "end_char": 15989, "line": 1, "excerpt": "哲学最为典型的马克思主义哲学，对吧？哎，我们国家的艺术当中一直强调哎要。深刻的啊，后面其实讲新思想，大家就知道了，要创作以人民为中心的这样的一种艺术形式，要创造人民群众喜闻乐见的这种啊，哎，这个形式对不对？哎，这就是你看从。从这儿，它所体现出来的，而宗教这个这咱就不说了，因为在中国，你会发现我们国家的这种宗教思想还是比较特殊的，对吧？哎，我们后面讲法律也会说我们国家信仰的是宗教自由。哎，宗教信仰自由，就是你可以信教，也可以不信，对不对？你可以信这个，也可以信那个，这都行啊，但是实际上呢，我们国家对于宗教其实保持着是一个相对来说啊，比较谨慎的态度，是不是？所以这个咱就不提不提了啊。那么，后面同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 42951, "end_char": 43251, "line": 3, "excerpt": "解决这个东西，对不对？哎，你不能说在实践过程当中啊，你说好这里面什么问题都没有，皆大欢喜对不对？这也不是啊，这也不应该这样，所以我们强调在实践过程当中一定要抓住人民群众有哪些问题，你要针对性的。去解决问题，对不对？所以呢，你看这个问题体现什么？是不是就体现我们之前讲的矛盾？它是普遍的，它是客观的呀。哎，你在这里，你就不能否认矛盾，它是普遍的，你一旦否认矛盾，矛盾的普遍性，想一想同学们是不是就认为什么？哎，之前还真有这样的一些案例啊，同学们。有的一些地方官员就认为，这个地方它就没有，就是我们这个地方它没有矛盾的存在啊，就认为啥万世太平对吧？唉，万世太平，那你想想同学们这个观点对吗？肯定是错的呀，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11864, "end_char": 11957, "line": 1, "excerpt": "我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？有同学说老师啥叫上层建筑没学？马哲对不对？哎，其实很简单，所谓的上层建筑就是改制度，改体系", "policy_id": "FENGZE_POL_020", "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 471, "end_char": 529, "line": 1, "excerpt": "生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个", "policy_id": "FENGZE_POL_019", "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 460, "end_char": 495, "line": 1, "excerpt": "社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾", "policy_id": "FENGZE_POL_018", "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 17648, "end_char": 17948, "line": 1, "excerpt": "，对不对？而第二次飞跃注意了，那就是从理性认识到实践的飞跃了，好吧嗯。这个也不多讲啊，大家知道这两次飞跃就可以了，那么紧接着往下来看，同学们啊，第二个认识过程的反复性和无限性。什么叫反复性？什么叫无限性呢？先来看第一个啊，反复性所谓反复性指的是认识过程啊，你看它指的是对一个复杂事物的认识。往往要经过由实践到认识，由认识到实践的多次反复才能完成。啥意思？同学们，你看比如说啊。大家通过这个课堂上接触了我，对不对？唉，接触了冯泽老师啊，那你是不是会对我形成一种感性认识啊？对不对，同学们？你会对我形成一种感性认识，对吧？唉，形成感性认识，但是你不要忘了同学们，人是最为复杂的生物，你知道我背地里啥样吗？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 9063, "end_char": 9363, "line": 1, "excerpt": "规律有哪些？首先，第一个强调认识的辩论过程啊，这个点上有首先第一个啊，虽然我没标红，但是你要知道这有个考点。认识的辩证过程是什么？就是第一句话，在实践基础上，由感性认识到理性认识，再由理性认识到实践的能动飞跃，这是一个。啊，也是容易出错的考点，同学们。怎么容易出出错呢？出错的点就在下面这块儿看到了吗？易错区分当中，我们在考试当中，他很喜欢在选项里面说认识的辩证过程是从实践到认识，再从认识到实践的过程。有很多同学这个知识点把握不准确，一看到这个说法，我的妈呀，这个说法可太正确了，对吧？没有比这个说法更正确的了。同学们，这个说法对吗？不对，因为你看我们书上已经强调了认识的辩证过程，强调的它是两次飞", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 6369, "end_char": 6444, "line": 1, "excerpt": "践是检验认识是否具有真理性的唯一标准。那么这个是啥意思？你看同学们，当我们在实践当中产生了某种认识之后，我们是希望能够用这种认识去改造世界的，对不对？", "policy_id": "FENGZE_POL_017", "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 650, "end_char": 743, "line": 1, "excerpt": "首先第一个强调实践是认识的来源。那这块儿同学们啊，我们之所以说它重要啊，另呃，其实从一个方面来说就是因为在实践决定认识这一块儿，刚才强调它是有四个方面的表现的。那你要学会去区分这四个方面", "policy_id": "FENGZE_POL_016", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 49276, "end_char": 49576, "line": 1, "excerpt": "分的你看学到最后，其实实际上。你区分非常简单，对吧？唉，区分非常简单啊。然后来往下把这个讲完，对吧？把矛盾这块儿讲完，然后咱们简单做个总结，咱们就下课啊呃，这个内因和外因这块儿就相当简单了啊，大家听一下就行了啊。你看，首先第一个他说了事物发展的动力和源泉就是事物的内部矛盾，哎，因为正是事物内部有矛盾嘛，所以我们的整个事物才会向前发展，我们在最初。讲到矛盾，也就是讲到对立统一的时候，你看他说了，他揭示了事物发展的什么源泉和动力，对吧？哎，因为事物内部它总有这种矛盾，矛盾的两个方面相互斗争啊，然后才促进了它的发展好，那么紧接着往下同学们。看所谓内因，指的就是事物的内部矛盾，而外因呢，同学们那就是事", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12382, "end_char": 12682, "line": 1, "excerpt": "人的出现去推翻当时的封建社会。你看他这句话说的是什么意思？就是封建社会到那个时期已经自我否定，对吧？他已经不行了。对，非常好，我看到有同学打了一个弹幕，就是因为内因他在事物的发展过程当中起决定作用，同学们，你看我们讲到这儿，前面的一些矛盾的观点是不是？已经深入到这里面了，对吧？已经串联起来了啊，内因是起决定作用的，整个封建社会已经腐朽，没落到一定的地步了。哎，所以我们不可否认啊，孙中山先生确实是非常伟大的，对不对？哎，但是换成比如说那个时候冯老师就在那个地方，对吧？我可能变换成孙中山。变成了冯中山，我就成为了大家历史课本上要学习的这个人物，是不是啊？那所以一定要注意啊他。它所谓的辩证的否定，就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 1816, "end_char": 2116, "line": 1, "excerpt": "说法，从哲学上那就是错的，唉，这不就是唯心的观点吗？对不对？唉。然后啊c选项说说矛盾的普遍性是矛盾的共性没问题啊，普遍的东西不就是共性的吗？对不对哎？那么矛盾的特殊性，它就是矛盾的个性，这没问题啊。所以这道题选的就是c啊，而4d选项当中说矛盾的普遍性和客观性决定了事物的不同性质，注意同学们。谁决定了事物的不同性质呢？其实是。这个点他说错了，同学们啊，我们在讲到呃这个事物性质的时候，哲学上强调主要矛盾的主要方面决定了。事物的不同性质，唉，主要矛盾的主要方面决定了事物的性质，但是如果你是从这个就是普遍性和特殊性的角度去考虑的话，那一定是特殊性，注意啊。特殊性，它决定了事物的不同性质，能理解吗？唉，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 31927, "end_char": 32227, "line": 1, "excerpt": "，其他的后面这个就不给大家讲了啊，因为后面这个呢，本身我们考试的时候它很少涉及啊，很少涉及。嗯，那么来往下同学们看第二个点啊，第二个点呢，我们在讲矛盾的普遍性和特殊性。看同学们，这就是我刚才为什么给大家讲说矛盾的基本属性，对吧？我们刚才讲的整个那个知识点是不是都在讲这个基本属性？矛盾的基本属性指的是矛盾的同一性和矛盾的斗争性。我解释了为什么这两个是它的基本属性啊？因为只要是矛盾，它就有同一就有斗争，所以它是基本的对不对哎？这是基本的属性。但你会发现，矛盾的普遍性和特殊性，这两个就不一样了，为什么？因为普遍性和特殊性看啊，它是矛盾问题的精髓，这是毛主席给的定义啊。它是矛盾问题的精髓。那么怎么理解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 37004, "end_char": 37304, "line": 1, "excerpt": "我为什么这么咬牙切齿，因为我们讲了对吧，就是原话呀，原话你还错，你想想同学们啊，这万一考试咋整啊？好，这是第二题啊，其他的都不用看了啊，都不用看了，就说什么矛盾特殊性，对吧？全面发展，按客规客观规律办事，你看这句话对吧？明者因时而变。智者随事而智，啥意思啊？就有智慧的人会根据实际情况的变化，然后去调整。能理解吧哎，去调整啊，然后做到什么做到哎，就像我们说的什么一切从实际出发呀，具体问题具体分析啊，这都行，所以a选项是不是把握了矛盾的特殊性？没问题吧，对不对哎？然后同样的，他在这里面强调提高创新思维活力，建立全面的发展观，同学们。后面人说了，根本途径在于创新，对吧？哎，所以你看在这里提高创新，其", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 15175, "end_char": 15475, "line": 1, "excerpt": "实质是什么？这个一定要记，因为考试的时候他就喜欢把这个实质和我们后面。学到的一个知识点的实质混淆一起啊，所以大家先把这个先记住啊，一会儿咱们再对比说发展的实质是新事物的产生和旧事物的灭亡。那问题来了，同学们。新事物的产生，旧事物的灭亡，什么叫新事物，什么叫旧事物呢？是不是按照我们平时的思维习惯去理解，说这个东西啊，你看比如说这个手机是我刚买的对吧？哎，今天下班儿没啥事儿，路过手机店发现哎，突然之间这个手机挺好看，我就新买了一个手机。啊，那这个就是新手机，那我之前的那个手机就是旧手机了，对吧？这是我们平时的理解，对不对？同学们，但是你要注意。在哲学上，我们不能用时间的先后去区分，而需要用什么去区", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12927, "end_char": 13227, "line": 1, "excerpt": "那这个点同学们，他容易怎么考？他很少直接去考，他会结合着我们前面讲到的一个知识点。看到了吗？也就是他会这样去说啊，在选项当中，他说a选项就这样的辩证否定的实质是新事物的产生和旧事物的灭亡，对吗？同学们。不对吧，哎，非常好，同学们有很多同学都知道这个是谁的实质，它是发展的实质呀，对不对？哎，发展的实质，所以我之前就讲到发展那个时候我就说了，我们很容易啊，他很喜欢在出题的时候把后面辩证否定的实质和它混合在一起。啊，要不然你看我为什么一直在说说哲学这个东西，其实你后期把它梳理完之后啊，你把它记住，有一些关键的知识点，你把它记住。记住之后你做题的时候非常好做，因为有些选项你打一眼儿一看对吧？哎，打眼儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 17011, "end_char": 17311, "line": 1, "excerpt": "一领域的，而哲学呢？是对这些的概括和总结，研究的是最普遍最一般的啊，所以在这里面。先搞清楚它啊，先搞清楚它那么来，同学们。看下面这个最为重要的点就是它二者之间的联系联系，说到具体科学是哲学的基础，而哲学给具体科学以世界观和方法论的指导。那么来同学们看啊，怎么去理解这个东西？为什么说具体科学是哲学的基础哲学，又给具体科学以世界观和方法论的指导呢？往下啊，我把这个白板清理一下，我给大家写一个案例啊。来吧，同学们，我们刚才是不是讲了很多的具体科学对吧？唉，你要结合我跟他大大家说的这些案例去理解啊，首先第一个比如说我们说物理学。那大家想一想，物理学之前我们讲物这个科技常识的时候讲过哪些物理知识啊？还记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 45862, "end_char": 46162, "line": 1, "excerpt": "不对？唉，那么我们就呃给大家解释一下这个规律，因为这也是我们考建考试的时候常见的一个考点啊。规律的含义了解就行，它说规律是事物本身所固有的本质的，必然的，稳定的联系。啊，那你看像比如说我们刚才提到的万有引力定律，是不是宇宙当中很多的这个事物都它都是遵循的，这个万有引力定律啊，对吧？哎，然后再比如说像我们讲到的牛顿的啊，三大运动定律啊，什么作用力反作用力对吧？惯性啊，惯性定律等等，类似于这个，你看这些它都是在事物。本身所固有的本质的必然的稳定的联系，对吧？唉，那这就是我们所说的这个规律啊，它是一种这个联系。那规律来看。下面是重点啊，规律，它具有客观性，什么是客观性啊，之前讲过了，对吧？客观性其实", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 564, "end_char": 864, "line": 1, "excerpt": "？我们在之前讲到形而上学的时候，其实给大家做了这样的一个呃，过去啊，就是在前两节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 9167, "end_char": 9238, "line": 1, "excerpt": "第三个否定之否定规律。否定之否定规定呢？它揭示的是事物发展的方向和道路。那么来看啊，所谓否定之否定，我们在语文上说双重否定是表肯定的，对不对？", "policy_id": "FENGZE_POL_015", "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 170, "end_char": 249, "line": 1, "excerpt": "这个第二个量变质变规律，那么量变质变规律这一块儿呢，大家看一下啊，首先呢，说到它揭示了事物发展的形势和状态。那么，具体它事物是以什么样的形式和状态去发展的呢？", "policy_id": "FENGZE_POL_014", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 41145, "end_char": 41235, "line": 1, "excerpt": "所谓的主要矛盾看书上标红的这句话就行了啊，这种居于支配地位对事物的发展过程起决定作用的矛盾就是什么？就是主要矛盾。啊，那反过来就好理解了呀，所谓的次要矛盾指的就是处于从属地位不起决", "policy_id": "FENGZE_POL_013", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 99, "end_char": 187, "line": 1, "excerpt": "是第三节的唯物辩证法，所以各位同学如果之前对吧呃，这个前两节课没跟到，包括可能有最近刚进来的各位同学啊。把政治理论的那本儿讲义打到咱们的第三节唯物辩证法，这个章节当中好不好嗯？", "policy_id": "FENGZE_POL_011", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 31909, "end_char": 32209, "line": 1, "excerpt": "一个缺陷。第二个缺陷就是我们刚才提到的形而上学性了，对吧？形而上学性这个词挺抽象，但是其实只需要你把握后面这三个词就行了。什么叫形而上选项？同学们，其实就是孤立静止和片面这三个观点。只要在某一个观点当中，它体现出这三个观点当中的任意一个，这是我给大家补充的啊。三者只要满足其一，就可以称之为叫形而上学性。啊，那这三个词都很好理解啊，孤立的静止的片面的对不对？好看下面我给大家举的这几个例子啊，首先第一个孤孤立的观点，比如说像我们之前做题的时候经常见到这么一句话叫什么？叫只见树木，不见森林，看到了吗？嗯，当有一整片森林在你眼前的时候，结果你只能看到一棵一棵的树，你并没有办法看到整个森林。那你看同学们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 8990, "end_char": 9290, "line": 1, "excerpt": "家思考这句话吧，这句话说的对不对呀？是不是是不是你看考虑所有的物质都是运动的，有同学说说老师，我咋这么不信呢，对吧？说的这么绝对，难道这个世界上就没有一些物质是静止状态的吗？啊，难道就没有一些物质，它是永恒静止状态呢？其实同学们，你要考虑。我就现在你想啊，你现在就想是宇宙当中有没有一种物质，就这种物质对吧？它就是永恒静止的状态，你想你想破脑袋，你都想不出来。同学们在宇宙当中有没有哪种物质？它是永恒静止的状态。是没有的唉，是没有的就哪怕像我们之前说的像你现在坐在这个椅子上，你没有动对吧？或者坐在床上没有动。那这个时候你看，随着地球在不断的进行自转和公转，你是不是一直在动，对吧？唉，所以在这种情况", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 603, "end_char": 903, "line": 1, "excerpt": "节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静止的，那么辩证法它强调的是事物都是永恒发展的。而形而上学，强调片面，那么在这里", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 33634, "end_char": 33934, "line": 1, "excerpt": "着往下来看，同学们这个比较重要的知识点啊，要记住的这几个点都要记住一二三四意识的能动作用。考的也非常多啊，什么叫意识的能动作用含义了解就行，他说也指的是意识的叫主观能动性啊。指的是意识能动的反映世界和通过实践改造世界的能力和作用啊，那这就是一种意识的能动性。那么，它的浓度性作用主要表现在下面四个点来看吧，哪四个点第一个点意识活动具有目的性和计划性？哎，什么意思啊？什么叫目的性计划性？其实目的和计划这两个大家都能理解，对吧？唉，也就是你带着什么目的？去想这个事情，比如说大家啊，你看你现在为什么在这学习啊？同学们，你是带着什么目的来的？你是带着要考上公务员儿的这个目的来的，对不对？唉，那这就是你看", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 5913, "end_char": 6213, "line": 1, "excerpt": "对？哎，那么在这种情况之下，大家注意人为事物的联系，有同学说都说人为了，那难道不是主观的吗？同学们。不是的啊，人为事物的联系，在你创造它的过程当中，可能确实有你主观能动性的发挥，对不对啊？因为你可以在四海报班儿，你也可以在其他的一些公司报班儿，对不对？这都可以。但是你要注意，一旦当你建立了这种联系之后，那这个联系它就是客观的，它就是不以人的意志为转移的。能理解吗？同学们哎，这种活动啊，这个这种联系是已经建立的啊，你不能说说啊，这个时候说你看说我感觉冯老师这不行了，对吧？我我不想再当你的学生了，那不好意思，也是一样的你你。因为我已经成为你的老师了，对吧？哪怕你后期换了个老师，再听这些课啊，那之前", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 39823, "end_char": 40123, "line": 1, "excerpt": "。所以主体是人，那紧接着往下，他又说了是人类怎么样叫能动的改造世界，什么叫能动的同学们？能动这个词，我们前面讲到意识的能动作用的时候，是不是给大家说了说发挥人的主观能动性，是不是哎？所以这个能动它，体现的就是我们的这种实践活动啊，是人一种有意识。有目的的活动。啊，这个能理解，就是人我们的实践活动是一种有意识，有目的的活动，比如说同学们像刚才给大家说的这个农民种地的活动，对吧？哎，农民种地的实践活动，你想一想。我在这块地上要种什么？农作物对不对？哎，是种玉米，是种水稻，是种小麦，你看首先我是有自己的主观意识的，对不对？以及我在种地的过程当中啊，可能我说了这块儿地啊，哎，我要把它分开种，对吧？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 25405, "end_char": 25705, "line": 1, "excerpt": "什么都回归到这个问题上，也就是思维与存在的关系问题。啊，所以后面我们才提到了这个问题，也就是哲学的基本问题是思维与存在的关系问题。那或者我们说另外一个点就是它是意识和物质的关系问题，这两个说哪个都可以知道吧？两种不同的表达啊，所以第一个考点需要记住的哲学基本问题是什么？啊，这是第一个考点，那么往下来看，关于哲学的基本问题，我们既然他提了，你是不是就得回答呀？对吧？唉，所以回答有两个方面啊，哪两个方面呢？第一个强调就是思维和存在何者为第一性的问题，而第二个方面强调的就是思维和存在是否具有同一性的问题。讲到这啊，有很多同学会很困惑，是不是什么是第一性，什么是同一性呢？来同学们啊。看我给大家做了一个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 41558, "end_char": 41858, "line": 1, "excerpt": "点儿，对不对？如果我没啥能力，那指导你，那可能就往一个坏的方向去发展了。啊好了，注意这三个就是比较容易错的说法就可以了好吧唉，好了，这是在这儿啊，第一个关于这个意识和物质的这个辩证关系。然后紧接着往下同学们看第二个就是它的方法论意义，方法论意义这一块儿，那么也很简单了，就是根据我们刚才说的。啊，这两个点第一个他说的是物质决定意识对不对？那既然物质决定意识有什么样的物质在我们的啊？这个精神当中才会有什么样的意识产生？所以你看他说了。我们要一切从实际出发，对吧？那一切从实际出发，他说到我们要按照事物的本来面貌去认识世界，在改造世界当中坚持实事求是。那啥意思啊？一切从实际出发，这还不简单吗？比如说同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 297, "end_char": 597, "line": 1, "excerpt": "这儿大家一定要认真听了啊。好实践与认识的辩证关系呢？其实大家会发现啊，如果你对于之前我们在讲唯物论那一块。嗯，还有印象的话，唯物论的辩证关系，他是不是也在讲关于物质和意识，二者之间的关系问题，对不对？唉，那么无非就是两个方面。哪两个方面，同学们首先第一个方面就是物质决定意识。对吧，这是第一个，然后第二个强调的是意识啊，反作用于物质，那么它有两个方面，一个强调的是哎，正确的去促进另外一个强调的就是。哎，这个错误的起阻碍，那么实际上你会发现实践与认识的辩证关系大体上来说也是这两个方面一个啊，强调的是决定作用，一个强调的是反作用。那么来看一下第一个实践决定认识我们在这里面讲到这个实践决定认识的时候，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 36502, "end_char": 36584, "line": 1, "excerpt": "做了最高的概括，指出客观实在性是物质的本质属性。同学们，你们有没有有没有发现就是马克思主义哲学和过去的两个古代朴素和近代形而上学？他认为物质的观点不太一样了，对吧？", "policy_id": "FENGZE_POL_010", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 38365, "end_char": 38447, "line": 1, "excerpt": "像旧唯物主义或者说庸俗唯物主义这样的一些说法。什么说法呢啊，什么下课呀，同学们到十点呢，哎呀，到十点了啊，好，那到底什么是旧唯物主义，什么叫庸俗唯物主义呢，同学们？", "policy_id": "FENGZE_POL_009", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26594, "end_char": 26663, "line": 1, "excerpt": "唯物主义之下还有什么古代朴素近代形，而上学是不是但是要注意我问的是基本的哲学派别。能理解吗？唉，基本的哲学派别只有唯物主义和唯心主义这两个", "policy_id": "FENGZE_POL_008", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26725, "end_char": 26757, "line": 1, "excerpt": "主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_007", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26976, "end_char": 27037, "line": 1, "excerpt": "为我们这个世界是能够被认知的，所以这就是一种典型的可知论的观点。能理解吧唉，然后第二种观点就是你认为思维不能够认识客观世界", "policy_id": "FENGZE_POL_006", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26642, "end_char": 26757, "line": 1, "excerpt": "基本的哲学派别只有唯物主义和唯心主义这两个，而我们所学的其他的很多非常细微的哲学理论，像我刚才提到的古代朴素唯物主义，对吧？近代形而上小唯物主义啊，马克思主义哲学以及主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_005", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx','political_theory','行测','政治理论','马克思主义基本原理','topic',1,1,'gongkao.xingce.political_theory.marx','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 13702, "end_char": 14002, "line": 3, "excerpt": "资本家通过个别劳动生产率来提高，然后实现的，所以它是个别上面那个是整个行业的社会劳动生产率。啊，好了，这是在这儿啊，就给大家讲这么些，那么往下同学们看第三个就是资本积累和资本的有机构成啊。资本积累这一块呢？先看第一个问题，也就是资本主义的再生产啊，资本主义再生产，说到资本家啊瓜分到剩余价值后，如果将其完全用于个人消费，则生产就在原有规模的基础上。重复进行，这叫资本主义的简单再生产。啥意思？同学们来给大家说个案例，大家就明确了啊，我刚才不是说了吗？我是100万投入，对不对？唉，然后我生产出来了150万的豆腐，我把它卖出去了啊，卖出去之后同学们这一段时间我生产出来的剩余价值有多少？是不是就花是就是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 41261, "end_char": 41561, "line": 1, "excerpt": "，那这种情况之下，它对于整个社会发展会起到一些延缓作用啊，那么同样的，当人口数量过少，同学们。其实他也不行哎，他也不行，因为那个时候对刚才有同学说了，那你就没有劳动力了，没劳动力你整个社会你怎么发展啊，对吧？哎，所以在这种情况之下啊，人口数量过多过少，其实都不行，要保持一个比较。适中的状态，那么再往下就是这个质量的问题了，同学们啊，人口质量这个最显然了，就是我们当然希望人口质量是越高越好了，对不对？唉，人口质量越高，它越能够促进社会的进步与发展。但是同样，如果人口质量哎，这个比较低的话，那它就会阻碍社会的发展啊，所以这个大家能理解就行，这就是第二个人口因素。第三个叫物质生产方式。注意同学们，这", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 4208, "end_char": 4508, "line": 1, "excerpt": "句话，我们把劳动资料和劳动对象二者合称为叫什么？合称为叫生产资料。所以你看同学们啊，我们现在是不是一直啊？我刚才也给大家说，就是我们在生产的过程当中，除了要投入劳动力之外，还要投入什么笼统的说，就是投入生产资料。啊，那两部分对不对？哎，一部分就是这个劳动资料，一部分就是劳动对象啊，好了，这是在这儿啊，我们给大家去。强调的这个问题啊，强调这个问题，那么来往下同学们看了解完了实体要素之后，紧接着再了解什么叫非实体？非实体要素呢，它主要包括的就是科学技术和经济管理等等，那尤其是科学技术，它的地位非常的重要，你看它说到了把这句话记住啊。科学技术，它是先进生产力的集中体现和主要标志。就记到这儿就行，同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 508, "end_char": 808, "line": 3, "excerpt": "所以来吧，同学们。这一节课啊，前半呃前半段的课程就带着大家去了解一下啊，大家之前所说的这种所谓的资本家到底是个什么东西？是不是哎？来看一下啊。首先，第一个先来看劳动力成为商品与货币转化为资本啊，那么劳动力成为商品，看它先说到了。资本主义经济制度是以资本家占有生产资料和以雇佣劳动为基础的经济制度。那么，资本主义雇佣劳动制度的形成，是以劳动力成为商品为前提的啥意思？同学们对吧？哎，掌握这个知识点啊，其实很好理解你，想一想，你既然要雇佣劳动。你是不是首先得有一个前提，就是这个劳动力，它必须是商品，对吧？如果它不是商品，你想想你怎么去雇佣劳动啊？你怎么花钱去雇佣他呀？对不对？唉，这就是一个字面意思上的", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 2721, "end_char": 3021, "line": 1, "excerpt": "时候会犯难啊，会犯难的，确实这个东西确实是很难的啊。你看，比如说像a选项，它不是问正确的吗？a说商品的价值量是由什么决定的？那肯定不是个别劳动时间决定的呀，它是社会必要劳动时间决定的啊，这个咱后面会讲。好吗？同学们哎，咱们这个具体知识点咱就不给大家解释了啊，然后往下b选项又说说货币的价值尺度，职能是通过实际的物质交换来实现的。同学们，首先你要知道什么叫价值尺度，是不是我用货币去衡量这个东西价值的多少啊？对吧？就这东西值多少钱？那你想想，我是通过实际的物质交换去实现的吗？同学们，我说这个商品值100块钱，我是通过实际的物质交换去那个实现的吗？不是，我就是跟他观念上我说了一下这个东西值100块钱。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 48219, "end_char": 48519, "line": 1, "excerpt": "的时间越多，那么我耗费的脑力和体力的量是不是就越多？能理解吗？同学们哎，所以啊，你看我们这个时候下面说了一个非常重要的知识点，就是商品的价值量是由生产商品的，叫社会必要劳动时间决定的。那注意了，这个社会必要劳动时间指的是啥呢？同学们，你看下面他说的这个概念，理解就可以了啊，指的是在社会现有的正常的生产条件下。在社会平均的劳动熟练程度和劳动强度下，制造某种使用价值所需要的劳动时间。那比如说看下面啊，同学们给大家拿了这么一个表格的案例，大家可以理解，这个你也不用记。在这个行业当中，假设有abcde五个厂商，他们是同时生产同一个商品的啊，那他们生产这个商品的时间包括方式方法都不一样a。生产一件商品用", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 1144, "end_char": 1444, "line": 3, "excerpt": "同学们也不需要你去掌握，你只需要理解就行了啊，知道劳动力的价值是用什么衡量出来的就可以了。那么，按照我们之前上一节课的思路说到，其实一个商品的价值是由这个商品的社会必要劳动时间所决定的，对不对？哎，那大家想一个问题。劳动力其实它指的是劳动者的一种工作能力，对不对？那这种工作能力你用这种社会必要劳动时间去决定，你怎么去衡量它呢？对吧，可能你会发现这个东西很难直接去衡量它，很抽象啊，那么在这里你看我们书上就给大家说了这样一个点。我们可以把这种社会必要劳动时间还原为生产出劳动者所消费的生活资料，所必须的社会必要劳动时间。啥意思啊？你这个劳动者对不对哎？你每天都要生活啊，你要生存下去，那我可以把生产和", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 4169, "end_char": 4256, "line": 3, "excerpt": "增值的价值，即剩余价值。看到了同学们这200块钱就是我们强调的叫剩余价值啊。所以你看他最后说到一旦货币所购买的劳动力带来了剩余价值，这个时候货币就不叫货币了，叫什么叫资本了？", "policy_id": "FENGZE_POL_022", "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 188, "end_char": 247, "line": 3, "excerpt": "商品的二因素，对吧？劳动的二重性以及商品价值量，它是由什么所决定的啊？价值规律等等，这些内容给大家做了一个简单的介绍。", "policy_id": "FENGZE_POL_021", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 46909, "end_char": 47209, "line": 1, "excerpt": "么往下最后一个，这个是稍微啊，需要大家还是费点儿脑子，要需要去理解一下的。你看他说的社会历史条件。啊，社会历史条件呢？强调的就是资本主义经济的高度发展和资本主义社会基本矛盾的充分暴露。啊，什么叫基本矛盾的充分暴露，对吧？是为什么资本主义经济又高度发展了？你考虑这个时期同学们。我们之前讲科技常识的时候，是不是给给大家讲过那个工业革命？还记得吗？同学们最早讲的在19世纪那个时候。工业革命，你想一想，那个就是我们之前说的那个第一次工业革命，对吧？哎，第一次工业革命，从呃18世纪，然后。就是末期的时候一直到19世纪，这个过程从一次工业革命，二次工业革命，对吧？唉，这个时间你看。借着这两次工业革命的东风", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 380, "end_char": 680, "line": 1, "excerpt": "就是。社会发展的基本规律看到了吗？啊，那么社会发展的基本规律是什么呢？大家要先明确这样一个问题，也就是我们书上第一段强调的啊，指的就是社会的基本矛盾运动。那么，社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个唉，这是第一个考点啊，同学们。那么，大家先来看这个词，为什么我们强调说这两个生产力，生产关系，经济基础和上层建筑的矛盾？它是属于叫社会的基本矛盾呢？大家要搞清楚啊，因为这种矛盾，它在任何的社会形态当中都是存在的。注意啊，在热任何的社会形态中都存在生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，那", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 4980, "end_char": 5280, "line": 1, "excerpt": "中啊，国外留学的过程当中，那个时候你看他接受到了我们所说到的就是这个共产党宣言的一些思想，对吧？也就是共产主义的一些思想。那这个过程当中好，为了能够让我们广大的人民群众都学习这种共产主义思想。所以啊，你看这就有一个翻译的人物，也就是陈望道就可以了啊，陈望道就可以了，好那么在这里面。记住它的翻译者是谁就可以了好吧，同学们唉，记住它就可以了啊。这个陈望道好。陈望道。作为翻译者，把它翻译成中文之后，那么它开始广泛的在我们中国去进行传播了啊，这个大家有个印象就可以了。我们之前的时候，习近平主席曾经说过一句话，说真理的味道是香甜的，对不对？唉，其实就是在说。陈王道，在翻译的过程当中啊，拿那个什么吃墨水儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 15689, "end_char": 15989, "line": 1, "excerpt": "哲学最为典型的马克思主义哲学，对吧？哎，我们国家的艺术当中一直强调哎要。深刻的啊，后面其实讲新思想，大家就知道了，要创作以人民为中心的这样的一种艺术形式，要创造人民群众喜闻乐见的这种啊，哎，这个形式对不对？哎，这就是你看从。从这儿，它所体现出来的，而宗教这个这咱就不说了，因为在中国，你会发现我们国家的这种宗教思想还是比较特殊的，对吧？哎，我们后面讲法律也会说我们国家信仰的是宗教自由。哎，宗教信仰自由，就是你可以信教，也可以不信，对不对？你可以信这个，也可以信那个，这都行啊，但是实际上呢，我们国家对于宗教其实保持着是一个相对来说啊，比较谨慎的态度，是不是？所以这个咱就不提不提了啊。那么，后面同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 42951, "end_char": 43251, "line": 3, "excerpt": "解决这个东西，对不对？哎，你不能说在实践过程当中啊，你说好这里面什么问题都没有，皆大欢喜对不对？这也不是啊，这也不应该这样，所以我们强调在实践过程当中一定要抓住人民群众有哪些问题，你要针对性的。去解决问题，对不对？所以呢，你看这个问题体现什么？是不是就体现我们之前讲的矛盾？它是普遍的，它是客观的呀。哎，你在这里，你就不能否认矛盾，它是普遍的，你一旦否认矛盾，矛盾的普遍性，想一想同学们是不是就认为什么？哎，之前还真有这样的一些案例啊，同学们。有的一些地方官员就认为，这个地方它就没有，就是我们这个地方它没有矛盾的存在啊，就认为啥万世太平对吧？唉，万世太平，那你想想同学们这个观点对吗？肯定是错的呀，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11864, "end_char": 11957, "line": 1, "excerpt": "我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？有同学说老师啥叫上层建筑没学？马哲对不对？哎，其实很简单，所谓的上层建筑就是改制度，改体系", "policy_id": "FENGZE_POL_020", "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 471, "end_char": 529, "line": 1, "excerpt": "生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个", "policy_id": "FENGZE_POL_019", "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 460, "end_char": 495, "line": 1, "excerpt": "社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾", "policy_id": "FENGZE_POL_018", "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 17648, "end_char": 17948, "line": 1, "excerpt": "，对不对？而第二次飞跃注意了，那就是从理性认识到实践的飞跃了，好吧嗯。这个也不多讲啊，大家知道这两次飞跃就可以了，那么紧接着往下来看，同学们啊，第二个认识过程的反复性和无限性。什么叫反复性？什么叫无限性呢？先来看第一个啊，反复性所谓反复性指的是认识过程啊，你看它指的是对一个复杂事物的认识。往往要经过由实践到认识，由认识到实践的多次反复才能完成。啥意思？同学们，你看比如说啊。大家通过这个课堂上接触了我，对不对？唉，接触了冯泽老师啊，那你是不是会对我形成一种感性认识啊？对不对，同学们？你会对我形成一种感性认识，对吧？唉，形成感性认识，但是你不要忘了同学们，人是最为复杂的生物，你知道我背地里啥样吗？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 9063, "end_char": 9363, "line": 1, "excerpt": "规律有哪些？首先，第一个强调认识的辩论过程啊，这个点上有首先第一个啊，虽然我没标红，但是你要知道这有个考点。认识的辩证过程是什么？就是第一句话，在实践基础上，由感性认识到理性认识，再由理性认识到实践的能动飞跃，这是一个。啊，也是容易出错的考点，同学们。怎么容易出出错呢？出错的点就在下面这块儿看到了吗？易错区分当中，我们在考试当中，他很喜欢在选项里面说认识的辩证过程是从实践到认识，再从认识到实践的过程。有很多同学这个知识点把握不准确，一看到这个说法，我的妈呀，这个说法可太正确了，对吧？没有比这个说法更正确的了。同学们，这个说法对吗？不对，因为你看我们书上已经强调了认识的辩证过程，强调的它是两次飞", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 6369, "end_char": 6444, "line": 1, "excerpt": "践是检验认识是否具有真理性的唯一标准。那么这个是啥意思？你看同学们，当我们在实践当中产生了某种认识之后，我们是希望能够用这种认识去改造世界的，对不对？", "policy_id": "FENGZE_POL_017", "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 650, "end_char": 743, "line": 1, "excerpt": "首先第一个强调实践是认识的来源。那这块儿同学们啊，我们之所以说它重要啊，另呃，其实从一个方面来说就是因为在实践决定认识这一块儿，刚才强调它是有四个方面的表现的。那你要学会去区分这四个方面", "policy_id": "FENGZE_POL_016", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 49276, "end_char": 49576, "line": 1, "excerpt": "分的你看学到最后，其实实际上。你区分非常简单，对吧？唉，区分非常简单啊。然后来往下把这个讲完，对吧？把矛盾这块儿讲完，然后咱们简单做个总结，咱们就下课啊呃，这个内因和外因这块儿就相当简单了啊，大家听一下就行了啊。你看，首先第一个他说了事物发展的动力和源泉就是事物的内部矛盾，哎，因为正是事物内部有矛盾嘛，所以我们的整个事物才会向前发展，我们在最初。讲到矛盾，也就是讲到对立统一的时候，你看他说了，他揭示了事物发展的什么源泉和动力，对吧？哎，因为事物内部它总有这种矛盾，矛盾的两个方面相互斗争啊，然后才促进了它的发展好，那么紧接着往下同学们。看所谓内因，指的就是事物的内部矛盾，而外因呢，同学们那就是事", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12382, "end_char": 12682, "line": 1, "excerpt": "人的出现去推翻当时的封建社会。你看他这句话说的是什么意思？就是封建社会到那个时期已经自我否定，对吧？他已经不行了。对，非常好，我看到有同学打了一个弹幕，就是因为内因他在事物的发展过程当中起决定作用，同学们，你看我们讲到这儿，前面的一些矛盾的观点是不是？已经深入到这里面了，对吧？已经串联起来了啊，内因是起决定作用的，整个封建社会已经腐朽，没落到一定的地步了。哎，所以我们不可否认啊，孙中山先生确实是非常伟大的，对不对？哎，但是换成比如说那个时候冯老师就在那个地方，对吧？我可能变换成孙中山。变成了冯中山，我就成为了大家历史课本上要学习的这个人物，是不是啊？那所以一定要注意啊他。它所谓的辩证的否定，就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 1816, "end_char": 2116, "line": 1, "excerpt": "说法，从哲学上那就是错的，唉，这不就是唯心的观点吗？对不对？唉。然后啊c选项说说矛盾的普遍性是矛盾的共性没问题啊，普遍的东西不就是共性的吗？对不对哎？那么矛盾的特殊性，它就是矛盾的个性，这没问题啊。所以这道题选的就是c啊，而4d选项当中说矛盾的普遍性和客观性决定了事物的不同性质，注意同学们。谁决定了事物的不同性质呢？其实是。这个点他说错了，同学们啊，我们在讲到呃这个事物性质的时候，哲学上强调主要矛盾的主要方面决定了。事物的不同性质，唉，主要矛盾的主要方面决定了事物的性质，但是如果你是从这个就是普遍性和特殊性的角度去考虑的话，那一定是特殊性，注意啊。特殊性，它决定了事物的不同性质，能理解吗？唉，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 31927, "end_char": 32227, "line": 1, "excerpt": "，其他的后面这个就不给大家讲了啊，因为后面这个呢，本身我们考试的时候它很少涉及啊，很少涉及。嗯，那么来往下同学们看第二个点啊，第二个点呢，我们在讲矛盾的普遍性和特殊性。看同学们，这就是我刚才为什么给大家讲说矛盾的基本属性，对吧？我们刚才讲的整个那个知识点是不是都在讲这个基本属性？矛盾的基本属性指的是矛盾的同一性和矛盾的斗争性。我解释了为什么这两个是它的基本属性啊？因为只要是矛盾，它就有同一就有斗争，所以它是基本的对不对哎？这是基本的属性。但你会发现，矛盾的普遍性和特殊性，这两个就不一样了，为什么？因为普遍性和特殊性看啊，它是矛盾问题的精髓，这是毛主席给的定义啊。它是矛盾问题的精髓。那么怎么理解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 37004, "end_char": 37304, "line": 1, "excerpt": "我为什么这么咬牙切齿，因为我们讲了对吧，就是原话呀，原话你还错，你想想同学们啊，这万一考试咋整啊？好，这是第二题啊，其他的都不用看了啊，都不用看了，就说什么矛盾特殊性，对吧？全面发展，按客规客观规律办事，你看这句话对吧？明者因时而变。智者随事而智，啥意思啊？就有智慧的人会根据实际情况的变化，然后去调整。能理解吧哎，去调整啊，然后做到什么做到哎，就像我们说的什么一切从实际出发呀，具体问题具体分析啊，这都行，所以a选项是不是把握了矛盾的特殊性？没问题吧，对不对哎？然后同样的，他在这里面强调提高创新思维活力，建立全面的发展观，同学们。后面人说了，根本途径在于创新，对吧？哎，所以你看在这里提高创新，其", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 15175, "end_char": 15475, "line": 1, "excerpt": "实质是什么？这个一定要记，因为考试的时候他就喜欢把这个实质和我们后面。学到的一个知识点的实质混淆一起啊，所以大家先把这个先记住啊，一会儿咱们再对比说发展的实质是新事物的产生和旧事物的灭亡。那问题来了，同学们。新事物的产生，旧事物的灭亡，什么叫新事物，什么叫旧事物呢？是不是按照我们平时的思维习惯去理解，说这个东西啊，你看比如说这个手机是我刚买的对吧？哎，今天下班儿没啥事儿，路过手机店发现哎，突然之间这个手机挺好看，我就新买了一个手机。啊，那这个就是新手机，那我之前的那个手机就是旧手机了，对吧？这是我们平时的理解，对不对？同学们，但是你要注意。在哲学上，我们不能用时间的先后去区分，而需要用什么去区", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12927, "end_char": 13227, "line": 1, "excerpt": "那这个点同学们，他容易怎么考？他很少直接去考，他会结合着我们前面讲到的一个知识点。看到了吗？也就是他会这样去说啊，在选项当中，他说a选项就这样的辩证否定的实质是新事物的产生和旧事物的灭亡，对吗？同学们。不对吧，哎，非常好，同学们有很多同学都知道这个是谁的实质，它是发展的实质呀，对不对？哎，发展的实质，所以我之前就讲到发展那个时候我就说了，我们很容易啊，他很喜欢在出题的时候把后面辩证否定的实质和它混合在一起。啊，要不然你看我为什么一直在说说哲学这个东西，其实你后期把它梳理完之后啊，你把它记住，有一些关键的知识点，你把它记住。记住之后你做题的时候非常好做，因为有些选项你打一眼儿一看对吧？哎，打眼儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 17011, "end_char": 17311, "line": 1, "excerpt": "一领域的，而哲学呢？是对这些的概括和总结，研究的是最普遍最一般的啊，所以在这里面。先搞清楚它啊，先搞清楚它那么来，同学们。看下面这个最为重要的点就是它二者之间的联系联系，说到具体科学是哲学的基础，而哲学给具体科学以世界观和方法论的指导。那么来同学们看啊，怎么去理解这个东西？为什么说具体科学是哲学的基础哲学，又给具体科学以世界观和方法论的指导呢？往下啊，我把这个白板清理一下，我给大家写一个案例啊。来吧，同学们，我们刚才是不是讲了很多的具体科学对吧？唉，你要结合我跟他大大家说的这些案例去理解啊，首先第一个比如说我们说物理学。那大家想一想，物理学之前我们讲物这个科技常识的时候讲过哪些物理知识啊？还记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 45862, "end_char": 46162, "line": 1, "excerpt": "不对？唉，那么我们就呃给大家解释一下这个规律，因为这也是我们考建考试的时候常见的一个考点啊。规律的含义了解就行，它说规律是事物本身所固有的本质的，必然的，稳定的联系。啊，那你看像比如说我们刚才提到的万有引力定律，是不是宇宙当中很多的这个事物都它都是遵循的，这个万有引力定律啊，对吧？哎，然后再比如说像我们讲到的牛顿的啊，三大运动定律啊，什么作用力反作用力对吧？惯性啊，惯性定律等等，类似于这个，你看这些它都是在事物。本身所固有的本质的必然的稳定的联系，对吧？唉，那这就是我们所说的这个规律啊，它是一种这个联系。那规律来看。下面是重点啊，规律，它具有客观性，什么是客观性啊，之前讲过了，对吧？客观性其实", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 564, "end_char": 864, "line": 1, "excerpt": "？我们在之前讲到形而上学的时候，其实给大家做了这样的一个呃，过去啊，就是在前两节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 9167, "end_char": 9238, "line": 1, "excerpt": "第三个否定之否定规律。否定之否定规定呢？它揭示的是事物发展的方向和道路。那么来看啊，所谓否定之否定，我们在语文上说双重否定是表肯定的，对不对？", "policy_id": "FENGZE_POL_015", "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 170, "end_char": 249, "line": 1, "excerpt": "这个第二个量变质变规律，那么量变质变规律这一块儿呢，大家看一下啊，首先呢，说到它揭示了事物发展的形势和状态。那么，具体它事物是以什么样的形式和状态去发展的呢？", "policy_id": "FENGZE_POL_014", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 41145, "end_char": 41235, "line": 1, "excerpt": "所谓的主要矛盾看书上标红的这句话就行了啊，这种居于支配地位对事物的发展过程起决定作用的矛盾就是什么？就是主要矛盾。啊，那反过来就好理解了呀，所谓的次要矛盾指的就是处于从属地位不起决", "policy_id": "FENGZE_POL_013", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 99, "end_char": 187, "line": 1, "excerpt": "是第三节的唯物辩证法，所以各位同学如果之前对吧呃，这个前两节课没跟到，包括可能有最近刚进来的各位同学啊。把政治理论的那本儿讲义打到咱们的第三节唯物辩证法，这个章节当中好不好嗯？", "policy_id": "FENGZE_POL_011", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 31909, "end_char": 32209, "line": 1, "excerpt": "一个缺陷。第二个缺陷就是我们刚才提到的形而上学性了，对吧？形而上学性这个词挺抽象，但是其实只需要你把握后面这三个词就行了。什么叫形而上选项？同学们，其实就是孤立静止和片面这三个观点。只要在某一个观点当中，它体现出这三个观点当中的任意一个，这是我给大家补充的啊。三者只要满足其一，就可以称之为叫形而上学性。啊，那这三个词都很好理解啊，孤立的静止的片面的对不对？好看下面我给大家举的这几个例子啊，首先第一个孤孤立的观点，比如说像我们之前做题的时候经常见到这么一句话叫什么？叫只见树木，不见森林，看到了吗？嗯，当有一整片森林在你眼前的时候，结果你只能看到一棵一棵的树，你并没有办法看到整个森林。那你看同学们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 8990, "end_char": 9290, "line": 1, "excerpt": "家思考这句话吧，这句话说的对不对呀？是不是是不是你看考虑所有的物质都是运动的，有同学说说老师，我咋这么不信呢，对吧？说的这么绝对，难道这个世界上就没有一些物质是静止状态的吗？啊，难道就没有一些物质，它是永恒静止状态呢？其实同学们，你要考虑。我就现在你想啊，你现在就想是宇宙当中有没有一种物质，就这种物质对吧？它就是永恒静止的状态，你想你想破脑袋，你都想不出来。同学们在宇宙当中有没有哪种物质？它是永恒静止的状态。是没有的唉，是没有的就哪怕像我们之前说的像你现在坐在这个椅子上，你没有动对吧？或者坐在床上没有动。那这个时候你看，随着地球在不断的进行自转和公转，你是不是一直在动，对吧？唉，所以在这种情况", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 603, "end_char": 903, "line": 1, "excerpt": "节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静止的，那么辩证法它强调的是事物都是永恒发展的。而形而上学，强调片面，那么在这里", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 33634, "end_char": 33934, "line": 1, "excerpt": "着往下来看，同学们这个比较重要的知识点啊，要记住的这几个点都要记住一二三四意识的能动作用。考的也非常多啊，什么叫意识的能动作用含义了解就行，他说也指的是意识的叫主观能动性啊。指的是意识能动的反映世界和通过实践改造世界的能力和作用啊，那这就是一种意识的能动性。那么，它的浓度性作用主要表现在下面四个点来看吧，哪四个点第一个点意识活动具有目的性和计划性？哎，什么意思啊？什么叫目的性计划性？其实目的和计划这两个大家都能理解，对吧？唉，也就是你带着什么目的？去想这个事情，比如说大家啊，你看你现在为什么在这学习啊？同学们，你是带着什么目的来的？你是带着要考上公务员儿的这个目的来的，对不对？唉，那这就是你看", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 5913, "end_char": 6213, "line": 1, "excerpt": "对？哎，那么在这种情况之下，大家注意人为事物的联系，有同学说都说人为了，那难道不是主观的吗？同学们。不是的啊，人为事物的联系，在你创造它的过程当中，可能确实有你主观能动性的发挥，对不对啊？因为你可以在四海报班儿，你也可以在其他的一些公司报班儿，对不对？这都可以。但是你要注意，一旦当你建立了这种联系之后，那这个联系它就是客观的，它就是不以人的意志为转移的。能理解吗？同学们哎，这种活动啊，这个这种联系是已经建立的啊，你不能说说啊，这个时候说你看说我感觉冯老师这不行了，对吧？我我不想再当你的学生了，那不好意思，也是一样的你你。因为我已经成为你的老师了，对吧？哪怕你后期换了个老师，再听这些课啊，那之前", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 39823, "end_char": 40123, "line": 1, "excerpt": "。所以主体是人，那紧接着往下，他又说了是人类怎么样叫能动的改造世界，什么叫能动的同学们？能动这个词，我们前面讲到意识的能动作用的时候，是不是给大家说了说发挥人的主观能动性，是不是哎？所以这个能动它，体现的就是我们的这种实践活动啊，是人一种有意识。有目的的活动。啊，这个能理解，就是人我们的实践活动是一种有意识，有目的的活动，比如说同学们像刚才给大家说的这个农民种地的活动，对吧？哎，农民种地的实践活动，你想一想。我在这块地上要种什么？农作物对不对？哎，是种玉米，是种水稻，是种小麦，你看首先我是有自己的主观意识的，对不对？以及我在种地的过程当中啊，可能我说了这块儿地啊，哎，我要把它分开种，对吧？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 25405, "end_char": 25705, "line": 1, "excerpt": "什么都回归到这个问题上，也就是思维与存在的关系问题。啊，所以后面我们才提到了这个问题，也就是哲学的基本问题是思维与存在的关系问题。那或者我们说另外一个点就是它是意识和物质的关系问题，这两个说哪个都可以知道吧？两种不同的表达啊，所以第一个考点需要记住的哲学基本问题是什么？啊，这是第一个考点，那么往下来看，关于哲学的基本问题，我们既然他提了，你是不是就得回答呀？对吧？唉，所以回答有两个方面啊，哪两个方面呢？第一个强调就是思维和存在何者为第一性的问题，而第二个方面强调的就是思维和存在是否具有同一性的问题。讲到这啊，有很多同学会很困惑，是不是什么是第一性，什么是同一性呢？来同学们啊。看我给大家做了一个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 41558, "end_char": 41858, "line": 1, "excerpt": "点儿，对不对？如果我没啥能力，那指导你，那可能就往一个坏的方向去发展了。啊好了，注意这三个就是比较容易错的说法就可以了好吧唉，好了，这是在这儿啊，第一个关于这个意识和物质的这个辩证关系。然后紧接着往下同学们看第二个就是它的方法论意义，方法论意义这一块儿，那么也很简单了，就是根据我们刚才说的。啊，这两个点第一个他说的是物质决定意识对不对？那既然物质决定意识有什么样的物质在我们的啊？这个精神当中才会有什么样的意识产生？所以你看他说了。我们要一切从实际出发，对吧？那一切从实际出发，他说到我们要按照事物的本来面貌去认识世界，在改造世界当中坚持实事求是。那啥意思啊？一切从实际出发，这还不简单吗？比如说同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 297, "end_char": 597, "line": 1, "excerpt": "这儿大家一定要认真听了啊。好实践与认识的辩证关系呢？其实大家会发现啊，如果你对于之前我们在讲唯物论那一块。嗯，还有印象的话，唯物论的辩证关系，他是不是也在讲关于物质和意识，二者之间的关系问题，对不对？唉，那么无非就是两个方面。哪两个方面，同学们首先第一个方面就是物质决定意识。对吧，这是第一个，然后第二个强调的是意识啊，反作用于物质，那么它有两个方面，一个强调的是哎，正确的去促进另外一个强调的就是。哎，这个错误的起阻碍，那么实际上你会发现实践与认识的辩证关系大体上来说也是这两个方面一个啊，强调的是决定作用，一个强调的是反作用。那么来看一下第一个实践决定认识我们在这里面讲到这个实践决定认识的时候，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 36502, "end_char": 36584, "line": 1, "excerpt": "做了最高的概括，指出客观实在性是物质的本质属性。同学们，你们有没有有没有发现就是马克思主义哲学和过去的两个古代朴素和近代形而上学？他认为物质的观点不太一样了，对吧？", "policy_id": "FENGZE_POL_010", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 38365, "end_char": 38447, "line": 1, "excerpt": "像旧唯物主义或者说庸俗唯物主义这样的一些说法。什么说法呢啊，什么下课呀，同学们到十点呢，哎呀，到十点了啊，好，那到底什么是旧唯物主义，什么叫庸俗唯物主义呢，同学们？", "policy_id": "FENGZE_POL_009", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26594, "end_char": 26663, "line": 1, "excerpt": "唯物主义之下还有什么古代朴素近代形，而上学是不是但是要注意我问的是基本的哲学派别。能理解吗？唉，基本的哲学派别只有唯物主义和唯心主义这两个", "policy_id": "FENGZE_POL_008", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26725, "end_char": 26757, "line": 1, "excerpt": "主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_007", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26976, "end_char": 27037, "line": 1, "excerpt": "为我们这个世界是能够被认知的，所以这就是一种典型的可知论的观点。能理解吧唉，然后第二种观点就是你认为思维不能够认识客观世界", "policy_id": "FENGZE_POL_006", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26642, "end_char": 26757, "line": 1, "excerpt": "基本的哲学派别只有唯物主义和唯心主义这两个，而我们所学的其他的很多非常细微的哲学理论，像我刚才提到的古代朴素唯物主义，对吧？近代形而上小唯物主义啊，马克思主义哲学以及主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_005", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought','political_theory','行测','政治理论','习近平新时代中国特色社会主义思想','topic',1,1,'gongkao.xingce.political_theory.thought','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15557, "end_char": 15857, "line": 1, "excerpt": "一体发展中特。啥意思呢？你看第一个党坚持党的领导，毕竟别的国家没有中国共产党的领导，对不对？哎，只有我们国家有，然后其次。人强调的是什么？强调的是后是后两个一个人类命运共同体，一个人类文明新形态，所以这是党人啊，然后按照五位一体同学们哪五位一体啊？看从这儿开始啊，第一个标一下经济是不是强调高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。紧接着，从这个社会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 56901, "end_char": 57201, "line": 1, "excerpt": "化是更基础，更广泛，更深厚的自信啊，它是最基本，最深沉，最持久的力量，明确它就行了啊。要不然的话，你想想同学们，你为什么现在习近平总书记在国际的讲话当中经常提叫人类命运共同体，对不对？他提这个东西啊，为什么很多人能信服？对不对？包括我们国家的很多的民众，你去向一些外国友人介绍这个东西的时候对不对？唉，你看你说我们现在正在创建人类命运共同体。你为什么能够很自信的把这个东西说出来，去向他介绍，不就是因为我们一直在说古代文化当中，中国一直在强调大同社会的理念，对吧？唉，这是古人就已经有的这样一种啊观念，我们只不过是现在把它拿出来了，对不对？唉，拿出来介绍给你，这就是中国古人的东西啊。所以你看最后他说", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 29255, "end_char": 29555, "line": 1, "excerpt": "？对不对？哎，所有的外交工作其实实际上都是为了啥呀？同学们。不就是为了主权，安全，发展利益嘛，对不对？哎，说了太多遍了啊，好了，然后紧接着往下同学们看第三个构建人类命运共同体的问题。这个人类命共同体这一块儿呢，大家可以看啊呃，首先啊，他提到了说这个构建人类命共同体呢，是当代中国共产党人回答和解决人类前途命运的时代之问的中国方案。哎，也是我们新时代对外工作的一个总目标，了解就行，同学们啊，了解就行，那么往下第一个啊，先明确构建人类命运共同体。它是世界各国人民的前途所在，那什么叫人类命运共同体啊？同学们记住这五个词要有印象啊。五个词强调，持久和平，普遍安全，共同繁荣，开放包容和清洁美丽。看到了吗？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 0, "end_char": 233, "line": 1, "excerpt": "14章节啊，我们的这个强大人民军队啊，所以如果之前没有跟着课的同学啊，今天呢呃，这个过来听课对吧？咱们把这个讲义啊打到第14章节好吧？好了，来看啊，在第14章节这一块儿呢，强调这个关于建设巩固国防和强大人民军队的问题。呃，那么今年呢？呃，针对于军队国防的这个问题呃，因为这个九三阅兵的问题是不是呃，所以呢，它呃会是我们在考试过程当中的一个重点内容。能理解吧，好，所以接下来啊啊，接下来我们来看一看啊，首先第一个就是关于这个军队建设，它对于我们的这个重要性在哪？那首先", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11443, "end_char": 11743, "line": 1, "excerpt": "域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没有说直接全部给你放开啊，所以这个时候你要保证一定的国家安全啊，因为你有很多行业，一旦啊，给它完全放开之后。它这个时候就会受到冲击，那就会就会出现这个问题，而最后一个就是我们一直在说的我们国家的经济体制，对吧？社会主义市场经济体制一方面要发挥市场的决定性作用，对不对？另外一个方面要发挥什么？发挥政府的宏观调控作用啊好，你看其实实际上你这样前后去对着去记，我感觉还是相对来说比较简单的，对不对？哎，还是比较简单的啊，哎呀，我非常我非常欣慰，我看到有一个同学说说，今天听着听着课好像开悟了，是不", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 46954, "end_char": 47254, "line": 1, "excerpt": "对不对哎？以国家公园为主体，然后三生道路，这不都是刚才说的吗？啊，好了，这是在这儿啊，第二题选的是c好吧嗯。然后紧接着同学们来往下看啊，往下看第13章维护和塑造国家安全啊，那么关于国家安全的问题啊，国家安全的问题来看啊来看。脑子塞不下了呀，塞不下也得塞，同学们啊，咱现在也不能下课，知道吧，还有半个小时呢啊，实在不行了，对吧，站起来啊。啊，那个拍拍自己的脸是不是如果感觉还不清醒，那就用点儿力啊，再不清醒再用点儿力是不是到最后你真的把自己？啪一下子对不对哎？就给打醒了，那个时候就行了啊，来吧，同学们先来看啊，总体国家安全观这一块，他说到的这个。坚持总体国家安全观。那安全观到底是什么？咱是不是得了解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 13225, "end_char": 13525, "line": 1, "excerpt": "后紧接着再往下第二个四体啊，我说了这个东西一般它不会挖坑，对不对哎？所以你大概读完之后没有什么错误的，你就默认它是对的就行了啊。紧接着再往下第二个二零二四年总体国家安全观提出十周年，是不是啊？同学们二零一四年啊，不是二零二四年啊，二零二四年。是不是啊？嗯，是不是啊？是呀，同学们嗯，哎呀。你回去啊，回去去看一看啊，回去去看一看，我们当时说的那个十周年是什么十周年，对吧？而我们当时明确给大家说的是二零一四年的时候，当时习近平总书记提出的。总体的国家安全观能理解吗？哎，然后他把二零呃，这个把那个4月15日哎，二四月十五日在二零一五年的时候，然后给他确定为了这个全民国家安全教育日。能理解吗？然后二五年", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15789, "end_char": 16089, "line": 1, "excerpt": "会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？经济，政治，文化，社会，生态文明，按照这个方向去思考，你也不用把这几句话完全背下来，对吧？唉，你也能知道他到底在说什么？然后紧接着发展中特儿就只剩最后一个了，中国特色社会主义对吧？唉，所以我们强调本质要求，强调的是党人按照五位一体发展中特儿。好吧，唉，按照这个去记就可以了啊，好了，这是本质要求，那么回过头来看下面第第三个问题就是重大原则啊。重大原则，这个东西呢，你注意，一般我们后面在讲到关于原则性的问题的时候，就是在实现中国式现代化的过程当中，这些东西是不能变", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 34913, "end_char": 35213, "line": 1, "excerpt": "一定要抓住这些题里面能够出题挖坑的点，然后去思考它有没有挖坑，对不对？有没有改啊？这是主要的。好，这是第二个啊，然后紧接着同学们往下咱们来看第12章建设社会主义生态文明啊，那么生态文明建设这一块呢，来看一下啊，第一个。说到他的地位，这个地位一定要记住的啊，生态文明建设是关系中华民族永续发展的根本大计啊，根本大计，你看你就直接记生根就行了，对吧？哎，正好和这个生态环境相关嘛。而且你直接去理解也行，同学们啊，为什么说生态文明它是永续发展的根本大计啊？其实很简单啊，我们之前多次给大家说到过，就是生态环境问题，它不仅仅关系的是我们一代人的问题，能理解吗？哎。它关系到的是我们子孙后代代代人的问题，所以在", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 4571, "end_char": 4871, "line": 1, "excerpt": "，你就要时刻的把人民放在心里，把国家放在心里啊。好了，这是在这儿啊，这个点就讲到这儿好吧，唉，多余的咱就不讲了啊，好，那紧接着往下来看啊，第三个就是关于社会主义核心价值观的问题了。这个点呢，我只能说它很重要，但是我们现在考试考的少，能理解吗？同学们啊，因为关于社会主义核心价值观的问题啊，我们在前些年的考试当中。啊，尤其是在很多事业单位考试当中啊，他把这个东西基本上考烂了啊，就直接问你啊，考的也非常简单，就直接问你说社会主义核心价值观，它在国家层面的表述是什么？同学们啊，其实就这12个词，你对应记清楚就行了，很简单，国家层面叫什么叫富强，民主，文明，和谐。啊，你多记多背几遍，其实这个马上啊就就记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 16554, "end_char": 16854, "line": 1, "excerpt": "这个情况之下，你看强化我们的内外联通啊，内外联通啊。啊，那内联外通啊，内联外通内联外通啊，好，这是在这儿啊，往下第四个弘扬核心价值，促进包容和谐，还有我们的这种核心价值观的问题啊。好了，这是在这儿，同学们，你看呃这几句话呢，你可以这样去记啊，叫依法内心啊，依法内心一强调的叫一国之本，对不对？哎，发强调高质量发展，高水平安全嘛。啊，然后内强调内廉外通对不对？新强调弘扬核心价值啊，所以在这一块的时候，同学们你注意啊，因为这这两句话说实话，它四句话加到一起比较长嘛，是不是？所以你就。啊，记一些关键词，把它能够记住就行了啊，所以叫一发内心啊，一发内心好，这是四条经验，那紧接着往下又对新一届的这个澳门特", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 53787, "end_char": 53894, "line": 1, "excerpt": "几章就是14，15，16和17讲完啊呃，我估计如果明天要能讲快点儿的话，没准儿明天能提前下课啊，同学们，因为后面剩下的这几章呢？呃，其实最重要的就是最后一章全面从严治党啊，其他那几个章节其实也不是特别的重要好吧哎。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34912, "end_char": 35212, "line": 1, "excerpt": "政策沟通设施连同贸易畅通，资金融通，民心相通啊，好，这是在这儿，所以这道题选的就是啥呀，选的就是b选项啊，选的就是b选项。好了，来，同学们往下来看。第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关，也就是我们常提的党建问题，对不对？哎，尤其是从我们啊这个习近平总书记开始啊。他一直在强调加强党的自身建设的这个问题啊，后期你看他还提出了自我革命这个跳出历史周期律的第二个答案，对不对？哎，那到底在新时代，我们应该如何？进行党的建设呢，对不对？来往下看啊，同学们，首先第一个他说到全面建设社会主义现代", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34986, "end_char": 35062, "line": 1, "excerpt": "第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关", "policy_id": "FENGZE_POL_030", "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 48717, "end_char": 49017, "line": 1, "excerpt": "是我们依法治国的主体，然后其次等国际强调等第三个法律面前人人平等，是不是在之前给大家说的我们？这个法律对不对？宪法的原则嘛啊？宪法的原则啊，然后国强调依法治国和以德治国相结合，最后记。从中国的实际出发，这就是我们全面依法治国的基本的原则。好吧，唉，基本的原则啊。好，那么这几个点前面两个一个党，一个人民其实就在强调这个呃，我们主体的问题是不是然后第三个强调的法律面前人人平等，也就是法律上我们的人际关系的问题？紧接着注意，后面他说的这个依法治国和以德治国的问题，给大家说一下啊，为什么在强调法治的时候，它还在强调叫以德治国的问题呢，同学们？其实很简单，你看法律这个东西啊，它是以这种就是成文的法规的形", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10003, "end_char": 10303, "line": 1, "excerpt": "先先看就是我们关和这个基本实现社会主义现代化相对应的，它是不是都带了一个基本？看到了吗？同学们，我们讲义当中有很多的内容，说基本实现四化，对吧？哎，基本实现啊，国家治理体系治理能力现代化基本建成法治国家法治政府法治社会。以及后面你看第六个啊和第七个啊，第七个它说美丽中国目标基本实现以及基本实现国防军队现代化，因为我们强调了。二零三五年的时候，它是不是要基本实现社会主义现代化呀？对不对哎？所以很多的目标前面它都带了一个基本。但是在这里面回过头来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 31725, "end_char": 32025, "line": 1, "excerpt": "社区治理，这里强调的一个点，一定要记住这个啊，包括大家之前学申论的时候应该也学过这个词，对不对？也就是最后一公里的问题啊，什么叫最后一公里啊，你看。说基层治理是国家治理的基石，城乡社区，这是关键啊，是社会治理最基本的单元。是党和政府联系服务群众的最后一公里，因为大家想呀，我们现在是不是很多的人啊？很多的人你是不是都。再不就是生活在我们乡村的农村，对不对？哎，或者说生活在城市的社区里面啊，你都是在这个里面，所以在这种情况之下啊，我们强调它是。党和政府联系服务群众的最后一公里，所以现在你看我们不是经常说嘛，要打通最后一公里对不对？哎，打通最后一公里啊，也就是在强调啥，要密切和人民群众之间的这种联系", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 35732, "end_char": 35822, "line": 1, "excerpt": "党的领导是人民当家作主和依法治国的根本保证，说了太多遍了吧，党的领导就是根本保证对吧，因为你想啊，同学们没有党的领导，我们会我们大家会使。实现人民当家作主吗？同学们会实现依法治国吗", "policy_id": "FENGZE_POL_029", "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 34155, "end_char": 34235, "line": 1, "excerpt": "主政治的本质属性就是全过程人民民主。啊，关于全过程人民民主这个词，我们一会儿会专门解释啊，大家先理解先知道这个词就行了，那么什么叫社会主义民主政治的本质属性呢？", "policy_id": "FENGZE_POL_028", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10225, "end_char": 10525, "line": 1, "excerpt": "来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强国，人才强国，文化强国，体育强国和健康中国。所以这两个比较特殊的，大家重点去记它，没带基本啊，没带基本好，那除了刚才给大家强调的，对吧？有一些带了基本有一些没带基本，那还有。一个考点非常重要的就是大家要把这六个国要记清楚，同学们，因为我们后面讲到政治理论的时候，经常会给大家强调，对吧？哎，教育强国呀啊，什么文化强国呀等等，这些什么时候建成呢？你看。我们强调，到二零三五年的时候，就要建成教育，科技，人才，文化，体育强国以及健康中国。那这个咋记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 14534, "end_char": 14834, "line": 1, "excerpt": "是啥呀？你既然想要让乡村振兴，你必须要坚持农业农村怎么样优先发展？这是很关键的，什么叫优先发展？同学们，比如说你要从资金的，对吧？这种配备上啊，资金的补充上，从人才的配备上，对不对？哎，从各种技术的这种支持上，你都要优先。去支持农业农村的发展，这才是我们强调的它的总方针。哎，好，那么来看第二个总要求是啥？总要求这几个词理解就行了，同学们也不要求大家去记了啊，因为也提了很早了。你看它的总要求是什么？你有没有发现其实这五个词也暗合了我们之前说到五位一体。对吧，你看一看同学们，咱们带着大家一起来看一下啊，说啥呢？第一个产业兴旺，是不是经济层面说的要产业兴旺，第二个生态宜居，那就是生态嘛。而乡风文明是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 7553, "end_char": 7853, "line": 1, "excerpt": "一个就是我们刚才说的军委主席的负责制，哎，把这两个点重点掌握就行了啊，二和三呢，这个理解就可以啊。好了，那么往下同学们第二个啊，关于这个政治建军改革强军科技强军人才强军和依法治军的这个问题。呃，这块儿呢，我先给大家说一下，就是过去它的一个发展啊，因为最早呢，我们提到这几个军的时候，其实没有这个人才强军。啊，然后过去的时候叫啥呢？叫科技兴军啊，科技兴军，所以过去提到这儿的时候，它强调的叫政治建军。改革强军，科技兴军，依法治军啊，但是你看现在我们把科技兴军改成了强军，对吧？哎，然后又多加了一个人才强军。唉，以及最后说的依法治军，所以现在变成五个了，这有一个改啊，改变了，那先来看第一个同学们政治建军", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10860, "end_char": 11160, "line": 1, "excerpt": "点，大家能够明确就行了，然后紧接着啊，和第二个本世纪中叶我们要实现的目标相对应的，有一个点同学们非常重要，我们后面也会讲到就是这个共识。同富裕看到了吗？哎，你看共同富裕的表述在这里面，哎，就不太一样了，因为我们刚才强调了，到二零三五年本世纪中叶的时候，我们的共同富裕要。应该按照正常来讲的话，它应该是基本实现共同富裕，对不对？但是你看他说的是取得更为明显的实质性进展。啊，而到本世纪中叶，他才强调全体人民共同富裕怎么样，基本实现这就是一个区别了，同学们。和大多数表述不一样的地方，是不是哎？所以同学们记住本共同富裕到什么时候才基本实现，是到本世纪中叶，为什么同学们？其实很简单啊，你想想共同富裕的实现", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11114, "end_char": 11414, "line": 1, "excerpt": "一大市场能理解吗？同学们唉，要建设我们全国的统一大市场啊，然后紧接着再往下，我们说到收入分配，那收入分配的咋样啊？现在是不是得？要公平啊，对不对？唉，我们之前讲共同富裕的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 20553, "end_char": 20853, "line": 1, "excerpt": "为我们在后面还会讲到一个地位和它有点像啊，两者有点像，所以先把它记住啊，收入分配是民生之源。是改善民生，实现发展成果由人民共享最重要最直接的方式分配制度，是促进共同富裕的基础性制度。那我们要来理解一下对不对我们国家现在的分配制度是什么样的？同学们，我们之前是不是在讲经济的时候，同学们还记得吗？唉，我们之前是在讲经济常识的时候，是不是给大家讲过关于我们国家的三次分配的这个问题，对不对？唉，三次分配的问题啊。好，那来看具体的这个收入分配到底怎么分配？初次再分配或第三次分配相协调的，这样的一个协调。协调配套的制度体系啊，那同学们来看一下啊，首先第一个它说要发挥初次分配的基础性作用。啊，因为大家想一想", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 46830, "end_char": 47130, "line": 1, "excerpt": "啊。截个图来a啊。好截个图啊，课下其实都会给大家发PPT的啊，大家可以直接看PPT，也更直观好不好嗯？来同学们那么往下来看啊，往下来看第一个完整准确全面的去贯彻新发展理念，新发展理念这一块呢，前面他先讲到了这个地位问题啊。地位问题这一块儿，他说到新发展理念是实现高质量发展的一个指导原则。一会儿，我们会重点去讲它啊，也就是到底什么是新发展理念。来看同学们第一个先理解我国进入新发展阶段啊，这块同学们所谓的新发展阶段不需要你背，你只需要理解就行了，我们过去考试的时候经常有这么一种说法，什么说法呢？他说了。我们的新发展阶段啊，是我们国家走出了社会主义初级阶段之后的一个阶段，同学们这个说法对不对？啊，同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11198, "end_char": 11498, "line": 1, "excerpt": "的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样要安全？因为你不能一味的开放，对不对？唉，我们国家在一些领域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 48951, "end_char": 49251, "line": 1, "excerpt": "决的是啥？解决的是保障问题啊。它是确保国家和民族行稳致远的一个坚强助石啊重点。其实记前面这个就行了，发展是动力，对不对？哎，安全是保障。啊，很简单呀，我们之前讲新发展理念，大家还记得吗？新发展理念当中，你看既然强调各个方面创新，协调，绿色，开放，共享，都是在强调如何发展的问题啊。包括习近平总书记之前也说过，这个点发展是解决一切问题的基础和关键，对不对？哎，那发展就是我们的动力啊，发展就是我们的动力。而安全呢？同学们，安全就是保障，对吧？唉，你看我们国家在当前最近这几十年，为什么能够发展的如此迅速？同学们不就是因为我们国家？这个环境是不是维持的非常安全，非常的稳定啊？对不对？唉，你看谁想谁敢对我", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 235, "end_char": 335, "line": 1, "excerpt": "以公有制为主体啊，因为书上有，所以这个呢，我就不写全了啊，大家有印象就行了，以公有制经济。为主体对不对唉？然后非公有制经济啊呃，这个共同发展，然后第二个也就是我们今天要给大家讲到的，强调按劳分配为主体", "policy_id": "FENGZE_POL_027", "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 7910, "end_char": 7980, "line": 3, "excerpt": "例15这道题选什么同学们啊？这道题选什么？直接打就行了啊，因为同学们，我这个我上这个政治理论课程的时候，我没有其他的教研老师帮助我发那个投票", "policy_id": "FENGZE_POL_026", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15702, "end_char": 15781, "line": 1, "excerpt": "高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。", "policy_id": "FENGZE_POL_025", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 119, "end_char": 209, "line": 1, "excerpt": "中国式现代化全面推进中华民族伟大复兴的这个问题啊。好了，来吧，同学们，今天晚上呢，咱们预计啊呃，讲到大概第六章结束啊，大家可以看一下你的讲义好吧嗯。好了啊，那先来看一下第一个问题，", "policy_id": "FENGZE_POL_024", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 17062, "end_char": 17362, "line": 1, "excerpt": "正和创新这个词说了很多遍了，是不是哎，守正有的一些东西是不能变的，像我们上上面提到的党的领导对吧，以人民为中心等等这些东西。都是不能变的，但是在发展的过程当中，必须坚持创新去带动发展好后面啊什么，还有就是效率和公平，因为你想。实现这种共同富裕，对吧？你要激发人民的这种效率啊啊，要让我们提升生产力，对不对？唉，但是同时还要强调什么？要注重公平，因为我们最后要实现共同富裕啊。那么，还有就是活力和秩序哎，你想想同学们这两个关系也很重要，对吧？唉，你想如果我们想要激发大家的活力，那你秩序上是不是可能稍微的就得放松一点儿？对吧哎，但是如果你秩序放的太松了，就你不管，那这个时候他可能太有活力了，同学们那就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 20661, "end_char": 20961, "line": 1, "excerpt": "理解也行好吗？同学们哎，直接去理解也行啊。那么，往下看，括号一教育是民族振兴，社会进步的基石，那怎么去发展教育？同学们，你看他说到啊，办好中国特色社会主义教育，必须坚持党对教育工作的全面领导。毋庸置疑，对不对？昨天刚讲到党是领导一切的啊，那必须坚持党的教育方针，我们党的教育方针是什么呢？大家可以看一下下面蓝色字体部分给大家拿出来的啊，这个了解就行，不用记同学们啊呃，我把这个划掉好吧，要不然有很多同学。容易引起误会啊，了解就行，你看他说教育必须以社会主义现代化建设服务，对吧？为人民服务必须以生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义阶。呃，社会主义建设者和接班人。唉，所以这个大家", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 19046, "end_char": 19346, "line": 1, "excerpt": "看我们书上具体是怎么表述的啊？好啊，稍微慢点儿是吧？好，稍微慢点儿啊，稍微慢点儿，首先第一个啊，我们在之前讲到关于党的领导的问题，给大家最讲呃，最刚开始的时候讲十个明确，不知道大家还记不记得啊？在讲十个明确的时候，那个时候我们强调第一个明确是不是明确中国特色社会主义最本质的特征是什么？是不是就是党的领导对吧？这也就是这个标题啊，其次它跟着是第二句话，也就是中国特色社会主义制度的最大优势是什么？同学们是不是也是党的领导啊？对吧？唉，那么。当时让大家记得叫本党是大党嘛，哎，本党是大党啊，那么除了这个之外，我们书上还说了两个比较特殊的，第一个强调党呢，是中国特色社会主义事业的坚强领导核心。啊，中国最", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 6243, "end_char": 6379, "line": 1, "excerpt": "关于两个结合的问题，那你得知道两个结合对吧？这里还是得需要你明确知道两个结合到底是啥的。两个结合，同学们来有没有同学记着的，之前我们说的两个结合是什么？它是经济工作吗？同学们，它是经济工作吗？不是唉，我们强调的两个结合与中国的传统文化相结合，与中国的具体实际相结合，对吧？", "policy_id": "FENGZE_POL_023", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy','political_theory','行测','政治理论','党和国家方针政策与时政','topic',1,1,'gongkao.xingce.political_theory.policy','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 10217, "end_char": 10517, "line": 1, "excerpt": "后紧接着再往下进一步形成人才辈出，人尽其才，人尽其用的生动局面，这就不说了，同学们啊，这三个词。看一看就可以了啊，可出题的点其实不是特别的多，然后往下第二个建设教育强国啊，科技强国，人才强国，必须坚持什么呢？正确的办学方向先理解这个。同学们，还记不记得正确的办学方向是什么方向？同学们非常好，我看到了花生不识数，同学对吧？唉，是社会主义的办学方向。啊，社会主义办学方向千万记住啊，这是我们后面讲新思想的时候，其实会讲到的啊，也就是本身关于正确的办学方向的问题，哪个方向其实就是我们。啊，这个整个大的层面上是要坚持社会主义的办学方向，这个就是啥意思呢？也就是你不要在这个培养人才的过程当中，对不对？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 8508, "end_char": 8808, "line": 3, "excerpt": "一点儿。那么，往下第三个啊，我们强调深入实施科教兴国战略，提升国家创新体系的整体效能，那怎么实行科科教兴国呢？首先，第一个强调了一个数字啊。数字这块说，制定实施教育强国建设的三年行动计划啊，我们之前啊，给大家也说过这个问题，就是如果说在一整道题当中，你会发现啊。呵呵呵，是别骂了，题是我出的，同学们别骂了好吗？哈哈哈，题是我出的啊。就是呃，如果啊，在一个题当中，他所有的一些这个选项都没有去提到这个呃年份的这个问题，知道吗？哎，都没有提到这个年份数字的问题而。只有一个选项提到了年份的问题，你就要重点关注了，知道了吗？同学们哎，那他很有可能，你看把这个三年就改成五年对不对？哎，等等，类似于这种啊，所", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 73, "end_char": 373, "line": 1, "excerpt": "给大家讲到了第三章对不对哎？第三章呢？然后我们把这个重要的文件。前两个也就是政府工作报告以及中央一号文件给大家讲完了，那么今天呢？我们继续开始讲啊，就是讲第三个教育强国建设规划纲要二零二四到二零。二零三五年，所以之前的时候，如果大家啊没没及时跟课的对吧？然后今天来了那把这个讲义啊，打到咱们这个章节好吧？那么来看啊，在这个章节当中，其实你会发现啊，关于教育强国的很多问题，我们在之前的时候给大家多多少少讲到新思想的时候，其实有一些问题是强调过的，对吧？哎，那先来看第一个啊，在这个规划纲要当中，第一个需要大家掌握的知识点就在这儿了，看到了吧？哎，也就是坚持什么样的一种办学方向，那么我们前面在讲到这个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250921 政治理论(时政)加课6.doc.txt", "source_sha256": "862757d3895e3eb6851995aeed8aa859c9f6e438490910fcff7e4a59da6f6037", "start_char": 186, "end_char": 240, "line": 1, "excerpt": "加快建设农业强国，规划二零二四到二零。二零三五年，那么首先第一个啊，大家先明确的就是我们未来所要建成的这个农", "policy_id": "FENGZE_POL_041", "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 508, "end_char": 538, "line": 1, "excerpt": "坚持社会主义的办学方向。那么，同样啊，落实立德树人的根本任务", "policy_id": "FENGZE_POL_040", "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 32313, "end_char": 32613, "line": 3, "excerpt": "紧接着往下两个确保，确保是啥呢？这是过去我们在讲到呃二四年一号文件的时候说到的，我们要确保两条底线。啊，所以我们经常叫两个底线嘛，哪两个底线一个强调的是确保国家粮食安全底线，另外一个是确保不发生规模性返贫置贫底线。看到了吧？哎，这是两条底线啊，也要从整个的这个农业发展上对不对？哎，从三农的这个角度上，我们强调两条底线，一个是粮食安全，一个是哎，不发生规模性返贫置贫的底线。那么，三个提升，三个提升，提升啥？同学们，其实这是过去在二四年一号文件当中提出的，叫三项重点工作。啊三项重点工作，那我们后面讲的很多的举措，同学们，你会发现它都是围绕着两个确保和三个提升来的啊，哪三项重点工作呢？第一个强调。提", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 10062, "end_char": 10362, "line": 1, "excerpt": "之外，剩下的同学们都是一样的，和我们之前讲的一号文件的说法是完全一样的，你看比如说我们。之前给大家强调的两条底线，对吧？哎，哪两条底线啊？同学们，一个是确保国家粮食安全底线，另外一个就是确保农业呃，农村人口不发生规模性返贫底线啊。啊，然后紧接着再往下三项重点工作，哪三项重点工作呀？是不是哎？以提升乡村产业发展，乡村建设，乡村治理水平啊？那你可以记按照之前的这个记啊。叫什么叫产建制？看到了吗？产建制啊，你可以按照这个去记好不好？哎，好了啊，这是在这一块儿，然后最后这五个振兴了解就行了，好吧，哎，这个不作为重点啊，产业人才。文化生态组织振兴，这提了太久了啊，提了太久了好了，这是在这儿啊，我们给大家", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 8886, "end_char": 8962, "line": 1, "excerpt": "锚定建设农业强国目标，哎，同学们来啊。重点内容一定要回过神儿来了啊，重点内容看我们这一块儿讲到的内容，你会发现它和我们前面讲一号文件的一些表述就不一样了", "policy_id": "FENGZE_POL_039", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 49249, "end_char": 49326, "line": 1, "excerpt": "降低财政赤字率错了吧？哎，刚才是说的是提高财政赤字率对不对？哎，然后说停止超长期特别国债，那也错了啊，应该是增发超长期特别国债。哎，然后其他两个这个都对了", "policy_id": "FENGZE_POL_038", "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 626, "end_char": 714, "line": 3, "excerpt": "国内生产总值增长5%左右，这个是不是和去年是持平的，对吧？哎，因为去年的时候我们强调二零二四年它的国内生产总值增长是一百三十四点九万亿。对不对诶？然后增长是多少？增长不就5%嘛", "policy_id": "FENGZE_POL_037", "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 329, "end_char": 412, "line": 3, "excerpt": "扩大内需，那既然是扩大内需，之前给大家讲过内需。它包括两个方面，哪两个方面？一个是消费，另外一个就是投资，看到了吗？同学们，唉，所以在这里面啊，首先你要先了解国内需求", "policy_id": "FENGZE_POL_036", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 47395, "end_char": 47465, "line": 1, "excerpt": "第11题选b选项啊。然后往下同学们，我们把这个四和五就是把这个政策给大家讲完好吗？同学们把四和五政策讲完啊，因为我知道你们中午还有课啊，但是", "policy_id": "FENGZE_POL_035", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 7667, "end_char": 7967, "line": 1, "excerpt": "全称是什么？看它的这个称呼啊，叫中国共产党第20次全国代表大会。这也就是我们简单意义上来说的什么，同学们。就是党代会。啊，就是党代会，我们所有的党员，我们之前学历史的时候是不是学了，对吧？还记得吗？同学们在一九二一年的时候，中共一大是不是召开了那个一大就是我们现在20大对吧？不断延伸过来的啊。从这开始，那么党代会注意它一般是多少？五年开一次啊，五年开一次，大家注意，这是从我们建国之后啊，建国之后也就是从一九八二年那个时候开始，其实才形成这样的一个。比较规律的啊，时间的啊，因为之前的时间大家学那个历史，我们学党代会的时候，大家也发现了那个时间不是很规律，对不对？哎，所以在这块儿大家知知道，就每五", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 38335, "end_char": 38635, "line": 3, "excerpt": "命这一重大问题上认识更加清醒，行动更加坚定。因为我们之前说过自我革命，这是第几个答案，同学们。之前是不是讲了对吧？前面刚讲完啊，自我革命，这是我们党跳出治乱兴衰历史周期律的第二个答案，对吧？唉，前面说过就不再多说啊，所以你看我们坚持把它作为第二个答案。所以我们对于自我革命这个问题认识更加先行，更加坚定啊，那第二个就是我们在扎实开展党纪学习教育。啊，党纪学习教育那么全党同志遵守唉，遵规守纪的意识更加增强了啊，好，这是党纪，然后紧接着第三。持续加大反腐败力度，铲除腐败滋生的土壤和条件。同学们啊，这个反腐败力度大不大？你就看我们每天的新闻就行了，对吧？哎，每天你看，无论是我们的这个央央视新闻，还是新", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 18988, "end_char": 19288, "line": 1, "excerpt": "国企业，中国公民一样的这种待遇。那你来不来？对吧？唉，是要来的啊，那么往下第八个第八个呢？强调多边主义是解决世界面临困难挑战的必然选择，而经济全球化是不可阻挡的历史潮流。这个注意别。别让这两个词互换位置就行了啊，因为之前我们在强调世界经济发展的时候，一直在说经济全球化，它是一种潮流，对吧？哎，因为现在你看没有哪个国家真正的能够独立于现代经济全球化的。潮流之外啊，没有哪个国家能真正的独立，任何国家的发展对吧？你看或者说有一些，尤其是做这种进出口企业的，它更加依赖于这种经济的发展啊。啊，那么还有就是前面说的多边主义，它是解决世界面临困难挑战的必然选择。当有一些问题出现的时候，对吧？各个国家之间我们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 24520, "end_char": 24820, "line": 1, "excerpt": "是遭遇了四一二和七一五的反革命政变之后。啊，然后我们开始南昌对吧？哎，然后这个秋收起义和广州起义等等，他在这些起义最终结果都失败之后。想一想毛主席，他就转战到了井冈山，建立了井冈山革命根据地，然后由此提出了一个非常重要的革命时期的理论什么。农村包围城市武装夺取政权呀，对吧？他为什么提这个？就是因为毛主席当时意识到了。既然我们要让人民群众站在我们这边，对不对？那当时中国社会而言，我们最广大的人民群众就是谁同学们？那不就是在农村待着的农民吗？我们当时中国80%都是农民啊，同学们哎，所以你看我们扎根农村，取得了农民的广泛信任，就代表我们真正的走到了人民群众的心里。对不对？所以你看到最后我们在解放战争", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 6304, "end_char": 6604, "line": 1, "excerpt": "神。啊，就这三个方面，其实你主要联系前面就行了，也就是开天辟地，对不对？敢为人先首创嘛，毕竟红船精神是我们党创建的时候啊，创建的时候。然后紧接着后面其他的啊，像井冈山精神这个不做重点介绍啊啊，井冈山呢呃，这个我们之前强调的是在一九二七年还记得吗啊，秋收起义结束之后啊，然后呢？呃秋收起义最终的这个结果不是失败了吗？失败之后，然后啊，毛泽东同志带领着我们当时的起义队伍转战到井冈山，是不是哎？然后成立了井冈山根据地啊。好，这个大家知道，井冈山是我们的第一个革命根据地，其实就行了啊，然后它里面的这些内容简单，看看这个不做一个重点啊。然后往下。第二个重点呢，就是它看到了吗？同学们叫遵义会议精神啊，遵义会", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 4256, "end_char": 4314, "line": 1, "excerpt": "会当中，他说到的这么一个东西就是关于完善市场经济基础制度。这个当时我不知道有没有同学掉坑的，对吧？关于市场经济的基础", "policy_id": "FENGZE_POL_034", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11811, "end_char": 11912, "line": 1, "excerpt": "以经济体制改革为牵引，为什么是以经济体制改革为牵引？我刚才提到了一个问题，我没在书上写啊，你看我刚才说了，我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？", "policy_id": "FENGZE_POL_033", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15979, "end_char": 16069, "line": 1, "excerpt": "进一步全面深化改革的原则。啊，这个呢，大家听一听就行啊，虽然我们也给大家出题了，但是呢啊，不作为一个重点，为什么？因为从之前啊，我们呃，就是国省考它出题的这个内容上来看它很少。出这", "policy_id": "FENGZE_POL_032", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15837, "end_char": 15922, "line": 1, "excerpt": "错了呀？我们书上说的是建国80周年，对吧？哎，中华人民共和国建成80周年啊，所以在这里面注意啊。这道题选的是。b选项啊，也就是二和四错了啊，一个时间错了一个具体的表述错了", "policy_id": "FENGZE_POL_031", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism','political_theory.marx','行测','政治理论','辩证唯物论','topic',1,1,'gongkao.xingce.political_theory.marx.materialism','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 31909, "end_char": 32209, "line": 1, "excerpt": "一个缺陷。第二个缺陷就是我们刚才提到的形而上学性了，对吧？形而上学性这个词挺抽象，但是其实只需要你把握后面这三个词就行了。什么叫形而上选项？同学们，其实就是孤立静止和片面这三个观点。只要在某一个观点当中，它体现出这三个观点当中的任意一个，这是我给大家补充的啊。三者只要满足其一，就可以称之为叫形而上学性。啊，那这三个词都很好理解啊，孤立的静止的片面的对不对？好看下面我给大家举的这几个例子啊，首先第一个孤孤立的观点，比如说像我们之前做题的时候经常见到这么一句话叫什么？叫只见树木，不见森林，看到了吗？嗯，当有一整片森林在你眼前的时候，结果你只能看到一棵一棵的树，你并没有办法看到整个森林。那你看同学们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 8990, "end_char": 9290, "line": 1, "excerpt": "家思考这句话吧，这句话说的对不对呀？是不是是不是你看考虑所有的物质都是运动的，有同学说说老师，我咋这么不信呢，对吧？说的这么绝对，难道这个世界上就没有一些物质是静止状态的吗？啊，难道就没有一些物质，它是永恒静止状态呢？其实同学们，你要考虑。我就现在你想啊，你现在就想是宇宙当中有没有一种物质，就这种物质对吧？它就是永恒静止的状态，你想你想破脑袋，你都想不出来。同学们在宇宙当中有没有哪种物质？它是永恒静止的状态。是没有的唉，是没有的就哪怕像我们之前说的像你现在坐在这个椅子上，你没有动对吧？或者坐在床上没有动。那这个时候你看，随着地球在不断的进行自转和公转，你是不是一直在动，对吧？唉，所以在这种情况", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 603, "end_char": 903, "line": 1, "excerpt": "节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静止的，那么辩证法它强调的是事物都是永恒发展的。而形而上学，强调片面，那么在这里", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 33634, "end_char": 33934, "line": 1, "excerpt": "着往下来看，同学们这个比较重要的知识点啊，要记住的这几个点都要记住一二三四意识的能动作用。考的也非常多啊，什么叫意识的能动作用含义了解就行，他说也指的是意识的叫主观能动性啊。指的是意识能动的反映世界和通过实践改造世界的能力和作用啊，那这就是一种意识的能动性。那么，它的浓度性作用主要表现在下面四个点来看吧，哪四个点第一个点意识活动具有目的性和计划性？哎，什么意思啊？什么叫目的性计划性？其实目的和计划这两个大家都能理解，对吧？唉，也就是你带着什么目的？去想这个事情，比如说大家啊，你看你现在为什么在这学习啊？同学们，你是带着什么目的来的？你是带着要考上公务员儿的这个目的来的，对不对？唉，那这就是你看", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 5913, "end_char": 6213, "line": 1, "excerpt": "对？哎，那么在这种情况之下，大家注意人为事物的联系，有同学说都说人为了，那难道不是主观的吗？同学们。不是的啊，人为事物的联系，在你创造它的过程当中，可能确实有你主观能动性的发挥，对不对啊？因为你可以在四海报班儿，你也可以在其他的一些公司报班儿，对不对？这都可以。但是你要注意，一旦当你建立了这种联系之后，那这个联系它就是客观的，它就是不以人的意志为转移的。能理解吗？同学们哎，这种活动啊，这个这种联系是已经建立的啊，你不能说说啊，这个时候说你看说我感觉冯老师这不行了，对吧？我我不想再当你的学生了，那不好意思，也是一样的你你。因为我已经成为你的老师了，对吧？哪怕你后期换了个老师，再听这些课啊，那之前", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 39823, "end_char": 40123, "line": 1, "excerpt": "。所以主体是人，那紧接着往下，他又说了是人类怎么样叫能动的改造世界，什么叫能动的同学们？能动这个词，我们前面讲到意识的能动作用的时候，是不是给大家说了说发挥人的主观能动性，是不是哎？所以这个能动它，体现的就是我们的这种实践活动啊，是人一种有意识。有目的的活动。啊，这个能理解，就是人我们的实践活动是一种有意识，有目的的活动，比如说同学们像刚才给大家说的这个农民种地的活动，对吧？哎，农民种地的实践活动，你想一想。我在这块地上要种什么？农作物对不对？哎，是种玉米，是种水稻，是种小麦，你看首先我是有自己的主观意识的，对不对？以及我在种地的过程当中啊，可能我说了这块儿地啊，哎，我要把它分开种，对吧？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 25405, "end_char": 25705, "line": 1, "excerpt": "什么都回归到这个问题上，也就是思维与存在的关系问题。啊，所以后面我们才提到了这个问题，也就是哲学的基本问题是思维与存在的关系问题。那或者我们说另外一个点就是它是意识和物质的关系问题，这两个说哪个都可以知道吧？两种不同的表达啊，所以第一个考点需要记住的哲学基本问题是什么？啊，这是第一个考点，那么往下来看，关于哲学的基本问题，我们既然他提了，你是不是就得回答呀？对吧？唉，所以回答有两个方面啊，哪两个方面呢？第一个强调就是思维和存在何者为第一性的问题，而第二个方面强调的就是思维和存在是否具有同一性的问题。讲到这啊，有很多同学会很困惑，是不是什么是第一性，什么是同一性呢？来同学们啊。看我给大家做了一个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 41558, "end_char": 41858, "line": 1, "excerpt": "点儿，对不对？如果我没啥能力，那指导你，那可能就往一个坏的方向去发展了。啊好了，注意这三个就是比较容易错的说法就可以了好吧唉，好了，这是在这儿啊，第一个关于这个意识和物质的这个辩证关系。然后紧接着往下同学们看第二个就是它的方法论意义，方法论意义这一块儿，那么也很简单了，就是根据我们刚才说的。啊，这两个点第一个他说的是物质决定意识对不对？那既然物质决定意识有什么样的物质在我们的啊？这个精神当中才会有什么样的意识产生？所以你看他说了。我们要一切从实际出发，对吧？那一切从实际出发，他说到我们要按照事物的本来面貌去认识世界，在改造世界当中坚持实事求是。那啥意思啊？一切从实际出发，这还不简单吗？比如说同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 297, "end_char": 597, "line": 1, "excerpt": "这儿大家一定要认真听了啊。好实践与认识的辩证关系呢？其实大家会发现啊，如果你对于之前我们在讲唯物论那一块。嗯，还有印象的话，唯物论的辩证关系，他是不是也在讲关于物质和意识，二者之间的关系问题，对不对？唉，那么无非就是两个方面。哪两个方面，同学们首先第一个方面就是物质决定意识。对吧，这是第一个，然后第二个强调的是意识啊，反作用于物质，那么它有两个方面，一个强调的是哎，正确的去促进另外一个强调的就是。哎，这个错误的起阻碍，那么实际上你会发现实践与认识的辩证关系大体上来说也是这两个方面一个啊，强调的是决定作用，一个强调的是反作用。那么来看一下第一个实践决定认识我们在这里面讲到这个实践决定认识的时候，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 36502, "end_char": 36584, "line": 1, "excerpt": "做了最高的概括，指出客观实在性是物质的本质属性。同学们，你们有没有有没有发现就是马克思主义哲学和过去的两个古代朴素和近代形而上学？他认为物质的观点不太一样了，对吧？", "policy_id": "FENGZE_POL_010", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 38365, "end_char": 38447, "line": 1, "excerpt": "像旧唯物主义或者说庸俗唯物主义这样的一些说法。什么说法呢啊，什么下课呀，同学们到十点呢，哎呀，到十点了啊，好，那到底什么是旧唯物主义，什么叫庸俗唯物主义呢，同学们？", "policy_id": "FENGZE_POL_009", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26594, "end_char": 26663, "line": 1, "excerpt": "唯物主义之下还有什么古代朴素近代形，而上学是不是但是要注意我问的是基本的哲学派别。能理解吗？唉，基本的哲学派别只有唯物主义和唯心主义这两个", "policy_id": "FENGZE_POL_008", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26725, "end_char": 26757, "line": 1, "excerpt": "主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_007", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26976, "end_char": 27037, "line": 1, "excerpt": "为我们这个世界是能够被认知的，所以这就是一种典型的可知论的观点。能理解吧唉，然后第二种观点就是你认为思维不能够认识客观世界", "policy_id": "FENGZE_POL_006", "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26642, "end_char": 26757, "line": 1, "excerpt": "基本的哲学派别只有唯物主义和唯心主义这两个，而我们所学的其他的很多非常细微的哲学理论，像我刚才提到的古代朴素唯物主义，对吧？近代形而上小唯物主义啊，马克思主义哲学以及主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_005", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics','political_theory.marx','行测','政治理论','唯物辩证法','topic',1,1,'gongkao.xingce.political_theory.marx.dialectics','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 49276, "end_char": 49576, "line": 1, "excerpt": "分的你看学到最后，其实实际上。你区分非常简单，对吧？唉，区分非常简单啊。然后来往下把这个讲完，对吧？把矛盾这块儿讲完，然后咱们简单做个总结，咱们就下课啊呃，这个内因和外因这块儿就相当简单了啊，大家听一下就行了啊。你看，首先第一个他说了事物发展的动力和源泉就是事物的内部矛盾，哎，因为正是事物内部有矛盾嘛，所以我们的整个事物才会向前发展，我们在最初。讲到矛盾，也就是讲到对立统一的时候，你看他说了，他揭示了事物发展的什么源泉和动力，对吧？哎，因为事物内部它总有这种矛盾，矛盾的两个方面相互斗争啊，然后才促进了它的发展好，那么紧接着往下同学们。看所谓内因，指的就是事物的内部矛盾，而外因呢，同学们那就是事", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12382, "end_char": 12682, "line": 1, "excerpt": "人的出现去推翻当时的封建社会。你看他这句话说的是什么意思？就是封建社会到那个时期已经自我否定，对吧？他已经不行了。对，非常好，我看到有同学打了一个弹幕，就是因为内因他在事物的发展过程当中起决定作用，同学们，你看我们讲到这儿，前面的一些矛盾的观点是不是？已经深入到这里面了，对吧？已经串联起来了啊，内因是起决定作用的，整个封建社会已经腐朽，没落到一定的地步了。哎，所以我们不可否认啊，孙中山先生确实是非常伟大的，对不对？哎，但是换成比如说那个时候冯老师就在那个地方，对吧？我可能变换成孙中山。变成了冯中山，我就成为了大家历史课本上要学习的这个人物，是不是啊？那所以一定要注意啊他。它所谓的辩证的否定，就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 1816, "end_char": 2116, "line": 1, "excerpt": "说法，从哲学上那就是错的，唉，这不就是唯心的观点吗？对不对？唉。然后啊c选项说说矛盾的普遍性是矛盾的共性没问题啊，普遍的东西不就是共性的吗？对不对哎？那么矛盾的特殊性，它就是矛盾的个性，这没问题啊。所以这道题选的就是c啊，而4d选项当中说矛盾的普遍性和客观性决定了事物的不同性质，注意同学们。谁决定了事物的不同性质呢？其实是。这个点他说错了，同学们啊，我们在讲到呃这个事物性质的时候，哲学上强调主要矛盾的主要方面决定了。事物的不同性质，唉，主要矛盾的主要方面决定了事物的性质，但是如果你是从这个就是普遍性和特殊性的角度去考虑的话，那一定是特殊性，注意啊。特殊性，它决定了事物的不同性质，能理解吗？唉，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 31927, "end_char": 32227, "line": 1, "excerpt": "，其他的后面这个就不给大家讲了啊，因为后面这个呢，本身我们考试的时候它很少涉及啊，很少涉及。嗯，那么来往下同学们看第二个点啊，第二个点呢，我们在讲矛盾的普遍性和特殊性。看同学们，这就是我刚才为什么给大家讲说矛盾的基本属性，对吧？我们刚才讲的整个那个知识点是不是都在讲这个基本属性？矛盾的基本属性指的是矛盾的同一性和矛盾的斗争性。我解释了为什么这两个是它的基本属性啊？因为只要是矛盾，它就有同一就有斗争，所以它是基本的对不对哎？这是基本的属性。但你会发现，矛盾的普遍性和特殊性，这两个就不一样了，为什么？因为普遍性和特殊性看啊，它是矛盾问题的精髓，这是毛主席给的定义啊。它是矛盾问题的精髓。那么怎么理解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 37004, "end_char": 37304, "line": 1, "excerpt": "我为什么这么咬牙切齿，因为我们讲了对吧，就是原话呀，原话你还错，你想想同学们啊，这万一考试咋整啊？好，这是第二题啊，其他的都不用看了啊，都不用看了，就说什么矛盾特殊性，对吧？全面发展，按客规客观规律办事，你看这句话对吧？明者因时而变。智者随事而智，啥意思啊？就有智慧的人会根据实际情况的变化，然后去调整。能理解吧哎，去调整啊，然后做到什么做到哎，就像我们说的什么一切从实际出发呀，具体问题具体分析啊，这都行，所以a选项是不是把握了矛盾的特殊性？没问题吧，对不对哎？然后同样的，他在这里面强调提高创新思维活力，建立全面的发展观，同学们。后面人说了，根本途径在于创新，对吧？哎，所以你看在这里提高创新，其", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 15175, "end_char": 15475, "line": 1, "excerpt": "实质是什么？这个一定要记，因为考试的时候他就喜欢把这个实质和我们后面。学到的一个知识点的实质混淆一起啊，所以大家先把这个先记住啊，一会儿咱们再对比说发展的实质是新事物的产生和旧事物的灭亡。那问题来了，同学们。新事物的产生，旧事物的灭亡，什么叫新事物，什么叫旧事物呢？是不是按照我们平时的思维习惯去理解，说这个东西啊，你看比如说这个手机是我刚买的对吧？哎，今天下班儿没啥事儿，路过手机店发现哎，突然之间这个手机挺好看，我就新买了一个手机。啊，那这个就是新手机，那我之前的那个手机就是旧手机了，对吧？这是我们平时的理解，对不对？同学们，但是你要注意。在哲学上，我们不能用时间的先后去区分，而需要用什么去区", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12927, "end_char": 13227, "line": 1, "excerpt": "那这个点同学们，他容易怎么考？他很少直接去考，他会结合着我们前面讲到的一个知识点。看到了吗？也就是他会这样去说啊，在选项当中，他说a选项就这样的辩证否定的实质是新事物的产生和旧事物的灭亡，对吗？同学们。不对吧，哎，非常好，同学们有很多同学都知道这个是谁的实质，它是发展的实质呀，对不对？哎，发展的实质，所以我之前就讲到发展那个时候我就说了，我们很容易啊，他很喜欢在出题的时候把后面辩证否定的实质和它混合在一起。啊，要不然你看我为什么一直在说说哲学这个东西，其实你后期把它梳理完之后啊，你把它记住，有一些关键的知识点，你把它记住。记住之后你做题的时候非常好做，因为有些选项你打一眼儿一看对吧？哎，打眼儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 17011, "end_char": 17311, "line": 1, "excerpt": "一领域的，而哲学呢？是对这些的概括和总结，研究的是最普遍最一般的啊，所以在这里面。先搞清楚它啊，先搞清楚它那么来，同学们。看下面这个最为重要的点就是它二者之间的联系联系，说到具体科学是哲学的基础，而哲学给具体科学以世界观和方法论的指导。那么来同学们看啊，怎么去理解这个东西？为什么说具体科学是哲学的基础哲学，又给具体科学以世界观和方法论的指导呢？往下啊，我把这个白板清理一下，我给大家写一个案例啊。来吧，同学们，我们刚才是不是讲了很多的具体科学对吧？唉，你要结合我跟他大大家说的这些案例去理解啊，首先第一个比如说我们说物理学。那大家想一想，物理学之前我们讲物这个科技常识的时候讲过哪些物理知识啊？还记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 45862, "end_char": 46162, "line": 1, "excerpt": "不对？唉，那么我们就呃给大家解释一下这个规律，因为这也是我们考建考试的时候常见的一个考点啊。规律的含义了解就行，它说规律是事物本身所固有的本质的，必然的，稳定的联系。啊，那你看像比如说我们刚才提到的万有引力定律，是不是宇宙当中很多的这个事物都它都是遵循的，这个万有引力定律啊，对吧？哎，然后再比如说像我们讲到的牛顿的啊，三大运动定律啊，什么作用力反作用力对吧？惯性啊，惯性定律等等，类似于这个，你看这些它都是在事物。本身所固有的本质的必然的稳定的联系，对吧？唉，那这就是我们所说的这个规律啊，它是一种这个联系。那规律来看。下面是重点啊，规律，它具有客观性，什么是客观性啊，之前讲过了，对吧？客观性其实", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 564, "end_char": 864, "line": 1, "excerpt": "？我们在之前讲到形而上学的时候，其实给大家做了这样的一个呃，过去啊，就是在前两节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 9167, "end_char": 9238, "line": 1, "excerpt": "第三个否定之否定规律。否定之否定规定呢？它揭示的是事物发展的方向和道路。那么来看啊，所谓否定之否定，我们在语文上说双重否定是表肯定的，对不对？", "policy_id": "FENGZE_POL_015", "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 170, "end_char": 249, "line": 1, "excerpt": "这个第二个量变质变规律，那么量变质变规律这一块儿呢，大家看一下啊，首先呢，说到它揭示了事物发展的形势和状态。那么，具体它事物是以什么样的形式和状态去发展的呢？", "policy_id": "FENGZE_POL_014", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 41145, "end_char": 41235, "line": 1, "excerpt": "所谓的主要矛盾看书上标红的这句话就行了啊，这种居于支配地位对事物的发展过程起决定作用的矛盾就是什么？就是主要矛盾。啊，那反过来就好理解了呀，所谓的次要矛盾指的就是处于从属地位不起决", "policy_id": "FENGZE_POL_013", "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 99, "end_char": 187, "line": 1, "excerpt": "是第三节的唯物辩证法，所以各位同学如果之前对吧呃，这个前两节课没跟到，包括可能有最近刚进来的各位同学啊。把政治理论的那本儿讲义打到咱们的第三节唯物辩证法，这个章节当中好不好嗯？", "policy_id": "FENGZE_POL_011", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.epistemology','political_theory.marx','行测','政治理论','认识论','topic',1,1,'gongkao.xingce.political_theory.marx.epistemology','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 17648, "end_char": 17948, "line": 1, "excerpt": "，对不对？而第二次飞跃注意了，那就是从理性认识到实践的飞跃了，好吧嗯。这个也不多讲啊，大家知道这两次飞跃就可以了，那么紧接着往下来看，同学们啊，第二个认识过程的反复性和无限性。什么叫反复性？什么叫无限性呢？先来看第一个啊，反复性所谓反复性指的是认识过程啊，你看它指的是对一个复杂事物的认识。往往要经过由实践到认识，由认识到实践的多次反复才能完成。啥意思？同学们，你看比如说啊。大家通过这个课堂上接触了我，对不对？唉，接触了冯泽老师啊，那你是不是会对我形成一种感性认识啊？对不对，同学们？你会对我形成一种感性认识，对吧？唉，形成感性认识，但是你不要忘了同学们，人是最为复杂的生物，你知道我背地里啥样吗？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 9063, "end_char": 9363, "line": 1, "excerpt": "规律有哪些？首先，第一个强调认识的辩论过程啊，这个点上有首先第一个啊，虽然我没标红，但是你要知道这有个考点。认识的辩证过程是什么？就是第一句话，在实践基础上，由感性认识到理性认识，再由理性认识到实践的能动飞跃，这是一个。啊，也是容易出错的考点，同学们。怎么容易出出错呢？出错的点就在下面这块儿看到了吗？易错区分当中，我们在考试当中，他很喜欢在选项里面说认识的辩证过程是从实践到认识，再从认识到实践的过程。有很多同学这个知识点把握不准确，一看到这个说法，我的妈呀，这个说法可太正确了，对吧？没有比这个说法更正确的了。同学们，这个说法对吗？不对，因为你看我们书上已经强调了认识的辩证过程，强调的它是两次飞", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 6369, "end_char": 6444, "line": 1, "excerpt": "践是检验认识是否具有真理性的唯一标准。那么这个是啥意思？你看同学们，当我们在实践当中产生了某种认识之后，我们是希望能够用这种认识去改造世界的，对不对？", "policy_id": "FENGZE_POL_017", "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 650, "end_char": 743, "line": 1, "excerpt": "首先第一个强调实践是认识的来源。那这块儿同学们啊，我们之所以说它重要啊，另呃，其实从一个方面来说就是因为在实践决定认识这一块儿，刚才强调它是有四个方面的表现的。那你要学会去区分这四个方面", "policy_id": "FENGZE_POL_016", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.history','political_theory.marx','行测','政治理论','历史唯物主义','topic',1,1,'gongkao.xingce.political_theory.marx.history','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 46909, "end_char": 47209, "line": 1, "excerpt": "么往下最后一个，这个是稍微啊，需要大家还是费点儿脑子，要需要去理解一下的。你看他说的社会历史条件。啊，社会历史条件呢？强调的就是资本主义经济的高度发展和资本主义社会基本矛盾的充分暴露。啊，什么叫基本矛盾的充分暴露，对吧？是为什么资本主义经济又高度发展了？你考虑这个时期同学们。我们之前讲科技常识的时候，是不是给给大家讲过那个工业革命？还记得吗？同学们最早讲的在19世纪那个时候。工业革命，你想一想，那个就是我们之前说的那个第一次工业革命，对吧？哎，第一次工业革命，从呃18世纪，然后。就是末期的时候一直到19世纪，这个过程从一次工业革命，二次工业革命，对吧？唉，这个时间你看。借着这两次工业革命的东风", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 380, "end_char": 680, "line": 1, "excerpt": "就是。社会发展的基本规律看到了吗？啊，那么社会发展的基本规律是什么呢？大家要先明确这样一个问题，也就是我们书上第一段强调的啊，指的就是社会的基本矛盾运动。那么，社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个唉，这是第一个考点啊，同学们。那么，大家先来看这个词，为什么我们强调说这两个生产力，生产关系，经济基础和上层建筑的矛盾？它是属于叫社会的基本矛盾呢？大家要搞清楚啊，因为这种矛盾，它在任何的社会形态当中都是存在的。注意啊，在热任何的社会形态中都存在生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，那", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 4980, "end_char": 5280, "line": 1, "excerpt": "中啊，国外留学的过程当中，那个时候你看他接受到了我们所说到的就是这个共产党宣言的一些思想，对吧？也就是共产主义的一些思想。那这个过程当中好，为了能够让我们广大的人民群众都学习这种共产主义思想。所以啊，你看这就有一个翻译的人物，也就是陈望道就可以了啊，陈望道就可以了，好那么在这里面。记住它的翻译者是谁就可以了好吧，同学们唉，记住它就可以了啊。这个陈望道好。陈望道。作为翻译者，把它翻译成中文之后，那么它开始广泛的在我们中国去进行传播了啊，这个大家有个印象就可以了。我们之前的时候，习近平主席曾经说过一句话，说真理的味道是香甜的，对不对？唉，其实就是在说。陈王道，在翻译的过程当中啊，拿那个什么吃墨水儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 15689, "end_char": 15989, "line": 1, "excerpt": "哲学最为典型的马克思主义哲学，对吧？哎，我们国家的艺术当中一直强调哎要。深刻的啊，后面其实讲新思想，大家就知道了，要创作以人民为中心的这样的一种艺术形式，要创造人民群众喜闻乐见的这种啊，哎，这个形式对不对？哎，这就是你看从。从这儿，它所体现出来的，而宗教这个这咱就不说了，因为在中国，你会发现我们国家的这种宗教思想还是比较特殊的，对吧？哎，我们后面讲法律也会说我们国家信仰的是宗教自由。哎，宗教信仰自由，就是你可以信教，也可以不信，对不对？你可以信这个，也可以信那个，这都行啊，但是实际上呢，我们国家对于宗教其实保持着是一个相对来说啊，比较谨慎的态度，是不是？所以这个咱就不提不提了啊。那么，后面同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 42951, "end_char": 43251, "line": 3, "excerpt": "解决这个东西，对不对？哎，你不能说在实践过程当中啊，你说好这里面什么问题都没有，皆大欢喜对不对？这也不是啊，这也不应该这样，所以我们强调在实践过程当中一定要抓住人民群众有哪些问题，你要针对性的。去解决问题，对不对？所以呢，你看这个问题体现什么？是不是就体现我们之前讲的矛盾？它是普遍的，它是客观的呀。哎，你在这里，你就不能否认矛盾，它是普遍的，你一旦否认矛盾，矛盾的普遍性，想一想同学们是不是就认为什么？哎，之前还真有这样的一些案例啊，同学们。有的一些地方官员就认为，这个地方它就没有，就是我们这个地方它没有矛盾的存在啊，就认为啥万世太平对吧？唉，万世太平，那你想想同学们这个观点对吗？肯定是错的呀，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11864, "end_char": 11957, "line": 1, "excerpt": "我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？有同学说老师啥叫上层建筑没学？马哲对不对？哎，其实很简单，所谓的上层建筑就是改制度，改体系", "policy_id": "FENGZE_POL_020", "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 471, "end_char": 529, "line": 1, "excerpt": "生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个", "policy_id": "FENGZE_POL_019", "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 460, "end_char": 495, "line": 1, "excerpt": "社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾", "policy_id": "FENGZE_POL_018", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.economics','political_theory.marx','行测','政治理论','马克思主义政治经济学','topic',1,1,'gongkao.xingce.political_theory.marx.economics','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 13702, "end_char": 14002, "line": 3, "excerpt": "资本家通过个别劳动生产率来提高，然后实现的，所以它是个别上面那个是整个行业的社会劳动生产率。啊，好了，这是在这儿啊，就给大家讲这么些，那么往下同学们看第三个就是资本积累和资本的有机构成啊。资本积累这一块呢？先看第一个问题，也就是资本主义的再生产啊，资本主义再生产，说到资本家啊瓜分到剩余价值后，如果将其完全用于个人消费，则生产就在原有规模的基础上。重复进行，这叫资本主义的简单再生产。啥意思？同学们来给大家说个案例，大家就明确了啊，我刚才不是说了吗？我是100万投入，对不对？唉，然后我生产出来了150万的豆腐，我把它卖出去了啊，卖出去之后同学们这一段时间我生产出来的剩余价值有多少？是不是就花是就是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 41261, "end_char": 41561, "line": 1, "excerpt": "，那这种情况之下，它对于整个社会发展会起到一些延缓作用啊，那么同样的，当人口数量过少，同学们。其实他也不行哎，他也不行，因为那个时候对刚才有同学说了，那你就没有劳动力了，没劳动力你整个社会你怎么发展啊，对吧？哎，所以在这种情况之下啊，人口数量过多过少，其实都不行，要保持一个比较。适中的状态，那么再往下就是这个质量的问题了，同学们啊，人口质量这个最显然了，就是我们当然希望人口质量是越高越好了，对不对？唉，人口质量越高，它越能够促进社会的进步与发展。但是同样，如果人口质量哎，这个比较低的话，那它就会阻碍社会的发展啊，所以这个大家能理解就行，这就是第二个人口因素。第三个叫物质生产方式。注意同学们，这", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 4208, "end_char": 4508, "line": 1, "excerpt": "句话，我们把劳动资料和劳动对象二者合称为叫什么？合称为叫生产资料。所以你看同学们啊，我们现在是不是一直啊？我刚才也给大家说，就是我们在生产的过程当中，除了要投入劳动力之外，还要投入什么笼统的说，就是投入生产资料。啊，那两部分对不对？哎，一部分就是这个劳动资料，一部分就是劳动对象啊，好了，这是在这儿啊，我们给大家去。强调的这个问题啊，强调这个问题，那么来往下同学们看了解完了实体要素之后，紧接着再了解什么叫非实体？非实体要素呢，它主要包括的就是科学技术和经济管理等等，那尤其是科学技术，它的地位非常的重要，你看它说到了把这句话记住啊。科学技术，它是先进生产力的集中体现和主要标志。就记到这儿就行，同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 508, "end_char": 808, "line": 3, "excerpt": "所以来吧，同学们。这一节课啊，前半呃前半段的课程就带着大家去了解一下啊，大家之前所说的这种所谓的资本家到底是个什么东西？是不是哎？来看一下啊。首先，第一个先来看劳动力成为商品与货币转化为资本啊，那么劳动力成为商品，看它先说到了。资本主义经济制度是以资本家占有生产资料和以雇佣劳动为基础的经济制度。那么，资本主义雇佣劳动制度的形成，是以劳动力成为商品为前提的啥意思？同学们对吧？哎，掌握这个知识点啊，其实很好理解你，想一想，你既然要雇佣劳动。你是不是首先得有一个前提，就是这个劳动力，它必须是商品，对吧？如果它不是商品，你想想你怎么去雇佣劳动啊？你怎么花钱去雇佣他呀？对不对？唉，这就是一个字面意思上的", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 2721, "end_char": 3021, "line": 1, "excerpt": "时候会犯难啊，会犯难的，确实这个东西确实是很难的啊。你看，比如说像a选项，它不是问正确的吗？a说商品的价值量是由什么决定的？那肯定不是个别劳动时间决定的呀，它是社会必要劳动时间决定的啊，这个咱后面会讲。好吗？同学们哎，咱们这个具体知识点咱就不给大家解释了啊，然后往下b选项又说说货币的价值尺度，职能是通过实际的物质交换来实现的。同学们，首先你要知道什么叫价值尺度，是不是我用货币去衡量这个东西价值的多少啊？对吧？就这东西值多少钱？那你想想，我是通过实际的物质交换去实现的吗？同学们，我说这个商品值100块钱，我是通过实际的物质交换去那个实现的吗？不是，我就是跟他观念上我说了一下这个东西值100块钱。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 48219, "end_char": 48519, "line": 1, "excerpt": "的时间越多，那么我耗费的脑力和体力的量是不是就越多？能理解吗？同学们哎，所以啊，你看我们这个时候下面说了一个非常重要的知识点，就是商品的价值量是由生产商品的，叫社会必要劳动时间决定的。那注意了，这个社会必要劳动时间指的是啥呢？同学们，你看下面他说的这个概念，理解就可以了啊，指的是在社会现有的正常的生产条件下。在社会平均的劳动熟练程度和劳动强度下，制造某种使用价值所需要的劳动时间。那比如说看下面啊，同学们给大家拿了这么一个表格的案例，大家可以理解，这个你也不用记。在这个行业当中，假设有abcde五个厂商，他们是同时生产同一个商品的啊，那他们生产这个商品的时间包括方式方法都不一样a。生产一件商品用", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 1144, "end_char": 1444, "line": 3, "excerpt": "同学们也不需要你去掌握，你只需要理解就行了啊，知道劳动力的价值是用什么衡量出来的就可以了。那么，按照我们之前上一节课的思路说到，其实一个商品的价值是由这个商品的社会必要劳动时间所决定的，对不对？哎，那大家想一个问题。劳动力其实它指的是劳动者的一种工作能力，对不对？那这种工作能力你用这种社会必要劳动时间去决定，你怎么去衡量它呢？对吧，可能你会发现这个东西很难直接去衡量它，很抽象啊，那么在这里你看我们书上就给大家说了这样一个点。我们可以把这种社会必要劳动时间还原为生产出劳动者所消费的生活资料，所必须的社会必要劳动时间。啥意思啊？你这个劳动者对不对哎？你每天都要生活啊，你要生存下去，那我可以把生产和", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 4169, "end_char": 4256, "line": 3, "excerpt": "增值的价值，即剩余价值。看到了同学们这200块钱就是我们强调的叫剩余价值啊。所以你看他最后说到一旦货币所购买的劳动力带来了剩余价值，这个时候货币就不叫货币了，叫什么叫资本了？", "policy_id": "FENGZE_POL_022", "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 188, "end_char": 247, "line": 3, "excerpt": "商品的二因素，对吧？劳动的二重性以及商品价值量，它是由什么所决定的啊？价值规律等等，这些内容给大家做了一个简单的介绍。", "policy_id": "FENGZE_POL_021", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.system','political_theory.thought','行测','政治理论','核心体系与理论创新','topic',1,1,'gongkao.xingce.political_theory.thought.system','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 17062, "end_char": 17362, "line": 1, "excerpt": "正和创新这个词说了很多遍了，是不是哎，守正有的一些东西是不能变的，像我们上上面提到的党的领导对吧，以人民为中心等等这些东西。都是不能变的，但是在发展的过程当中，必须坚持创新去带动发展好后面啊什么，还有就是效率和公平，因为你想。实现这种共同富裕，对吧？你要激发人民的这种效率啊啊，要让我们提升生产力，对不对？唉，但是同时还要强调什么？要注重公平，因为我们最后要实现共同富裕啊。那么，还有就是活力和秩序哎，你想想同学们这两个关系也很重要，对吧？唉，你想如果我们想要激发大家的活力，那你秩序上是不是可能稍微的就得放松一点儿？对吧哎，但是如果你秩序放的太松了，就你不管，那这个时候他可能太有活力了，同学们那就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 20661, "end_char": 20961, "line": 1, "excerpt": "理解也行好吗？同学们哎，直接去理解也行啊。那么，往下看，括号一教育是民族振兴，社会进步的基石，那怎么去发展教育？同学们，你看他说到啊，办好中国特色社会主义教育，必须坚持党对教育工作的全面领导。毋庸置疑，对不对？昨天刚讲到党是领导一切的啊，那必须坚持党的教育方针，我们党的教育方针是什么呢？大家可以看一下下面蓝色字体部分给大家拿出来的啊，这个了解就行，不用记同学们啊呃，我把这个划掉好吧，要不然有很多同学。容易引起误会啊，了解就行，你看他说教育必须以社会主义现代化建设服务，对吧？为人民服务必须以生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义阶。呃，社会主义建设者和接班人。唉，所以这个大家", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 19046, "end_char": 19346, "line": 1, "excerpt": "看我们书上具体是怎么表述的啊？好啊，稍微慢点儿是吧？好，稍微慢点儿啊，稍微慢点儿，首先第一个啊，我们在之前讲到关于党的领导的问题，给大家最讲呃，最刚开始的时候讲十个明确，不知道大家还记不记得啊？在讲十个明确的时候，那个时候我们强调第一个明确是不是明确中国特色社会主义最本质的特征是什么？是不是就是党的领导对吧？这也就是这个标题啊，其次它跟着是第二句话，也就是中国特色社会主义制度的最大优势是什么？同学们是不是也是党的领导啊？对吧？唉，那么。当时让大家记得叫本党是大党嘛，哎，本党是大党啊，那么除了这个之外，我们书上还说了两个比较特殊的，第一个强调党呢，是中国特色社会主义事业的坚强领导核心。啊，中国最", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 6243, "end_char": 6379, "line": 1, "excerpt": "关于两个结合的问题，那你得知道两个结合对吧？这里还是得需要你明确知道两个结合到底是啥的。两个结合，同学们来有没有同学记着的，之前我们说的两个结合是什么？它是经济工作吗？同学们，它是经济工作吗？不是唉，我们强调的两个结合与中国的传统文化相结合，与中国的具体实际相结合，对吧？", "policy_id": "FENGZE_POL_023", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.modernization','political_theory.thought','行测','政治理论','中国式现代化','topic',1,1,'gongkao.xingce.political_theory.thought.modernization','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 119, "end_char": 209, "line": 1, "excerpt": "中国式现代化全面推进中华民族伟大复兴的这个问题啊。好了，来吧，同学们，今天晚上呢，咱们预计啊呃，讲到大概第六章结束啊，大家可以看一下你的讲义好吧嗯。好了啊，那先来看一下第一个问题，", "policy_id": "FENGZE_POL_024", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy','political_theory.thought','行测','政治理论','经济发展与民生','topic',1,1,'gongkao.xingce.political_theory.thought.economy','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10225, "end_char": 10525, "line": 1, "excerpt": "来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强国，人才强国，文化强国，体育强国和健康中国。所以这两个比较特殊的，大家重点去记它，没带基本啊，没带基本好，那除了刚才给大家强调的，对吧？有一些带了基本有一些没带基本，那还有。一个考点非常重要的就是大家要把这六个国要记清楚，同学们，因为我们后面讲到政治理论的时候，经常会给大家强调，对吧？哎，教育强国呀啊，什么文化强国呀等等，这些什么时候建成呢？你看。我们强调，到二零三五年的时候，就要建成教育，科技，人才，文化，体育强国以及健康中国。那这个咋记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 14534, "end_char": 14834, "line": 1, "excerpt": "是啥呀？你既然想要让乡村振兴，你必须要坚持农业农村怎么样优先发展？这是很关键的，什么叫优先发展？同学们，比如说你要从资金的，对吧？这种配备上啊，资金的补充上，从人才的配备上，对不对？哎，从各种技术的这种支持上，你都要优先。去支持农业农村的发展，这才是我们强调的它的总方针。哎，好，那么来看第二个总要求是啥？总要求这几个词理解就行了，同学们也不要求大家去记了啊，因为也提了很早了。你看它的总要求是什么？你有没有发现其实这五个词也暗合了我们之前说到五位一体。对吧，你看一看同学们，咱们带着大家一起来看一下啊，说啥呢？第一个产业兴旺，是不是经济层面说的要产业兴旺，第二个生态宜居，那就是生态嘛。而乡风文明是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 7553, "end_char": 7853, "line": 1, "excerpt": "一个就是我们刚才说的军委主席的负责制，哎，把这两个点重点掌握就行了啊，二和三呢，这个理解就可以啊。好了，那么往下同学们第二个啊，关于这个政治建军改革强军科技强军人才强军和依法治军的这个问题。呃，这块儿呢，我先给大家说一下，就是过去它的一个发展啊，因为最早呢，我们提到这几个军的时候，其实没有这个人才强军。啊，然后过去的时候叫啥呢？叫科技兴军啊，科技兴军，所以过去提到这儿的时候，它强调的叫政治建军。改革强军，科技兴军，依法治军啊，但是你看现在我们把科技兴军改成了强军，对吧？哎，然后又多加了一个人才强军。唉，以及最后说的依法治军，所以现在变成五个了，这有一个改啊，改变了，那先来看第一个同学们政治建军", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10860, "end_char": 11160, "line": 1, "excerpt": "点，大家能够明确就行了，然后紧接着啊，和第二个本世纪中叶我们要实现的目标相对应的，有一个点同学们非常重要，我们后面也会讲到就是这个共识。同富裕看到了吗？哎，你看共同富裕的表述在这里面，哎，就不太一样了，因为我们刚才强调了，到二零三五年本世纪中叶的时候，我们的共同富裕要。应该按照正常来讲的话，它应该是基本实现共同富裕，对不对？但是你看他说的是取得更为明显的实质性进展。啊，而到本世纪中叶，他才强调全体人民共同富裕怎么样，基本实现这就是一个区别了，同学们。和大多数表述不一样的地方，是不是哎？所以同学们记住本共同富裕到什么时候才基本实现，是到本世纪中叶，为什么同学们？其实很简单啊，你想想共同富裕的实现", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11114, "end_char": 11414, "line": 1, "excerpt": "一大市场能理解吗？同学们唉，要建设我们全国的统一大市场啊，然后紧接着再往下，我们说到收入分配，那收入分配的咋样啊？现在是不是得？要公平啊，对不对？唉，我们之前讲共同富裕的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 20553, "end_char": 20853, "line": 1, "excerpt": "为我们在后面还会讲到一个地位和它有点像啊，两者有点像，所以先把它记住啊，收入分配是民生之源。是改善民生，实现发展成果由人民共享最重要最直接的方式分配制度，是促进共同富裕的基础性制度。那我们要来理解一下对不对我们国家现在的分配制度是什么样的？同学们，我们之前是不是在讲经济的时候，同学们还记得吗？唉，我们之前是在讲经济常识的时候，是不是给大家讲过关于我们国家的三次分配的这个问题，对不对？唉，三次分配的问题啊。好，那来看具体的这个收入分配到底怎么分配？初次再分配或第三次分配相协调的，这样的一个协调。协调配套的制度体系啊，那同学们来看一下啊，首先第一个它说要发挥初次分配的基础性作用。啊，因为大家想一想", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 46830, "end_char": 47130, "line": 1, "excerpt": "啊。截个图来a啊。好截个图啊，课下其实都会给大家发PPT的啊，大家可以直接看PPT，也更直观好不好嗯？来同学们那么往下来看啊，往下来看第一个完整准确全面的去贯彻新发展理念，新发展理念这一块呢，前面他先讲到了这个地位问题啊。地位问题这一块儿，他说到新发展理念是实现高质量发展的一个指导原则。一会儿，我们会重点去讲它啊，也就是到底什么是新发展理念。来看同学们第一个先理解我国进入新发展阶段啊，这块同学们所谓的新发展阶段不需要你背，你只需要理解就行了，我们过去考试的时候经常有这么一种说法，什么说法呢？他说了。我们的新发展阶段啊，是我们国家走出了社会主义初级阶段之后的一个阶段，同学们这个说法对不对？啊，同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11198, "end_char": 11498, "line": 1, "excerpt": "的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样要安全？因为你不能一味的开放，对不对？唉，我们国家在一些领域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 48951, "end_char": 49251, "line": 1, "excerpt": "决的是啥？解决的是保障问题啊。它是确保国家和民族行稳致远的一个坚强助石啊重点。其实记前面这个就行了，发展是动力，对不对？哎，安全是保障。啊，很简单呀，我们之前讲新发展理念，大家还记得吗？新发展理念当中，你看既然强调各个方面创新，协调，绿色，开放，共享，都是在强调如何发展的问题啊。包括习近平总书记之前也说过，这个点发展是解决一切问题的基础和关键，对不对？哎，那发展就是我们的动力啊，发展就是我们的动力。而安全呢？同学们，安全就是保障，对吧？唉，你看我们国家在当前最近这几十年，为什么能够发展的如此迅速？同学们不就是因为我们国家？这个环境是不是维持的非常安全，非常的稳定啊？对不对？唉，你看谁想谁敢对我", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 235, "end_char": 335, "line": 1, "excerpt": "以公有制为主体啊，因为书上有，所以这个呢，我就不写全了啊，大家有印象就行了，以公有制经济。为主体对不对唉？然后非公有制经济啊呃，这个共同发展，然后第二个也就是我们今天要给大家讲到的，强调按劳分配为主体", "policy_id": "FENGZE_POL_027", "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 7910, "end_char": 7980, "line": 3, "excerpt": "例15这道题选什么同学们啊？这道题选什么？直接打就行了啊，因为同学们，我这个我上这个政治理论课程的时候，我没有其他的教研老师帮助我发那个投票", "policy_id": "FENGZE_POL_026", "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15702, "end_char": 15781, "line": 1, "excerpt": "高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。", "policy_id": "FENGZE_POL_025", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.democracy','political_theory.thought','行测','政治理论','民主政治与全面依法治国','topic',1,1,'gongkao.xingce.political_theory.thought.democracy','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 48717, "end_char": 49017, "line": 1, "excerpt": "是我们依法治国的主体，然后其次等国际强调等第三个法律面前人人平等，是不是在之前给大家说的我们？这个法律对不对？宪法的原则嘛啊？宪法的原则啊，然后国强调依法治国和以德治国相结合，最后记。从中国的实际出发，这就是我们全面依法治国的基本的原则。好吧，唉，基本的原则啊。好，那么这几个点前面两个一个党，一个人民其实就在强调这个呃，我们主体的问题是不是然后第三个强调的法律面前人人平等，也就是法律上我们的人际关系的问题？紧接着注意，后面他说的这个依法治国和以德治国的问题，给大家说一下啊，为什么在强调法治的时候，它还在强调叫以德治国的问题呢，同学们？其实很简单，你看法律这个东西啊，它是以这种就是成文的法规的形", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10003, "end_char": 10303, "line": 1, "excerpt": "先先看就是我们关和这个基本实现社会主义现代化相对应的，它是不是都带了一个基本？看到了吗？同学们，我们讲义当中有很多的内容，说基本实现四化，对吧？哎，基本实现啊，国家治理体系治理能力现代化基本建成法治国家法治政府法治社会。以及后面你看第六个啊和第七个啊，第七个它说美丽中国目标基本实现以及基本实现国防军队现代化，因为我们强调了。二零三五年的时候，它是不是要基本实现社会主义现代化呀？对不对哎？所以很多的目标前面它都带了一个基本。但是在这里面回过头来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 31725, "end_char": 32025, "line": 1, "excerpt": "社区治理，这里强调的一个点，一定要记住这个啊，包括大家之前学申论的时候应该也学过这个词，对不对？也就是最后一公里的问题啊，什么叫最后一公里啊，你看。说基层治理是国家治理的基石，城乡社区，这是关键啊，是社会治理最基本的单元。是党和政府联系服务群众的最后一公里，因为大家想呀，我们现在是不是很多的人啊？很多的人你是不是都。再不就是生活在我们乡村的农村，对不对？哎，或者说生活在城市的社区里面啊，你都是在这个里面，所以在这种情况之下啊，我们强调它是。党和政府联系服务群众的最后一公里，所以现在你看我们不是经常说嘛，要打通最后一公里对不对？哎，打通最后一公里啊，也就是在强调啥，要密切和人民群众之间的这种联系", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 35732, "end_char": 35822, "line": 1, "excerpt": "党的领导是人民当家作主和依法治国的根本保证，说了太多遍了吧，党的领导就是根本保证对吧，因为你想啊，同学们没有党的领导，我们会我们大家会使。实现人民当家作主吗？同学们会实现依法治国吗", "policy_id": "FENGZE_POL_029", "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 34155, "end_char": 34235, "line": 1, "excerpt": "主政治的本质属性就是全过程人民民主。啊，关于全过程人民民主这个词，我们一会儿会专门解释啊，大家先理解先知道这个词就行了，那么什么叫社会主义民主政治的本质属性呢？", "policy_id": "FENGZE_POL_028", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.party','political_theory.thought','行测','政治理论','党的建设与自我革命','topic',1,1,'gongkao.xingce.political_theory.thought.party','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 53787, "end_char": 53894, "line": 1, "excerpt": "几章就是14，15，16和17讲完啊呃，我估计如果明天要能讲快点儿的话，没准儿明天能提前下课啊，同学们，因为后面剩下的这几章呢？呃，其实最重要的就是最后一章全面从严治党啊，其他那几个章节其实也不是特别的重要好吧哎。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34912, "end_char": 35212, "line": 1, "excerpt": "政策沟通设施连同贸易畅通，资金融通，民心相通啊，好，这是在这儿，所以这道题选的就是啥呀，选的就是b选项啊，选的就是b选项。好了，来，同学们往下来看。第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关，也就是我们常提的党建问题，对不对？哎，尤其是从我们啊这个习近平总书记开始啊。他一直在强调加强党的自身建设的这个问题啊，后期你看他还提出了自我革命这个跳出历史周期律的第二个答案，对不对？哎，那到底在新时代，我们应该如何？进行党的建设呢，对不对？来往下看啊，同学们，首先第一个他说到全面建设社会主义现代", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34986, "end_char": 35062, "line": 1, "excerpt": "第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关", "policy_id": "FENGZE_POL_030", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform','political_theory.policy','行测','政治理论','重要会议与全面深化改革','topic',1,1,'gongkao.xingce.political_theory.policy.reform','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 7667, "end_char": 7967, "line": 1, "excerpt": "全称是什么？看它的这个称呼啊，叫中国共产党第20次全国代表大会。这也就是我们简单意义上来说的什么，同学们。就是党代会。啊，就是党代会，我们所有的党员，我们之前学历史的时候是不是学了，对吧？还记得吗？同学们在一九二一年的时候，中共一大是不是召开了那个一大就是我们现在20大对吧？不断延伸过来的啊。从这开始，那么党代会注意它一般是多少？五年开一次啊，五年开一次，大家注意，这是从我们建国之后啊，建国之后也就是从一九八二年那个时候开始，其实才形成这样的一个。比较规律的啊，时间的啊，因为之前的时间大家学那个历史，我们学党代会的时候，大家也发现了那个时间不是很规律，对不对？哎，所以在这块儿大家知知道，就每五", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 38335, "end_char": 38635, "line": 3, "excerpt": "命这一重大问题上认识更加清醒，行动更加坚定。因为我们之前说过自我革命，这是第几个答案，同学们。之前是不是讲了对吧？前面刚讲完啊，自我革命，这是我们党跳出治乱兴衰历史周期律的第二个答案，对吧？唉，前面说过就不再多说啊，所以你看我们坚持把它作为第二个答案。所以我们对于自我革命这个问题认识更加先行，更加坚定啊，那第二个就是我们在扎实开展党纪学习教育。啊，党纪学习教育那么全党同志遵守唉，遵规守纪的意识更加增强了啊，好，这是党纪，然后紧接着第三。持续加大反腐败力度，铲除腐败滋生的土壤和条件。同学们啊，这个反腐败力度大不大？你就看我们每天的新闻就行了，对吧？哎，每天你看，无论是我们的这个央央视新闻，还是新", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 18988, "end_char": 19288, "line": 1, "excerpt": "国企业，中国公民一样的这种待遇。那你来不来？对吧？唉，是要来的啊，那么往下第八个第八个呢？强调多边主义是解决世界面临困难挑战的必然选择，而经济全球化是不可阻挡的历史潮流。这个注意别。别让这两个词互换位置就行了啊，因为之前我们在强调世界经济发展的时候，一直在说经济全球化，它是一种潮流，对吧？哎，因为现在你看没有哪个国家真正的能够独立于现代经济全球化的。潮流之外啊，没有哪个国家能真正的独立，任何国家的发展对吧？你看或者说有一些，尤其是做这种进出口企业的，它更加依赖于这种经济的发展啊。啊，那么还有就是前面说的多边主义，它是解决世界面临困难挑战的必然选择。当有一些问题出现的时候，对吧？各个国家之间我们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 24520, "end_char": 24820, "line": 1, "excerpt": "是遭遇了四一二和七一五的反革命政变之后。啊，然后我们开始南昌对吧？哎，然后这个秋收起义和广州起义等等，他在这些起义最终结果都失败之后。想一想毛主席，他就转战到了井冈山，建立了井冈山革命根据地，然后由此提出了一个非常重要的革命时期的理论什么。农村包围城市武装夺取政权呀，对吧？他为什么提这个？就是因为毛主席当时意识到了。既然我们要让人民群众站在我们这边，对不对？那当时中国社会而言，我们最广大的人民群众就是谁同学们？那不就是在农村待着的农民吗？我们当时中国80%都是农民啊，同学们哎，所以你看我们扎根农村，取得了农民的广泛信任，就代表我们真正的走到了人民群众的心里。对不对？所以你看到最后我们在解放战争", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 6304, "end_char": 6604, "line": 1, "excerpt": "神。啊，就这三个方面，其实你主要联系前面就行了，也就是开天辟地，对不对？敢为人先首创嘛，毕竟红船精神是我们党创建的时候啊，创建的时候。然后紧接着后面其他的啊，像井冈山精神这个不做重点介绍啊啊，井冈山呢呃，这个我们之前强调的是在一九二七年还记得吗啊，秋收起义结束之后啊，然后呢？呃秋收起义最终的这个结果不是失败了吗？失败之后，然后啊，毛泽东同志带领着我们当时的起义队伍转战到井冈山，是不是哎？然后成立了井冈山根据地啊。好，这个大家知道，井冈山是我们的第一个革命根据地，其实就行了啊，然后它里面的这些内容简单，看看这个不做一个重点啊。然后往下。第二个重点呢，就是它看到了吗？同学们叫遵义会议精神啊，遵义会", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 4256, "end_char": 4314, "line": 1, "excerpt": "会当中，他说到的这么一个东西就是关于完善市场经济基础制度。这个当时我不知道有没有同学掉坑的，对吧？关于市场经济的基础", "policy_id": "FENGZE_POL_034", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11811, "end_char": 11912, "line": 1, "excerpt": "以经济体制改革为牵引，为什么是以经济体制改革为牵引？我刚才提到了一个问题，我没在书上写啊，你看我刚才说了，我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？", "policy_id": "FENGZE_POL_033", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15979, "end_char": 16069, "line": 1, "excerpt": "进一步全面深化改革的原则。啊，这个呢，大家听一听就行啊，虽然我们也给大家出题了，但是呢啊，不作为一个重点，为什么？因为从之前啊，我们呃，就是国省考它出题的这个内容上来看它很少。出这", "policy_id": "FENGZE_POL_032", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15837, "end_char": 15922, "line": 1, "excerpt": "错了呀？我们书上说的是建国80周年，对吧？哎，中华人民共和国建成80周年啊，所以在这里面注意啊。这道题选的是。b选项啊，也就是二和四错了啊，一个时间错了一个具体的表述错了", "policy_id": "FENGZE_POL_031", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.economy','political_theory.policy','行测','政治理论','中央经济工作会议','topic',1,1,'gongkao.xingce.political_theory.policy.economy','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 329, "end_char": 412, "line": 3, "excerpt": "扩大内需，那既然是扩大内需，之前给大家讲过内需。它包括两个方面，哪两个方面？一个是消费，另外一个就是投资，看到了吗？同学们，唉，所以在这里面啊，首先你要先了解国内需求", "policy_id": "FENGZE_POL_036", "course_period": "2025-08至2025-09"}, {"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 47395, "end_char": 47465, "line": 1, "excerpt": "第11题选b选项啊。然后往下同学们，我们把这个四和五就是把这个政策给大家讲完好吗？同学们把四和五政策讲完啊，因为我知道你们中午还有课啊，但是", "policy_id": "FENGZE_POL_035", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.government','political_theory.policy','行测','政治理论','政府工作报告','topic',1,1,'gongkao.xingce.political_theory.policy.government','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 49249, "end_char": 49326, "line": 1, "excerpt": "降低财政赤字率错了吧？哎，刚才是说的是提高财政赤字率对不对？哎，然后说停止超长期特别国债，那也错了啊，应该是增发超长期特别国债。哎，然后其他两个这个都对了", "policy_id": "FENGZE_POL_038", "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 626, "end_char": 714, "line": 3, "excerpt": "国内生产总值增长5%左右，这个是不是和去年是持平的，对吧？哎，因为去年的时候我们强调二零二四年它的国内生产总值增长是一百三十四点九万亿。对不对诶？然后增长是多少？增长不就5%嘛", "policy_id": "FENGZE_POL_037", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.rural','political_theory.policy','行测','政治理论','三农与乡村振兴','topic',1,1,'gongkao.xingce.political_theory.policy.rural','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 32313, "end_char": 32613, "line": 3, "excerpt": "紧接着往下两个确保，确保是啥呢？这是过去我们在讲到呃二四年一号文件的时候说到的，我们要确保两条底线。啊，所以我们经常叫两个底线嘛，哪两个底线一个强调的是确保国家粮食安全底线，另外一个是确保不发生规模性返贫置贫底线。看到了吧？哎，这是两条底线啊，也要从整个的这个农业发展上对不对？哎，从三农的这个角度上，我们强调两条底线，一个是粮食安全，一个是哎，不发生规模性返贫置贫的底线。那么，三个提升，三个提升，提升啥？同学们，其实这是过去在二四年一号文件当中提出的，叫三项重点工作。啊三项重点工作，那我们后面讲的很多的举措，同学们，你会发现它都是围绕着两个确保和三个提升来的啊，哪三项重点工作呢？第一个强调。提", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 10062, "end_char": 10362, "line": 1, "excerpt": "之外，剩下的同学们都是一样的，和我们之前讲的一号文件的说法是完全一样的，你看比如说我们。之前给大家强调的两条底线，对吧？哎，哪两条底线啊？同学们，一个是确保国家粮食安全底线，另外一个就是确保农业呃，农村人口不发生规模性返贫底线啊。啊，然后紧接着再往下三项重点工作，哪三项重点工作呀？是不是哎？以提升乡村产业发展，乡村建设，乡村治理水平啊？那你可以记按照之前的这个记啊。叫什么叫产建制？看到了吗？产建制啊，你可以按照这个去记好不好？哎，好了啊，这是在这一块儿，然后最后这五个振兴了解就行了，好吧，哎，这个不作为重点啊，产业人才。文化生态组织振兴，这提了太久了啊，提了太久了好了，这是在这儿啊，我们给大家", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 8886, "end_char": 8962, "line": 1, "excerpt": "锚定建设农业强国目标，哎，同学们来啊。重点内容一定要回过神儿来了啊，重点内容看我们这一块儿讲到的内容，你会发现它和我们前面讲一号文件的一些表述就不一样了", "policy_id": "FENGZE_POL_039", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.plans','political_theory.policy','行测','政治理论','专项政策与规划','topic',1,1,'gongkao.xingce.political_theory.policy.plans','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 10217, "end_char": 10517, "line": 1, "excerpt": "后紧接着再往下进一步形成人才辈出，人尽其才，人尽其用的生动局面，这就不说了，同学们啊，这三个词。看一看就可以了啊，可出题的点其实不是特别的多，然后往下第二个建设教育强国啊，科技强国，人才强国，必须坚持什么呢？正确的办学方向先理解这个。同学们，还记不记得正确的办学方向是什么方向？同学们非常好，我看到了花生不识数，同学对吧？唉，是社会主义的办学方向。啊，社会主义办学方向千万记住啊，这是我们后面讲新思想的时候，其实会讲到的啊，也就是本身关于正确的办学方向的问题，哪个方向其实就是我们。啊，这个整个大的层面上是要坚持社会主义的办学方向，这个就是啥意思呢？也就是你不要在这个培养人才的过程当中，对不对？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 8508, "end_char": 8808, "line": 3, "excerpt": "一点儿。那么，往下第三个啊，我们强调深入实施科教兴国战略，提升国家创新体系的整体效能，那怎么实行科科教兴国呢？首先，第一个强调了一个数字啊。数字这块说，制定实施教育强国建设的三年行动计划啊，我们之前啊，给大家也说过这个问题，就是如果说在一整道题当中，你会发现啊。呵呵呵，是别骂了，题是我出的，同学们别骂了好吗？哈哈哈，题是我出的啊。就是呃，如果啊，在一个题当中，他所有的一些这个选项都没有去提到这个呃年份的这个问题，知道吗？哎，都没有提到这个年份数字的问题而。只有一个选项提到了年份的问题，你就要重点关注了，知道了吗？同学们哎，那他很有可能，你看把这个三年就改成五年对不对？哎，等等，类似于这种啊，所", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 73, "end_char": 373, "line": 1, "excerpt": "给大家讲到了第三章对不对哎？第三章呢？然后我们把这个重要的文件。前两个也就是政府工作报告以及中央一号文件给大家讲完了，那么今天呢？我们继续开始讲啊，就是讲第三个教育强国建设规划纲要二零二四到二零。二零三五年，所以之前的时候，如果大家啊没没及时跟课的对吧？然后今天来了那把这个讲义啊，打到咱们这个章节好吧？那么来看啊，在这个章节当中，其实你会发现啊，关于教育强国的很多问题，我们在之前的时候给大家多多少少讲到新思想的时候，其实有一些问题是强调过的，对吧？哎，那先来看第一个啊，在这个规划纲要当中，第一个需要大家掌握的知识点就在这儿了，看到了吧？哎，也就是坚持什么样的一种办学方向，那么我们前面在讲到这个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250921 政治理论(时政)加课6.doc.txt", "source_sha256": "862757d3895e3eb6851995aeed8aa859c9f6e438490910fcff7e4a59da6f6037", "start_char": 186, "end_char": 240, "line": 1, "excerpt": "加快建设农业强国，规划二零二四到二零。二零三五年，那么首先第一个啊，大家先明确的就是我们未来所要建成的这个农", "policy_id": "FENGZE_POL_041", "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 508, "end_char": 538, "line": 1, "excerpt": "坚持社会主义的办学方向。那么，同样啊，落实立德树人的根本任务", "policy_id": "FENGZE_POL_040", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.culture','political_theory.thought','行测','政治理论','文化建设与意识形态','topic',1,1,'gongkao.xingce.political_theory.thought.culture','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 4571, "end_char": 4871, "line": 1, "excerpt": "，你就要时刻的把人民放在心里，把国家放在心里啊。好了，这是在这儿啊，这个点就讲到这儿好吧，唉，多余的咱就不讲了啊，好，那紧接着往下来看啊，第三个就是关于社会主义核心价值观的问题了。这个点呢，我只能说它很重要，但是我们现在考试考的少，能理解吗？同学们啊，因为关于社会主义核心价值观的问题啊，我们在前些年的考试当中。啊，尤其是在很多事业单位考试当中啊，他把这个东西基本上考烂了啊，就直接问你啊，考的也非常简单，就直接问你说社会主义核心价值观，它在国家层面的表述是什么？同学们啊，其实就这12个词，你对应记清楚就行了，很简单，国家层面叫什么叫富强，民主，文明，和谐。啊，你多记多背几遍，其实这个马上啊就就记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 16554, "end_char": 16854, "line": 1, "excerpt": "这个情况之下，你看强化我们的内外联通啊，内外联通啊。啊，那内联外通啊，内联外通内联外通啊，好，这是在这儿啊，往下第四个弘扬核心价值，促进包容和谐，还有我们的这种核心价值观的问题啊。好了，这是在这儿，同学们，你看呃这几句话呢，你可以这样去记啊，叫依法内心啊，依法内心一强调的叫一国之本，对不对？哎，发强调高质量发展，高水平安全嘛。啊，然后内强调内廉外通对不对？新强调弘扬核心价值啊，所以在这一块的时候，同学们你注意啊，因为这这两句话说实话，它四句话加到一起比较长嘛，是不是？所以你就。啊，记一些关键词，把它能够记住就行了啊，所以叫一发内心啊，一发内心好，这是四条经验，那紧接着往下又对新一届的这个澳门特", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.ecology','political_theory.thought','行测','政治理论','生态文明建设','topic',1,1,'gongkao.xingce.political_theory.thought.ecology','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15789, "end_char": 16089, "line": 1, "excerpt": "会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？经济，政治，文化，社会，生态文明，按照这个方向去思考，你也不用把这几句话完全背下来，对吧？唉，你也能知道他到底在说什么？然后紧接着发展中特儿就只剩最后一个了，中国特色社会主义对吧？唉，所以我们强调本质要求，强调的是党人按照五位一体发展中特儿。好吧，唉，按照这个去记就可以了啊，好了，这是本质要求，那么回过头来看下面第第三个问题就是重大原则啊。重大原则，这个东西呢，你注意，一般我们后面在讲到关于原则性的问题的时候，就是在实现中国式现代化的过程当中，这些东西是不能变", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 34913, "end_char": 35213, "line": 1, "excerpt": "一定要抓住这些题里面能够出题挖坑的点，然后去思考它有没有挖坑，对不对？有没有改啊？这是主要的。好，这是第二个啊，然后紧接着同学们往下咱们来看第12章建设社会主义生态文明啊，那么生态文明建设这一块呢，来看一下啊，第一个。说到他的地位，这个地位一定要记住的啊，生态文明建设是关系中华民族永续发展的根本大计啊，根本大计，你看你就直接记生根就行了，对吧？哎，正好和这个生态环境相关嘛。而且你直接去理解也行，同学们啊，为什么说生态文明它是永续发展的根本大计啊？其实很简单啊，我们之前多次给大家说到过，就是生态环境问题，它不仅仅关系的是我们一代人的问题，能理解吗？哎。它关系到的是我们子孙后代代代人的问题，所以在", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.security','political_theory.thought','行测','政治理论','总体国家安全观','topic',1,1,'gongkao.xingce.political_theory.thought.security','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11443, "end_char": 11743, "line": 1, "excerpt": "域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没有说直接全部给你放开啊，所以这个时候你要保证一定的国家安全啊，因为你有很多行业，一旦啊，给它完全放开之后。它这个时候就会受到冲击，那就会就会出现这个问题，而最后一个就是我们一直在说的我们国家的经济体制，对吧？社会主义市场经济体制一方面要发挥市场的决定性作用，对不对？另外一个方面要发挥什么？发挥政府的宏观调控作用啊好，你看其实实际上你这样前后去对着去记，我感觉还是相对来说比较简单的，对不对？哎，还是比较简单的啊，哎呀，我非常我非常欣慰，我看到有一个同学说说，今天听着听着课好像开悟了，是不", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 46954, "end_char": 47254, "line": 1, "excerpt": "对不对哎？以国家公园为主体，然后三生道路，这不都是刚才说的吗？啊，好了，这是在这儿啊，第二题选的是c好吧嗯。然后紧接着同学们来往下看啊，往下看第13章维护和塑造国家安全啊，那么关于国家安全的问题啊，国家安全的问题来看啊来看。脑子塞不下了呀，塞不下也得塞，同学们啊，咱现在也不能下课，知道吧，还有半个小时呢啊，实在不行了，对吧，站起来啊。啊，那个拍拍自己的脸是不是如果感觉还不清醒，那就用点儿力啊，再不清醒再用点儿力是不是到最后你真的把自己？啪一下子对不对哎？就给打醒了，那个时候就行了啊，来吧，同学们先来看啊，总体国家安全观这一块，他说到的这个。坚持总体国家安全观。那安全观到底是什么？咱是不是得了解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 13225, "end_char": 13525, "line": 1, "excerpt": "后紧接着再往下第二个四体啊，我说了这个东西一般它不会挖坑，对不对哎？所以你大概读完之后没有什么错误的，你就默认它是对的就行了啊。紧接着再往下第二个二零二四年总体国家安全观提出十周年，是不是啊？同学们二零一四年啊，不是二零二四年啊，二零二四年。是不是啊？嗯，是不是啊？是呀，同学们嗯，哎呀。你回去啊，回去去看一看啊，回去去看一看，我们当时说的那个十周年是什么十周年，对吧？而我们当时明确给大家说的是二零一四年的时候，当时习近平总书记提出的。总体的国家安全观能理解吗？哎，然后他把二零呃，这个把那个4月15日哎，二四月十五日在二零一五年的时候，然后给他确定为了这个全民国家安全教育日。能理解吗？然后二五年", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.defense','political_theory.thought','行测','政治理论','国防与人民军队','topic',1,1,'gongkao.xingce.political_theory.thought.defense','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 0, "end_char": 233, "line": 1, "excerpt": "14章节啊，我们的这个强大人民军队啊，所以如果之前没有跟着课的同学啊，今天呢呃，这个过来听课对吧？咱们把这个讲义啊打到第14章节好吧？好了，来看啊，在第14章节这一块儿呢，强调这个关于建设巩固国防和强大人民军队的问题。呃，那么今年呢？呃，针对于军队国防的这个问题呃，因为这个九三阅兵的问题是不是呃，所以呢，它呃会是我们在考试过程当中的一个重点内容。能理解吧，好，所以接下来啊啊，接下来我们来看一看啊，首先第一个就是关于这个军队建设，它对于我们的这个重要性在哪？那首先", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.diplomacy','political_theory.thought','行测','政治理论','中国特色大国外交','topic',1,1,'gongkao.xingce.political_theory.thought.diplomacy','','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15557, "end_char": 15857, "line": 1, "excerpt": "一体发展中特。啥意思呢？你看第一个党坚持党的领导，毕竟别的国家没有中国共产党的领导，对不对？哎，只有我们国家有，然后其次。人强调的是什么？强调的是后是后两个一个人类命运共同体，一个人类文明新形态，所以这是党人啊，然后按照五位一体同学们哪五位一体啊？看从这儿开始啊，第一个标一下经济是不是强调高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。紧接着，从这个社会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 56901, "end_char": 57201, "line": 1, "excerpt": "化是更基础，更广泛，更深厚的自信啊，它是最基本，最深沉，最持久的力量，明确它就行了啊。要不然的话，你想想同学们，你为什么现在习近平总书记在国际的讲话当中经常提叫人类命运共同体，对不对？他提这个东西啊，为什么很多人能信服？对不对？包括我们国家的很多的民众，你去向一些外国友人介绍这个东西的时候对不对？唉，你看你说我们现在正在创建人类命运共同体。你为什么能够很自信的把这个东西说出来，去向他介绍，不就是因为我们一直在说古代文化当中，中国一直在强调大同社会的理念，对吧？唉，这是古人就已经有的这样一种啊观念，我们只不过是现在把它拿出来了，对不对？唉，拿出来介绍给你，这就是中国古人的东西啊。所以你看最后他说", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 29255, "end_char": 29555, "line": 1, "excerpt": "？对不对？哎，所有的外交工作其实实际上都是为了啥呀？同学们。不就是为了主权，安全，发展利益嘛，对不对？哎，说了太多遍了啊，好了，然后紧接着往下同学们看第三个构建人类命运共同体的问题。这个人类命共同体这一块儿呢，大家可以看啊呃，首先啊，他提到了说这个构建人类命共同体呢，是当代中国共产党人回答和解决人类前途命运的时代之问的中国方案。哎，也是我们新时代对外工作的一个总目标，了解就行，同学们啊，了解就行，那么往下第一个啊，先明确构建人类命运共同体。它是世界各国人民的前途所在，那什么叫人类命运共同体啊？同学们记住这五个词要有印象啊。五个词强调，持久和平，普遍安全，共同繁荣，开放包容和清洁美丽。看到了吗？", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.fengze_pol_005','political_theory.marx.materialism','行测','政治理论','哲学基本问题：唯物主义与唯心主义','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.fengze_pol_005','哲学基本问题第一性定党性：何者为第一性决定哲学两大基本派别（唯物主义 vs 唯心主义），无第三个基本派别。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26642, "end_char": 26757, "line": 1, "excerpt": "基本的哲学派别只有唯物主义和唯心主义这两个，而我们所学的其他的很多非常细微的哲学理论，像我刚才提到的古代朴素唯物主义，对吧？近代形而上小唯物主义啊，马克思主义哲学以及主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_005", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.fengze_pol_006','political_theory.marx.materialism','行测','政治理论','可知论与不可知论','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.fengze_pol_006','思维存在同一性定可知论：承认思维能正确认识世界是可知论，否认是不可知论；唯物主义都是可知论，但黑格尔唯心也是可知论。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26976, "end_char": 27037, "line": 1, "excerpt": "为我们这个世界是能够被认知的，所以这就是一种典型的可知论的观点。能理解吧唉，然后第二种观点就是你认为思维不能够认识客观世界", "policy_id": "FENGZE_POL_006", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.fengze_pol_007','political_theory.marx.materialism','行测','政治理论','主观唯心与客观唯心辨析法','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.fengze_pol_007','主观唯心与客观唯心辨析：本原在人的心灵/感觉为主观唯心；本原在脱离人体的神秘外在精神/天理/上帝为客观唯心。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26725, "end_char": 26757, "line": 1, "excerpt": "主观唯心，客观唯心等等，都是在这两个派别的基础之下，它又划分了。", "policy_id": "FENGZE_POL_007", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.fengze_pol_008','political_theory.marx.materialism','行测','政治理论','古代朴素与近代形而上学唯物主义缺陷辨析','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.fengze_pol_008','唯物主义三形态辨析：古代朴素归结为具体实物；近代形而上学归结为原子且有机械性、孤立片面、半截子唯物三大缺陷；马哲归结为客观实在性。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 26594, "end_char": 26663, "line": 1, "excerpt": "唯物主义之下还有什么古代朴素近代形，而上学是不是但是要注意我问的是基本的哲学派别。能理解吗？唉，基本的哲学派别只有唯物主义和唯心主义这两个", "policy_id": "FENGZE_POL_008", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.fengze_pol_009','political_theory.marx.materialism','行测','政治理论','庸俗唯物主义把意识等同于物质的本质辨析','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.fengze_pol_009','庸俗唯物主义辨析：把意识等同于物质、宣称大脑分泌意识如肝脏分泌胆汁系庸俗唯物主义，马哲坚持意识是主观映象。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 38365, "end_char": 38447, "line": 1, "excerpt": "像旧唯物主义或者说庸俗唯物主义这样的一些说法。什么说法呢啊，什么下课呀，同学们到十点呢，哎呀，到十点了啊，好，那到底什么是旧唯物主义，什么叫庸俗唯物主义呢，同学们？", "policy_id": "FENGZE_POL_009", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.fengze_pol_010','political_theory.marx.materialism','行测','政治理论','物质的客观实在性与运动属性','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.fengze_pol_010','物质特性与属性区分法：唯一特性是客观实在性，根本属性和存在方式是运动；二者互换必错。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 36502, "end_char": 36584, "line": 1, "excerpt": "做了最高的概括，指出客观实在性是物质的本质属性。同学们，你们有没有有没有发现就是马克思主义哲学和过去的两个古代朴素和近代形而上学？他认为物质的观点不太一样了，对吧？", "policy_id": "FENGZE_POL_010", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.fengze_pol_011','political_theory.marx.dialectics','行测','政治理论','唯物辩证法两大特征普遍联系与永恒发展','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.fengze_pol_011','辩证法两大特征：普遍联系（客观、普遍、多样、有条件）与永恒发展（实质是新事物产生旧事物灭亡）；反对无条件联系论。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 99, "end_char": 187, "line": 1, "excerpt": "是第三节的唯物辩证法，所以各位同学如果之前对吧呃，这个前两节课没跟到，包括可能有最近刚进来的各位同学啊。把政治理论的那本儿讲义打到咱们的第三节唯物辩证法，这个章节当中好不好嗯？", "policy_id": "FENGZE_POL_011", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.fengze_pol_012','political_theory.marx.dialectics','行测','政治理论','主要矛盾与次要矛盾','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.fengze_pol_012','主要矛盾判断法：多个矛盾中居支配地位、起决定作用的是主要矛盾；标志词为抓重点、抓中心、牵牛鼻子、首要任务。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 41145, "end_char": 41202, "line": 1, "excerpt": "所谓的主要矛盾看书上标红的这句话就行了啊，这种居于支配地位对事物的发展过程起决定作用的矛盾就是什么？就是主要矛盾。", "policy_id": "FENGZE_POL_012", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.fengze_pol_013','political_theory.marx.dialectics','行测','政治理论','矛盾的主要方面与次要方面','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.fengze_pol_013','矛盾主要方面定性法：一个矛盾内部处支配地位、起主导作用的方面为主要方面，决定事物性质；主流与支流、利大于弊对应主要方面。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 41145, "end_char": 41235, "line": 1, "excerpt": "所谓的主要矛盾看书上标红的这句话就行了啊，这种居于支配地位对事物的发展过程起决定作用的矛盾就是什么？就是主要矛盾。啊，那反过来就好理解了呀，所谓的次要矛盾指的就是处于从属地位不起决", "policy_id": "FENGZE_POL_013", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.fengze_pol_014','political_theory.marx.dialectics','行测','政治理论','质量互变规律度与关节点辨析法','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.fengze_pol_014','质量互变规律法则：量变是必要准备，质变是必然结果；度是质与量的统一限度，做事情坚持适度原则、防微杜渐。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 170, "end_char": 249, "line": 1, "excerpt": "这个第二个量变质变规律，那么量变质变规律这一块儿呢，大家看一下啊，首先呢，说到它揭示了事物发展的形势和状态。那么，具体它事物是以什么样的形式和状态去发展的呢？", "policy_id": "FENGZE_POL_014", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.fengze_pol_015','political_theory.marx.dialectics','行测','政治理论','否定之否定规律螺旋式上升与前进曲折性统一','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.fengze_pol_015','否定之否定规律法则：揭示事物发展的方向与道路；辩证否定实质是扬弃；发展总趋势前进上升，道路曲折迂回。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 9167, "end_char": 9238, "line": 1, "excerpt": "第三个否定之否定规律。否定之否定规定呢？它揭示的是事物发展的方向和道路。那么来看啊，所谓否定之否定，我们在语文上说双重否定是表肯定的，对不对？", "policy_id": "FENGZE_POL_015", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.epistemology.fengze_pol_016','political_theory.marx.epistemology','行测','政治理论','实践是认识基础的四重维度判定法','concept',1,1,'gongkao.xingce.political_theory.marx.epistemology.fengze_pol_016','实践是认识基础四维度：实践是来源（唯一源泉）、动力、目的和检验真理的唯一标准；逻辑证明仅为辅助检验手段。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 650, "end_char": 743, "line": 1, "excerpt": "首先第一个强调实践是认识的来源。那这块儿同学们啊，我们之所以说它重要啊，另呃，其实从一个方面来说就是因为在实践决定认识这一块儿，刚才强调它是有四个方面的表现的。那你要学会去区分这四个方面", "policy_id": "FENGZE_POL_016", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.epistemology.fengze_pol_017','political_theory.marx.epistemology','行测','政治理论','真理的客观性、绝对性与相对性统一法则','concept',1,1,'gongkao.xingce.political_theory.marx.epistemology.fengze_pol_017','真理属性法则：真理具有客观性（内容客观、一元性）、绝对性与相对性；真理必有用但有用不等于真理；超界转化为谬误。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 6369, "end_char": 6444, "line": 1, "excerpt": "践是检验认识是否具有真理性的唯一标准。那么这个是啥意思？你看同学们，当我们在实践当中产生了某种认识之后，我们是希望能够用这种认识去改造世界的，对不对？", "policy_id": "FENGZE_POL_017", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.history.fengze_pol_018','political_theory.marx.history','行测','政治理论','社会存在与社会意识辩证关系基本定性','concept',1,1,'gongkao.xingce.political_theory.marx.history.fengze_pol_018','社会存在与意识法则：社会存在决定社会意识（唯物史观基石）；社会意识具有相对独立性，能动反作用于社会存在。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 460, "end_char": 495, "line": 1, "excerpt": "社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾", "policy_id": "FENGZE_POL_018", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.history.fengze_pol_019','political_theory.marx.history','行测','政治理论','生产力与生产关系矛盾运动及工具标志法','concept',1,1,'gongkao.xingce.political_theory.marx.history.fengze_pol_019','生产力与生产关系法则：生产工具是生产力水平客观标志，所有制形式是生产关系基础；生产力决定生产关系。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 471, "end_char": 529, "line": 1, "excerpt": "生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个", "policy_id": "FENGZE_POL_019", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.history.fengze_pol_020','political_theory.marx.history','行测','政治理论','经济基础与上层建筑矛盾运动及制度属性','concept',1,1,'gongkao.xingce.political_theory.marx.history.fengze_pol_020','经济基础与上层建筑法则：政治上层建筑以国家政权为核心；全面深化改革本质是调整上层建筑与经济基础适应。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11864, "end_char": 11957, "line": 1, "excerpt": "我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？有同学说老师啥叫上层建筑没学？马哲对不对？哎，其实很简单，所谓的上层建筑就是改制度，改体系", "policy_id": "FENGZE_POL_020", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.economics.fengze_pol_021','political_theory.marx.economics','行测','政治理论','商品二因素与劳动二重性对应统一法则','concept',1,1,'gongkao.xingce.political_theory.marx.economics.fengze_pol_021','商品二因素与劳动二重性：具体劳动创造使用价值（自然属性），抽象劳动形成价值（本质社会属性）；是同一劳动的两个方面。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 188, "end_char": 247, "line": 3, "excerpt": "商品的二因素，对吧？劳动的二重性以及商品价值量，它是由什么所决定的啊？价值规律等等，这些内容给大家做了一个简单的介绍。", "policy_id": "FENGZE_POL_021", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.economics.fengze_pol_022','political_theory.marx.economics','行测','政治理论','绝对剩余价值、相对剩余价值与超额剩余价值辨析','concept',1,1,'gongkao.xingce.political_theory.marx.economics.fengze_pol_022','剩余价值辨析法：绝对剩余价值靠延长工时/加重劳动；相对剩余价值靠全社会生产率提高缩短必要劳动时间；超额剩余价值靠个别生产率领先。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 4169, "end_char": 4256, "line": 3, "excerpt": "增值的价值，即剩余价值。看到了同学们这200块钱就是我们强调的叫剩余价值啊。所以你看他最后说到一旦货币所购买的劳动力带来了剩余价值，这个时候货币就不叫货币了，叫什么叫资本了？", "policy_id": "FENGZE_POL_022", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.system.fengze_pol_023','political_theory.thought.system','行测','政治理论','两个结合精髓与党的理论创新源泉','concept',1,1,'gongkao.xingce.political_theory.thought.system.fengze_pol_023','两个结合法则：同中国具体实际相结合、同中华优秀传统文化相结合，是推进马克思主义中国化时代化的根本途径。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 6243, "end_char": 6379, "line": 1, "excerpt": "关于两个结合的问题，那你得知道两个结合对吧？这里还是得需要你明确知道两个结合到底是啥的。两个结合，同学们来有没有同学记着的，之前我们说的两个结合是什么？它是经济工作吗？同学们，它是经济工作吗？不是唉，我们强调的两个结合与中国的传统文化相结合，与中国的具体实际相结合，对吧？", "policy_id": "FENGZE_POL_023", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.modernization.fengze_pol_024','political_theory.thought.modernization','行测','政治理论','中国式现代化五大特征与本质要求辨析','concept',1,1,'gongkao.xingce.political_theory.thought.modernization.fengze_pol_024','中国式现代化辨析法：牢记五大特色（人口规模巨大/共同富裕/物质精神协调/人与自然和谐/和平发展）与九大本质要求；党的领导是最本质特征。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 119, "end_char": 209, "line": 1, "excerpt": "中国式现代化全面推进中华民族伟大复兴的这个问题啊。好了，来吧，同学们，今天晚上呢，咱们预计啊呃，讲到大概第六章结束啊，大家可以看一下你的讲义好吧嗯。好了啊，那先来看一下第一个问题，", "policy_id": "FENGZE_POL_024", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy.fengze_pol_025','political_theory.thought.economy','行测','政治理论','高质量发展是全面建设现代化国家首要任务','concept',1,1,'gongkao.xingce.political_theory.thought.economy.fengze_pol_025','高质量发展法则：高质量发展是首要任务；坚持完整准确全面贯彻新发展理念，实现质的有效提升和量的合理增长。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15702, "end_char": 15781, "line": 1, "excerpt": "高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。", "policy_id": "FENGZE_POL_025", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy.fengze_pol_026','political_theory.thought.economy','行测','政治理论','因地制宜发展新质生产力及反对一哄而上','concept',1,1,'gongkao.xingce.political_theory.thought.economy.fengze_pol_026','新质生产力法则：以创新为主导、以全要素生产率大幅提升为核心标志；坚持因地制宜，绝非忽视或放弃传统产业，严禁一哄而上。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 7910, "end_char": 7980, "line": 3, "excerpt": "例15这道题选什么同学们啊？这道题选什么？直接打就行了啊，因为同学们，我这个我上这个政治理论课程的时候，我没有其他的教研老师帮助我发那个投票", "policy_id": "FENGZE_POL_026", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy.fengze_pol_027','political_theory.thought.economy','行测','政治理论','社会主义基本经济制度的三大内涵统一定位','concept',1,1,'gongkao.xingce.political_theory.thought.economy.fengze_pol_027','基本经济制度法则：包含所有制（公有制为主体多种并存）、分配制（按劳为主多种并存）和体制（社会主义市场经济体制）三位一体。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 235, "end_char": 335, "line": 1, "excerpt": "以公有制为主体啊，因为书上有，所以这个呢，我就不写全了啊，大家有印象就行了，以公有制经济。为主体对不对唉？然后非公有制经济啊呃，这个共同发展，然后第二个也就是我们今天要给大家讲到的，强调按劳分配为主体", "policy_id": "FENGZE_POL_027", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.democracy.fengze_pol_028','political_theory.thought.democracy','行测','政治理论','全过程人民民主最广泛、最真实、最管用法则','concept',1,1,'gongkao.xingce.political_theory.thought.democracy.fengze_pol_028','全过程人民民主法则：是社会主义民主政治本质属性；最广泛、最真实、最管用；人民当家作主是本质特征。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 34155, "end_char": 34235, "line": 1, "excerpt": "主政治的本质属性就是全过程人民民主。啊，关于全过程人民民主这个词，我们一会儿会专门解释啊，大家先理解先知道这个词就行了，那么什么叫社会主义民主政治的本质属性呢？", "policy_id": "FENGZE_POL_028", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.democracy.fengze_pol_029','political_theory.thought.democracy','行测','政治理论','全面依法治国法治国家、政府、社会一体建设','concept',1,1,'gongkao.xingce.political_theory.thought.democracy.fengze_pol_029','全面依法治国法则：总目标是建设法治体系与法治国家；共同推进一体建设；法治政府建设是重点任务和主体工程。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 35732, "end_char": 35822, "line": 1, "excerpt": "党的领导是人民当家作主和依法治国的根本保证，说了太多遍了吧，党的领导就是根本保证对吧，因为你想啊，同学们没有党的领导，我们会我们大家会使。实现人民当家作主吗？同学们会实现依法治国吗", "policy_id": "FENGZE_POL_029", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.party.fengze_pol_030','political_theory.thought.party','行测','政治理论','自我革命是跳出治乱兴衰历史周期率的第二个答案','concept',1,1,'gongkao.xingce.political_theory.thought.party.fengze_pol_030','跳出历史周期率法则：第一个答案是人民监督，第二个答案是党的自我革命；全面从严治党是新时代伟大实践。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34986, "end_char": 35062, "line": 1, "excerpt": "第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关", "policy_id": "FENGZE_POL_030", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform.fengze_pol_031','political_theory.policy.reform','行测','政治理论','三中全会改革总目标与2035/2029时间线节点','concept',1,1,'gongkao.xingce.political_theory.policy.reform.fengze_pol_031','三中全会总目标时间线：2035年全面建成高水平市场经济体制、基本实现现代化；2029年建国80周年完成改革任务；对调必错。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15837, "end_char": 15922, "line": 1, "excerpt": "错了呀？我们书上说的是建国80周年，对吧？哎，中华人民共和国建成80周年啊，所以在这里面注意啊。这道题选的是。b选项啊，也就是二和四错了啊，一个时间错了一个具体的表述错了", "policy_id": "FENGZE_POL_031", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform.fengze_pol_032','political_theory.policy.reform','行测','政治理论','进一步全面深化改革的六大重大原则','concept',1,1,'gongkao.xingce.political_theory.policy.reform.fengze_pol_032','三中全会六大原则：坚持党的全面领导、以人民为中心、守正创新、以制度建设为主线、全面依法治国、系统观念。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 15979, "end_char": 16069, "line": 1, "excerpt": "进一步全面深化改革的原则。啊，这个呢，大家听一听就行啊，虽然我们也给大家出题了，但是呢啊，不作为一个重点，为什么？因为从之前啊，我们呃，就是国省考它出题的这个内容上来看它很少。出这", "policy_id": "FENGZE_POL_032", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform.fengze_pol_033','political_theory.policy.reform','行测','政治理论','以经济体制改革为牵引与高水平市场经济体制','concept',1,1,'gongkao.xingce.political_theory.policy.reform.fengze_pol_033','经济体制改革牵引法则：以经济体制改革为牵引，以促进社会公平正义、增进人民福祉为出发点落脚点；放得活又管得好。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 11811, "end_char": 11912, "line": 1, "excerpt": "以经济体制改革为牵引，为什么是以经济体制改革为牵引？我刚才提到了一个问题，我没在书上写啊，你看我刚才说了，我说改革。他改什么？对吧，他改什么？我刚才提了这么一个点，改什么？是不是我刚才强调了改上层建筑？", "policy_id": "FENGZE_POL_033", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform.fengze_pol_034','political_theory.policy.reform','行测','政治理论','市场经济基础制度四大构成排他法','concept',1,1,'gongkao.xingce.political_theory.policy.reform.fengze_pol_034','市场经济基础制度法则：由产权保护、市场准入、公平竞争、社会信用四大支柱构成；混入财政/金融体制必错。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 4256, "end_char": 4314, "line": 1, "excerpt": "会当中，他说到的这么一个东西就是关于完善市场经济基础制度。这个当时我不知道有没有同学掉坑的，对吧？关于市场经济的基础", "policy_id": "FENGZE_POL_034", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.economy.fengze_pol_035','political_theory.policy.economy','行测','政治理论','稳中求进以进促稳先立后破总基调与政策取向一致性','concept',1,1,'gongkao.xingce.political_theory.policy.economy.fengze_pol_035','经济工作会议总基调：稳中求进、以进促稳、先立后破；增强宏观政策取向一致性，非经济政策纳入评估。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 47395, "end_char": 47465, "line": 1, "excerpt": "第11题选b选项啊。然后往下同学们，我们把这个四和五就是把这个政策给大家讲完好吗？同学们把四和五政策讲完啊，因为我知道你们中午还有课啊，但是", "policy_id": "FENGZE_POL_035", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.economy.fengze_pol_036','political_theory.policy.economy','行测','政治理论','扩大国内需求重点举措投资消费双轮驱动','concept',1,1,'gongkao.xingce.political_theory.policy.economy.fengze_pol_036','扩大国内需求法则：消费与投资良性循环；传统消费与新型消费并重，发挥政府投资带动放大效应。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 329, "end_char": 412, "line": 3, "excerpt": "扩大内需，那既然是扩大内需，之前给大家讲过内需。它包括两个方面，哪两个方面？一个是消费，另外一个就是投资，看到了吗？同学们，唉，所以在这里面啊，首先你要先了解国内需求", "policy_id": "FENGZE_POL_036", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.government.fengze_pol_037','political_theory.policy.government','行测','政治理论','2025政府工作报告经济发展预期目标与赤字率','concept',1,1,'gongkao.xingce.political_theory.policy.government.fengze_pol_037','2025政府工作报告指标：国内生产总值增长5%左右；赤字率拟按3%左右安排；超长期特别国债专项统筹两重建设。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 626, "end_char": 714, "line": 3, "excerpt": "国内生产总值增长5%左右，这个是不是和去年是持平的，对吧？哎，因为去年的时候我们强调二零二四年它的国内生产总值增长是一百三十四点九万亿。对不对诶？然后增长是多少？增长不就5%嘛", "policy_id": "FENGZE_POL_037", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.government.fengze_pol_038','political_theory.policy.government','行测','政治理论','超长期特别国债与两重建设战略协同','concept',1,1,'gongkao.xingce.political_theory.policy.government.fengze_pol_038','超长期特别国债法则：专项用于国家重大战略实施和重点领域安全能力建设（两重建设），协同推进两新政策。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 49249, "end_char": 49326, "line": 1, "excerpt": "降低财政赤字率错了吧？哎，刚才是说的是提高财政赤字率对不对？哎，然后说停止超长期特别国债，那也错了啊，应该是增发超长期特别国债。哎，然后其他两个这个都对了", "policy_id": "FENGZE_POL_038", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.rural.fengze_pol_039','political_theory.policy.rural','行测','政治理论','2025中央一号文件守住两条底线与推进乡村全面振兴','concept',1,1,'gongkao.xingce.political_theory.policy.rural.fengze_pol_039','中央一号文件法则：以千万工程经验为引领；牢牢守住国家粮食安全和不发生规模性返贫两条底线；抓好三提升一强化。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 8886, "end_char": 8962, "line": 1, "excerpt": "锚定建设农业强国目标，哎，同学们来啊。重点内容一定要回过神儿来了啊，重点内容看我们这一块儿讲到的内容，你会发现它和我们前面讲一号文件的一些表述就不一样了", "policy_id": "FENGZE_POL_039", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.plans.fengze_pol_040','political_theory.policy.plans','行测','政治理论','教育强国建设规划纲要办学方向与根本任务','concept',1,1,'gongkao.xingce.political_theory.policy.plans.fengze_pol_040','教育强国规划法则：坚持社会主义办学方向；落实立德树人根本任务；统筹推进教育科技人才一体化发展。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 508, "end_char": 538, "line": 1, "excerpt": "坚持社会主义的办学方向。那么，同样啊，落实立德树人的根本任务", "policy_id": "FENGZE_POL_040", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.plans.fengze_pol_041','political_theory.policy.plans','行测','政治理论','加快建设农业强国规划基本要求与供给保障','concept',1,1,'gongkao.xingce.political_theory.policy.plans.fengze_pol_041','建设农业强国法则：首要任务是保障粮食与重要农产品稳定安全供给；立足大国小农国情，坚持科技改革双轮驱动。','{"source": "fengze_politics_course_catalog", "aliases": [], "course_sources": [{"source_file": "20250921 政治理论(时政)加课6.doc.txt", "source_sha256": "862757d3895e3eb6851995aeed8aa859c9f6e438490910fcff7e4a59da6f6037", "start_char": 186, "end_char": 240, "line": 1, "excerpt": "加快建设农业强国，规划二零二四到二零。二零三五年，那么首先第一个啊，大家先明确的就是我们未来所要建成的这个农", "policy_id": "FENGZE_POL_041", "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.topic_1','political_theory.marx.materialism','行测','政治理论','意识与物质的关系','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.topic_1','课程知识：意识与物质的关系。什么都回归到这个问题上，也就是思维与存在的关系问题。啊，所以后面我们才提到了这个问题，也就是哲学的基本问题是思维与存在的关系问题。那或者我们说另外一个点就是它是意识和物质的关系问题，这两个说哪个都可以知道吧？两种不同的表达啊，所以第一个考点需要记住的哲学基本问题是什么？啊，这是第一个考点，那么往下来看，关于哲学的基本问题，我们既然他提了，你是不是就得回答呀？对吧？唉，所以回答有两个方面啊，哪两个方面呢？第一个强调就是思维和存在何者为第一性的问题，而第二个方面强调的就是思维和存在是否具有同一性的问题。讲到这啊，有很多同学会很困惑，是不是什么是第一性，什么是同一性呢？来同学们啊。看我给大家做了一个','{"source": "fengze_politics_course_catalog", "aliases": ["物质和意识"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 25405, "end_char": 25705, "line": 1, "excerpt": "什么都回归到这个问题上，也就是思维与存在的关系问题。啊，所以后面我们才提到了这个问题，也就是哲学的基本问题是思维与存在的关系问题。那或者我们说另外一个点就是它是意识和物质的关系问题，这两个说哪个都可以知道吧？两种不同的表达啊，所以第一个考点需要记住的哲学基本问题是什么？啊，这是第一个考点，那么往下来看，关于哲学的基本问题，我们既然他提了，你是不是就得回答呀？对吧？唉，所以回答有两个方面啊，哪两个方面呢？第一个强调就是思维和存在何者为第一性的问题，而第二个方面强调的就是思维和存在是否具有同一性的问题。讲到这啊，有很多同学会很困惑，是不是什么是第一性，什么是同一性呢？来同学们啊。看我给大家做了一个", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 41558, "end_char": 41858, "line": 1, "excerpt": "点儿，对不对？如果我没啥能力，那指导你，那可能就往一个坏的方向去发展了。啊好了，注意这三个就是比较容易错的说法就可以了好吧唉，好了，这是在这儿啊，第一个关于这个意识和物质的这个辩证关系。然后紧接着往下同学们看第二个就是它的方法论意义，方法论意义这一块儿，那么也很简单了，就是根据我们刚才说的。啊，这两个点第一个他说的是物质决定意识对不对？那既然物质决定意识有什么样的物质在我们的啊？这个精神当中才会有什么样的意识产生？所以你看他说了。我们要一切从实际出发，对吧？那一切从实际出发，他说到我们要按照事物的本来面貌去认识世界，在改造世界当中坚持实事求是。那啥意思啊？一切从实际出发，这还不简单吗？比如说同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 297, "end_char": 597, "line": 1, "excerpt": "这儿大家一定要认真听了啊。好实践与认识的辩证关系呢？其实大家会发现啊，如果你对于之前我们在讲唯物论那一块。嗯，还有印象的话，唯物论的辩证关系，他是不是也在讲关于物质和意识，二者之间的关系问题，对不对？唉，那么无非就是两个方面。哪两个方面，同学们首先第一个方面就是物质决定意识。对吧，这是第一个，然后第二个强调的是意识啊，反作用于物质，那么它有两个方面，一个强调的是哎，正确的去促进另外一个强调的就是。哎，这个错误的起阻碍，那么实际上你会发现实践与认识的辩证关系大体上来说也是这两个方面一个啊，强调的是决定作用，一个强调的是反作用。那么来看一下第一个实践决定认识我们在这里面讲到这个实践决定认识的时候，", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.topic_2','political_theory.marx.materialism','行测','政治理论','尊重客观规律与主观能动性','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.topic_2','课程知识：尊重客观规律与主观能动性。着往下来看，同学们这个比较重要的知识点啊，要记住的这几个点都要记住一二三四意识的能动作用。考的也非常多啊，什么叫意识的能动作用含义了解就行，他说也指的是意识的叫主观能动性啊。指的是意识能动的反映世界和通过实践改造世界的能力和作用啊，那这就是一种意识的能动性。那么，它的浓度性作用主要表现在下面四个点来看吧，哪四个点第一个点意识活动具有目的性和计划性？哎，什么意思啊？什么叫目的性计划性？其实目的和计划这两个大家都能理解，对吧？唉，也就是你带着什么目的？去想这个事情，比如说大家啊，你看你现在为什么在这学习啊？同学们，你是带着什么目的来的？你是带着要考上公务员儿的这个目的来的，对不对？唉，那这就是你看','{"source": "fengze_politics_course_catalog", "aliases": ["主观能动性"], "course_sources": [{"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 33634, "end_char": 33934, "line": 1, "excerpt": "着往下来看，同学们这个比较重要的知识点啊，要记住的这几个点都要记住一二三四意识的能动作用。考的也非常多啊，什么叫意识的能动作用含义了解就行，他说也指的是意识的叫主观能动性啊。指的是意识能动的反映世界和通过实践改造世界的能力和作用啊，那这就是一种意识的能动性。那么，它的浓度性作用主要表现在下面四个点来看吧，哪四个点第一个点意识活动具有目的性和计划性？哎，什么意思啊？什么叫目的性计划性？其实目的和计划这两个大家都能理解，对吧？唉，也就是你带着什么目的？去想这个事情，比如说大家啊，你看你现在为什么在这学习啊？同学们，你是带着什么目的来的？你是带着要考上公务员儿的这个目的来的，对不对？唉，那这就是你看", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 5913, "end_char": 6213, "line": 1, "excerpt": "对？哎，那么在这种情况之下，大家注意人为事物的联系，有同学说都说人为了，那难道不是主观的吗？同学们。不是的啊，人为事物的联系，在你创造它的过程当中，可能确实有你主观能动性的发挥，对不对啊？因为你可以在四海报班儿，你也可以在其他的一些公司报班儿，对不对？这都可以。但是你要注意，一旦当你建立了这种联系之后，那这个联系它就是客观的，它就是不以人的意志为转移的。能理解吗？同学们哎，这种活动啊，这个这种联系是已经建立的啊，你不能说说啊，这个时候说你看说我感觉冯老师这不行了，对吧？我我不想再当你的学生了，那不好意思，也是一样的你你。因为我已经成为你的老师了，对吧？哪怕你后期换了个老师，再听这些课啊，那之前", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 39823, "end_char": 40123, "line": 1, "excerpt": "。所以主体是人，那紧接着往下，他又说了是人类怎么样叫能动的改造世界，什么叫能动的同学们？能动这个词，我们前面讲到意识的能动作用的时候，是不是给大家说了说发挥人的主观能动性，是不是哎？所以这个能动它，体现的就是我们的这种实践活动啊，是人一种有意识。有目的的活动。啊，这个能理解，就是人我们的实践活动是一种有意识，有目的的活动，比如说同学们像刚才给大家说的这个农民种地的活动，对吧？哎，农民种地的实践活动，你想一想。我在这块地上要种什么？农作物对不对？哎，是种玉米，是种水稻，是种小麦，你看首先我是有自己的主观意识的，对不对？以及我在种地的过程当中啊，可能我说了这块儿地啊，哎，我要把它分开种，对吧？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.materialism.topic_3','political_theory.marx.materialism','行测','政治理论','运动与静止','concept',1,1,'gongkao.xingce.political_theory.marx.materialism.topic_3','课程知识：运动与静止。一个缺陷。第二个缺陷就是我们刚才提到的形而上学性了，对吧？形而上学性这个词挺抽象，但是其实只需要你把握后面这三个词就行了。什么叫形而上选项？同学们，其实就是孤立静止和片面这三个观点。只要在某一个观点当中，它体现出这三个观点当中的任意一个，这是我给大家补充的啊。三者只要满足其一，就可以称之为叫形而上学性。啊，那这三个词都很好理解啊，孤立的静止的片面的对不对？好看下面我给大家举的这几个例子啊，首先第一个孤孤立的观点，比如说像我们之前做题的时候经常见到这么一句话叫什么？叫只见树木，不见森林，看到了吗？嗯，当有一整片森林在你眼前的时候，结果你只能看到一棵一棵的树，你并没有办法看到整个森林。那你看同学们','{"source": "fengze_politics_course_catalog", "aliases": ["静止"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 31909, "end_char": 32209, "line": 1, "excerpt": "一个缺陷。第二个缺陷就是我们刚才提到的形而上学性了，对吧？形而上学性这个词挺抽象，但是其实只需要你把握后面这三个词就行了。什么叫形而上选项？同学们，其实就是孤立静止和片面这三个观点。只要在某一个观点当中，它体现出这三个观点当中的任意一个，这是我给大家补充的啊。三者只要满足其一，就可以称之为叫形而上学性。啊，那这三个词都很好理解啊，孤立的静止的片面的对不对？好看下面我给大家举的这几个例子啊，首先第一个孤孤立的观点，比如说像我们之前做题的时候经常见到这么一句话叫什么？叫只见树木，不见森林，看到了吗？嗯，当有一整片森林在你眼前的时候，结果你只能看到一棵一棵的树，你并没有办法看到整个森林。那你看同学们", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 8990, "end_char": 9290, "line": 1, "excerpt": "家思考这句话吧，这句话说的对不对呀？是不是是不是你看考虑所有的物质都是运动的，有同学说说老师，我咋这么不信呢，对吧？说的这么绝对，难道这个世界上就没有一些物质是静止状态的吗？啊，难道就没有一些物质，它是永恒静止状态呢？其实同学们，你要考虑。我就现在你想啊，你现在就想是宇宙当中有没有一种物质，就这种物质对吧？它就是永恒静止的状态，你想你想破脑袋，你都想不出来。同学们在宇宙当中有没有哪种物质？它是永恒静止的状态。是没有的唉，是没有的就哪怕像我们之前说的像你现在坐在这个椅子上，你没有动对吧？或者坐在床上没有动。那这个时候你看，随着地球在不断的进行自转和公转，你是不是一直在动，对吧？唉，所以在这种情况", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 603, "end_char": 903, "line": 1, "excerpt": "节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静止的，那么辩证法它强调的是事物都是永恒发展的。而形而上学，强调片面，那么在这里", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.topic_4','political_theory.marx.dialectics','行测','政治理论','联系的客观性与条件性','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.topic_4','课程知识：联系的客观性与条件性。一领域的，而哲学呢？是对这些的概括和总结，研究的是最普遍最一般的啊，所以在这里面。先搞清楚它啊，先搞清楚它那么来，同学们。看下面这个最为重要的点就是它二者之间的联系联系，说到具体科学是哲学的基础，而哲学给具体科学以世界观和方法论的指导。那么来同学们看啊，怎么去理解这个东西？为什么说具体科学是哲学的基础哲学，又给具体科学以世界观和方法论的指导呢？往下啊，我把这个白板清理一下，我给大家写一个案例啊。来吧，同学们，我们刚才是不是讲了很多的具体科学对吧？唉，你要结合我跟他大大家说的这些案例去理解啊，首先第一个比如说我们说物理学。那大家想一想，物理学之前我们讲物这个科技常识的时候讲过哪些物理知识啊？还记','{"source": "fengze_politics_course_catalog", "aliases": ["联系"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 17011, "end_char": 17311, "line": 1, "excerpt": "一领域的，而哲学呢？是对这些的概括和总结，研究的是最普遍最一般的啊，所以在这里面。先搞清楚它啊，先搞清楚它那么来，同学们。看下面这个最为重要的点就是它二者之间的联系联系，说到具体科学是哲学的基础，而哲学给具体科学以世界观和方法论的指导。那么来同学们看啊，怎么去理解这个东西？为什么说具体科学是哲学的基础哲学，又给具体科学以世界观和方法论的指导呢？往下啊，我把这个白板清理一下，我给大家写一个案例啊。来吧，同学们，我们刚才是不是讲了很多的具体科学对吧？唉，你要结合我跟他大大家说的这些案例去理解啊，首先第一个比如说我们说物理学。那大家想一想，物理学之前我们讲物这个科技常识的时候讲过哪些物理知识啊？还记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250816 政治理论2.doc.txt", "source_sha256": "c319fba0472d54643b2e57a955c00dc1e8854f3f64435b3b0571a3da58a13df7", "start_char": 45862, "end_char": 46162, "line": 1, "excerpt": "不对？唉，那么我们就呃给大家解释一下这个规律，因为这也是我们考建考试的时候常见的一个考点啊。规律的含义了解就行，它说规律是事物本身所固有的本质的，必然的，稳定的联系。啊，那你看像比如说我们刚才提到的万有引力定律，是不是宇宙当中很多的这个事物都它都是遵循的，这个万有引力定律啊，对吧？哎，然后再比如说像我们讲到的牛顿的啊，三大运动定律啊，什么作用力反作用力对吧？惯性啊，惯性定律等等，类似于这个，你看这些它都是在事物。本身所固有的本质的必然的稳定的联系，对吧？唉，那这就是我们所说的这个规律啊，它是一种这个联系。那规律来看。下面是重点啊，规律，它具有客观性，什么是客观性啊，之前讲过了，对吧？客观性其实", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 564, "end_char": 864, "line": 1, "excerpt": "？我们在之前讲到形而上学的时候，其实给大家做了这样的一个呃，过去啊，就是在前两节课的时候做过一个对比，我不知道大家还记不记得。也就是本身唯物辩证法，它所坚持的是联系发展和全面的观点，而在这种情况之下，你看形而上学，它用的是什么？用的是孤立静止和片面的观点看问题。所以之前我们给大家在讲这个马克思主义哲学的时候，给大家强调了一个问题，就是马马克思主义哲学，你看它实现了这个唯物主义和辩证法之间的这样一种统一，对不对？哎，主要的原因在哪？其实就在于他批判了形而上学的孤立静止和片面，那么这几个你看同学们是不是正好都是相互之间对立的这种关系啊？形而上学是孤立的，而辩证法是什么？是联系的观点呃，形而上学是静", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.topic_5','political_theory.marx.dialectics','行测','政治理论','发展的实质','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.topic_5','课程知识：发展的实质。实质是什么？这个一定要记，因为考试的时候他就喜欢把这个实质和我们后面。学到的一个知识点的实质混淆一起啊，所以大家先把这个先记住啊，一会儿咱们再对比说发展的实质是新事物的产生和旧事物的灭亡。那问题来了，同学们。新事物的产生，旧事物的灭亡，什么叫新事物，什么叫旧事物呢？是不是按照我们平时的思维习惯去理解，说这个东西啊，你看比如说这个手机是我刚买的对吧？哎，今天下班儿没啥事儿，路过手机店发现哎，突然之间这个手机挺好看，我就新买了一个手机。啊，那这个就是新手机，那我之前的那个手机就是旧手机了，对吧？这是我们平时的理解，对不对？同学们，但是你要注意。在哲学上，我们不能用时间的先后去区分，而需要用什么去区','{"source": "fengze_politics_course_catalog", "aliases": ["新事物"], "course_sources": [{"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 15175, "end_char": 15475, "line": 1, "excerpt": "实质是什么？这个一定要记，因为考试的时候他就喜欢把这个实质和我们后面。学到的一个知识点的实质混淆一起啊，所以大家先把这个先记住啊，一会儿咱们再对比说发展的实质是新事物的产生和旧事物的灭亡。那问题来了，同学们。新事物的产生，旧事物的灭亡，什么叫新事物，什么叫旧事物呢？是不是按照我们平时的思维习惯去理解，说这个东西啊，你看比如说这个手机是我刚买的对吧？哎，今天下班儿没啥事儿，路过手机店发现哎，突然之间这个手机挺好看，我就新买了一个手机。啊，那这个就是新手机，那我之前的那个手机就是旧手机了，对吧？这是我们平时的理解，对不对？同学们，但是你要注意。在哲学上，我们不能用时间的先后去区分，而需要用什么去区", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12927, "end_char": 13227, "line": 1, "excerpt": "那这个点同学们，他容易怎么考？他很少直接去考，他会结合着我们前面讲到的一个知识点。看到了吗？也就是他会这样去说啊，在选项当中，他说a选项就这样的辩证否定的实质是新事物的产生和旧事物的灭亡，对吗？同学们。不对吧，哎，非常好，同学们有很多同学都知道这个是谁的实质，它是发展的实质呀，对不对？哎，发展的实质，所以我之前就讲到发展那个时候我就说了，我们很容易啊，他很喜欢在出题的时候把后面辩证否定的实质和它混合在一起。啊，要不然你看我为什么一直在说说哲学这个东西，其实你后期把它梳理完之后啊，你把它记住，有一些关键的知识点，你把它记住。记住之后你做题的时候非常好做，因为有些选项你打一眼儿一看对吧？哎，打眼儿", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.topic_6','political_theory.marx.dialectics','行测','政治理论','矛盾的普遍性与特殊性','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.topic_6','课程知识：矛盾的普遍性与特殊性。说法，从哲学上那就是错的，唉，这不就是唯心的观点吗？对不对？唉。然后啊c选项说说矛盾的普遍性是矛盾的共性没问题啊，普遍的东西不就是共性的吗？对不对哎？那么矛盾的特殊性，它就是矛盾的个性，这没问题啊。所以这道题选的就是c啊，而4d选项当中说矛盾的普遍性和客观性决定了事物的不同性质，注意同学们。谁决定了事物的不同性质呢？其实是。这个点他说错了，同学们啊，我们在讲到呃这个事物性质的时候，哲学上强调主要矛盾的主要方面决定了。事物的不同性质，唉，主要矛盾的主要方面决定了事物的性质，但是如果你是从这个就是普遍性和特殊性的角度去考虑的话，那一定是特殊性，注意啊。特殊性，它决定了事物的不同性质，能理解吗？唉，','{"source": "fengze_politics_course_catalog", "aliases": ["特殊性"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 1816, "end_char": 2116, "line": 1, "excerpt": "说法，从哲学上那就是错的，唉，这不就是唯心的观点吗？对不对？唉。然后啊c选项说说矛盾的普遍性是矛盾的共性没问题啊，普遍的东西不就是共性的吗？对不对哎？那么矛盾的特殊性，它就是矛盾的个性，这没问题啊。所以这道题选的就是c啊，而4d选项当中说矛盾的普遍性和客观性决定了事物的不同性质，注意同学们。谁决定了事物的不同性质呢？其实是。这个点他说错了，同学们啊，我们在讲到呃这个事物性质的时候，哲学上强调主要矛盾的主要方面决定了。事物的不同性质，唉，主要矛盾的主要方面决定了事物的性质，但是如果你是从这个就是普遍性和特殊性的角度去考虑的话，那一定是特殊性，注意啊。特殊性，它决定了事物的不同性质，能理解吗？唉，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 31927, "end_char": 32227, "line": 1, "excerpt": "，其他的后面这个就不给大家讲了啊，因为后面这个呢，本身我们考试的时候它很少涉及啊，很少涉及。嗯，那么来往下同学们看第二个点啊，第二个点呢，我们在讲矛盾的普遍性和特殊性。看同学们，这就是我刚才为什么给大家讲说矛盾的基本属性，对吧？我们刚才讲的整个那个知识点是不是都在讲这个基本属性？矛盾的基本属性指的是矛盾的同一性和矛盾的斗争性。我解释了为什么这两个是它的基本属性啊？因为只要是矛盾，它就有同一就有斗争，所以它是基本的对不对哎？这是基本的属性。但你会发现，矛盾的普遍性和特殊性，这两个就不一样了，为什么？因为普遍性和特殊性看啊，它是矛盾问题的精髓，这是毛主席给的定义啊。它是矛盾问题的精髓。那么怎么理解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 37004, "end_char": 37304, "line": 1, "excerpt": "我为什么这么咬牙切齿，因为我们讲了对吧，就是原话呀，原话你还错，你想想同学们啊，这万一考试咋整啊？好，这是第二题啊，其他的都不用看了啊，都不用看了，就说什么矛盾特殊性，对吧？全面发展，按客规客观规律办事，你看这句话对吧？明者因时而变。智者随事而智，啥意思啊？就有智慧的人会根据实际情况的变化，然后去调整。能理解吧哎，去调整啊，然后做到什么做到哎，就像我们说的什么一切从实际出发呀，具体问题具体分析啊，这都行，所以a选项是不是把握了矛盾的特殊性？没问题吧，对不对哎？然后同样的，他在这里面强调提高创新思维活力，建立全面的发展观，同学们。后面人说了，根本途径在于创新，对吧？哎，所以你看在这里提高创新，其", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.dialectics.topic_7','political_theory.marx.dialectics','行测','政治理论','内因与外因','concept',1,1,'gongkao.xingce.political_theory.marx.dialectics.topic_7','课程知识：内因与外因。分的你看学到最后，其实实际上。你区分非常简单，对吧？唉，区分非常简单啊。然后来往下把这个讲完，对吧？把矛盾这块儿讲完，然后咱们简单做个总结，咱们就下课啊呃，这个内因和外因这块儿就相当简单了啊，大家听一下就行了啊。你看，首先第一个他说了事物发展的动力和源泉就是事物的内部矛盾，哎，因为正是事物内部有矛盾嘛，所以我们的整个事物才会向前发展，我们在最初。讲到矛盾，也就是讲到对立统一的时候，你看他说了，他揭示了事物发展的什么源泉和动力，对吧？哎，因为事物内部它总有这种矛盾，矛盾的两个方面相互斗争啊，然后才促进了它的发展好，那么紧接着往下同学们。看所谓内因，指的就是事物的内部矛盾，而外因呢，同学们那就是事','{"source": "fengze_politics_course_catalog", "aliases": ["内因"], "course_sources": [{"source_file": "20250821 政治理论3.doc.txt", "source_sha256": "9faafec2ce2752bc83101b66ab40bb094fe5f918d09d5cec0f666652cc442530", "start_char": 49276, "end_char": 49576, "line": 1, "excerpt": "分的你看学到最后，其实实际上。你区分非常简单，对吧？唉，区分非常简单啊。然后来往下把这个讲完，对吧？把矛盾这块儿讲完，然后咱们简单做个总结，咱们就下课啊呃，这个内因和外因这块儿就相当简单了啊，大家听一下就行了啊。你看，首先第一个他说了事物发展的动力和源泉就是事物的内部矛盾，哎，因为正是事物内部有矛盾嘛，所以我们的整个事物才会向前发展，我们在最初。讲到矛盾，也就是讲到对立统一的时候，你看他说了，他揭示了事物发展的什么源泉和动力，对吧？哎，因为事物内部它总有这种矛盾，矛盾的两个方面相互斗争啊，然后才促进了它的发展好，那么紧接着往下同学们。看所谓内因，指的就是事物的内部矛盾，而外因呢，同学们那就是事", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250822 政治理论4.doc.txt", "source_sha256": "a1ecb30dd2fded17a53e2477a51980a047e2309cd710d43e53fa17de7d864e51", "start_char": 12382, "end_char": 12682, "line": 1, "excerpt": "人的出现去推翻当时的封建社会。你看他这句话说的是什么意思？就是封建社会到那个时期已经自我否定，对吧？他已经不行了。对，非常好，我看到有同学打了一个弹幕，就是因为内因他在事物的发展过程当中起决定作用，同学们，你看我们讲到这儿，前面的一些矛盾的观点是不是？已经深入到这里面了，对吧？已经串联起来了啊，内因是起决定作用的，整个封建社会已经腐朽，没落到一定的地步了。哎，所以我们不可否认啊，孙中山先生确实是非常伟大的，对不对？哎，但是换成比如说那个时候冯老师就在那个地方，对吧？我可能变换成孙中山。变成了冯中山，我就成为了大家历史课本上要学习的这个人物，是不是啊？那所以一定要注意啊他。它所谓的辩证的否定，就", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.epistemology.topic_8','political_theory.marx.epistemology','行测','政治理论','感性认识与理性认识','concept',1,1,'gongkao.xingce.political_theory.marx.epistemology.topic_8','课程知识：感性认识与理性认识。规律有哪些？首先，第一个强调认识的辩论过程啊，这个点上有首先第一个啊，虽然我没标红，但是你要知道这有个考点。认识的辩证过程是什么？就是第一句话，在实践基础上，由感性认识到理性认识，再由理性认识到实践的能动飞跃，这是一个。啊，也是容易出错的考点，同学们。怎么容易出出错呢？出错的点就在下面这块儿看到了吗？易错区分当中，我们在考试当中，他很喜欢在选项里面说认识的辩证过程是从实践到认识，再从认识到实践的过程。有很多同学这个知识点把握不准确，一看到这个说法，我的妈呀，这个说法可太正确了，对吧？没有比这个说法更正确的了。同学们，这个说法对吗？不对，因为你看我们书上已经强调了认识的辩证过程，强调的它是两次飞','{"source": "fengze_politics_course_catalog", "aliases": ["感性认识"], "course_sources": [{"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 9063, "end_char": 9363, "line": 1, "excerpt": "规律有哪些？首先，第一个强调认识的辩论过程啊，这个点上有首先第一个啊，虽然我没标红，但是你要知道这有个考点。认识的辩证过程是什么？就是第一句话，在实践基础上，由感性认识到理性认识，再由理性认识到实践的能动飞跃，这是一个。啊，也是容易出错的考点，同学们。怎么容易出出错呢？出错的点就在下面这块儿看到了吗？易错区分当中，我们在考试当中，他很喜欢在选项里面说认识的辩证过程是从实践到认识，再从认识到实践的过程。有很多同学这个知识点把握不准确，一看到这个说法，我的妈呀，这个说法可太正确了，对吧？没有比这个说法更正确的了。同学们，这个说法对吗？不对，因为你看我们书上已经强调了认识的辩证过程，强调的它是两次飞", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.epistemology.topic_9','political_theory.marx.epistemology','行测','政治理论','认识的反复性与无限性','concept',1,1,'gongkao.xingce.political_theory.marx.epistemology.topic_9','课程知识：认识的反复性与无限性。，对不对？而第二次飞跃注意了，那就是从理性认识到实践的飞跃了，好吧嗯。这个也不多讲啊，大家知道这两次飞跃就可以了，那么紧接着往下来看，同学们啊，第二个认识过程的反复性和无限性。什么叫反复性？什么叫无限性呢？先来看第一个啊，反复性所谓反复性指的是认识过程啊，你看它指的是对一个复杂事物的认识。往往要经过由实践到认识，由认识到实践的多次反复才能完成。啥意思？同学们，你看比如说啊。大家通过这个课堂上接触了我，对不对？唉，接触了冯泽老师啊，那你是不是会对我形成一种感性认识啊？对不对，同学们？你会对我形成一种感性认识，对吧？唉，形成感性认识，但是你不要忘了同学们，人是最为复杂的生物，你知道我背地里啥样吗？','{"source": "fengze_politics_course_catalog", "aliases": ["反复性"], "course_sources": [{"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 17648, "end_char": 17948, "line": 1, "excerpt": "，对不对？而第二次飞跃注意了，那就是从理性认识到实践的飞跃了，好吧嗯。这个也不多讲啊，大家知道这两次飞跃就可以了，那么紧接着往下来看，同学们啊，第二个认识过程的反复性和无限性。什么叫反复性？什么叫无限性呢？先来看第一个啊，反复性所谓反复性指的是认识过程啊，你看它指的是对一个复杂事物的认识。往往要经过由实践到认识，由认识到实践的多次反复才能完成。啥意思？同学们，你看比如说啊。大家通过这个课堂上接触了我，对不对？唉，接触了冯泽老师啊，那你是不是会对我形成一种感性认识啊？对不对，同学们？你会对我形成一种感性认识，对吧？唉，形成感性认识，但是你不要忘了同学们，人是最为复杂的生物，你知道我背地里啥样吗？", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.history.topic_10','political_theory.marx.history','行测','政治理论','人民群众与历史创造','concept',1,1,'gongkao.xingce.political_theory.marx.history.topic_10','课程知识：人民群众与历史创造。中啊，国外留学的过程当中，那个时候你看他接受到了我们所说到的就是这个共产党宣言的一些思想，对吧？也就是共产主义的一些思想。那这个过程当中好，为了能够让我们广大的人民群众都学习这种共产主义思想。所以啊，你看这就有一个翻译的人物，也就是陈望道就可以了啊，陈望道就可以了，好那么在这里面。记住它的翻译者是谁就可以了好吧，同学们唉，记住它就可以了啊。这个陈望道好。陈望道。作为翻译者，把它翻译成中文之后，那么它开始广泛的在我们中国去进行传播了啊，这个大家有个印象就可以了。我们之前的时候，习近平主席曾经说过一句话，说真理的味道是香甜的，对不对？唉，其实就是在说。陈王道，在翻译的过程当中啊，拿那个什么吃墨水儿','{"source": "fengze_politics_course_catalog", "aliases": ["人民群众"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 4980, "end_char": 5280, "line": 1, "excerpt": "中啊，国外留学的过程当中，那个时候你看他接受到了我们所说到的就是这个共产党宣言的一些思想，对吧？也就是共产主义的一些思想。那这个过程当中好，为了能够让我们广大的人民群众都学习这种共产主义思想。所以啊，你看这就有一个翻译的人物，也就是陈望道就可以了啊，陈望道就可以了，好那么在这里面。记住它的翻译者是谁就可以了好吧，同学们唉，记住它就可以了啊。这个陈望道好。陈望道。作为翻译者，把它翻译成中文之后，那么它开始广泛的在我们中国去进行传播了啊，这个大家有个印象就可以了。我们之前的时候，习近平主席曾经说过一句话，说真理的味道是香甜的，对不对？唉，其实就是在说。陈王道，在翻译的过程当中啊，拿那个什么吃墨水儿", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 15689, "end_char": 15989, "line": 1, "excerpt": "哲学最为典型的马克思主义哲学，对吧？哎，我们国家的艺术当中一直强调哎要。深刻的啊，后面其实讲新思想，大家就知道了，要创作以人民为中心的这样的一种艺术形式，要创造人民群众喜闻乐见的这种啊，哎，这个形式对不对？哎，这就是你看从。从这儿，它所体现出来的，而宗教这个这咱就不说了，因为在中国，你会发现我们国家的这种宗教思想还是比较特殊的，对吧？哎，我们后面讲法律也会说我们国家信仰的是宗教自由。哎，宗教信仰自由，就是你可以信教，也可以不信，对不对？你可以信这个，也可以信那个，这都行啊，但是实际上呢，我们国家对于宗教其实保持着是一个相对来说啊，比较谨慎的态度，是不是？所以这个咱就不提不提了啊。那么，后面同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 42951, "end_char": 43251, "line": 3, "excerpt": "解决这个东西，对不对？哎，你不能说在实践过程当中啊，你说好这里面什么问题都没有，皆大欢喜对不对？这也不是啊，这也不应该这样，所以我们强调在实践过程当中一定要抓住人民群众有哪些问题，你要针对性的。去解决问题，对不对？所以呢，你看这个问题体现什么？是不是就体现我们之前讲的矛盾？它是普遍的，它是客观的呀。哎，你在这里，你就不能否认矛盾，它是普遍的，你一旦否认矛盾，矛盾的普遍性，想一想同学们是不是就认为什么？哎，之前还真有这样的一些案例啊，同学们。有的一些地方官员就认为，这个地方它就没有，就是我们这个地方它没有矛盾的存在啊，就认为啥万世太平对吧？唉，万世太平，那你想想同学们这个观点对吗？肯定是错的呀，", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.history.topic_11','political_theory.marx.history','行测','政治理论','社会基本矛盾与社会发展','concept',1,1,'gongkao.xingce.political_theory.marx.history.topic_11','课程知识：社会基本矛盾与社会发展。么往下最后一个，这个是稍微啊，需要大家还是费点儿脑子，要需要去理解一下的。你看他说的社会历史条件。啊，社会历史条件呢？强调的就是资本主义经济的高度发展和资本主义社会基本矛盾的充分暴露。啊，什么叫基本矛盾的充分暴露，对吧？是为什么资本主义经济又高度发展了？你考虑这个时期同学们。我们之前讲科技常识的时候，是不是给给大家讲过那个工业革命？还记得吗？同学们最早讲的在19世纪那个时候。工业革命，你想一想，那个就是我们之前说的那个第一次工业革命，对吧？哎，第一次工业革命，从呃18世纪，然后。就是末期的时候一直到19世纪，这个过程从一次工业革命，二次工业革命，对吧？唉，这个时间你看。借着这两次工业革命的东风','{"source": "fengze_politics_course_catalog", "aliases": ["社会基本矛盾"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 46909, "end_char": 47209, "line": 1, "excerpt": "么往下最后一个，这个是稍微啊，需要大家还是费点儿脑子，要需要去理解一下的。你看他说的社会历史条件。啊，社会历史条件呢？强调的就是资本主义经济的高度发展和资本主义社会基本矛盾的充分暴露。啊，什么叫基本矛盾的充分暴露，对吧？是为什么资本主义经济又高度发展了？你考虑这个时期同学们。我们之前讲科技常识的时候，是不是给给大家讲过那个工业革命？还记得吗？同学们最早讲的在19世纪那个时候。工业革命，你想一想，那个就是我们之前说的那个第一次工业革命，对吧？哎，第一次工业革命，从呃18世纪，然后。就是末期的时候一直到19世纪，这个过程从一次工业革命，二次工业革命，对吧？唉，这个时间你看。借着这两次工业革命的东风", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 380, "end_char": 680, "line": 1, "excerpt": "就是。社会发展的基本规律看到了吗？啊，那么社会发展的基本规律是什么呢？大家要先明确这样一个问题，也就是我们书上第一段强调的啊，指的就是社会的基本矛盾运动。那么，社会基本矛盾运动包括了生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，这两个点要注意，首先同学们要先掌握社会的基本矛盾，运动有哪两个唉，这是第一个考点啊，同学们。那么，大家先来看这个词，为什么我们强调说这两个生产力，生产关系，经济基础和上层建筑的矛盾？它是属于叫社会的基本矛盾呢？大家要搞清楚啊，因为这种矛盾，它在任何的社会形态当中都是存在的。注意啊，在热任何的社会形态中都存在生产力和生产关系的矛盾，经济基础和上层建筑的矛盾。好，那", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.economics.topic_12','political_theory.marx.economics','行测','政治理论','价值规律与社会必要劳动时间','concept',1,1,'gongkao.xingce.political_theory.marx.economics.topic_12','课程知识：价值规律与社会必要劳动时间。时候会犯难啊，会犯难的，确实这个东西确实是很难的啊。你看，比如说像a选项，它不是问正确的吗？a说商品的价值量是由什么决定的？那肯定不是个别劳动时间决定的呀，它是社会必要劳动时间决定的啊，这个咱后面会讲。好吗？同学们哎，咱们这个具体知识点咱就不给大家解释了啊，然后往下b选项又说说货币的价值尺度，职能是通过实际的物质交换来实现的。同学们，首先你要知道什么叫价值尺度，是不是我用货币去衡量这个东西价值的多少啊？对吧？就这东西值多少钱？那你想想，我是通过实际的物质交换去实现的吗？同学们，我说这个商品值100块钱，我是通过实际的物质交换去那个实现的吗？不是，我就是跟他观念上我说了一下这个东西值100块钱。','{"source": "fengze_politics_course_catalog", "aliases": ["社会必要劳动时间"], "course_sources": [{"source_file": "20250815 政治理论1.doc.txt", "source_sha256": "57723c3bd4fcbeb848fd101a207042f4d25f0d099837cf6e49556a5ab962707d", "start_char": 2721, "end_char": 3021, "line": 1, "excerpt": "时候会犯难啊，会犯难的，确实这个东西确实是很难的啊。你看，比如说像a选项，它不是问正确的吗？a说商品的价值量是由什么决定的？那肯定不是个别劳动时间决定的呀，它是社会必要劳动时间决定的啊，这个咱后面会讲。好吗？同学们哎，咱们这个具体知识点咱就不给大家解释了啊，然后往下b选项又说说货币的价值尺度，职能是通过实际的物质交换来实现的。同学们，首先你要知道什么叫价值尺度，是不是我用货币去衡量这个东西价值的多少啊？对吧？就这东西值多少钱？那你想想，我是通过实际的物质交换去实现的吗？同学们，我说这个商品值100块钱，我是通过实际的物质交换去那个实现的吗？不是，我就是跟他观念上我说了一下这个东西值100块钱。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 48219, "end_char": 48519, "line": 1, "excerpt": "的时间越多，那么我耗费的脑力和体力的量是不是就越多？能理解吗？同学们哎，所以啊，你看我们这个时候下面说了一个非常重要的知识点，就是商品的价值量是由生产商品的，叫社会必要劳动时间决定的。那注意了，这个社会必要劳动时间指的是啥呢？同学们，你看下面他说的这个概念，理解就可以了啊，指的是在社会现有的正常的生产条件下。在社会平均的劳动熟练程度和劳动强度下，制造某种使用价值所需要的劳动时间。那比如说看下面啊，同学们给大家拿了这么一个表格的案例，大家可以理解，这个你也不用记。在这个行业当中，假设有abcde五个厂商，他们是同时生产同一个商品的啊，那他们生产这个商品的时间包括方式方法都不一样a。生产一件商品用", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 1144, "end_char": 1444, "line": 3, "excerpt": "同学们也不需要你去掌握，你只需要理解就行了啊，知道劳动力的价值是用什么衡量出来的就可以了。那么，按照我们之前上一节课的思路说到，其实一个商品的价值是由这个商品的社会必要劳动时间所决定的，对不对？哎，那大家想一个问题。劳动力其实它指的是劳动者的一种工作能力，对不对？那这种工作能力你用这种社会必要劳动时间去决定，你怎么去衡量它呢？对吧，可能你会发现这个东西很难直接去衡量它，很抽象啊，那么在这里你看我们书上就给大家说了这样一个点。我们可以把这种社会必要劳动时间还原为生产出劳动者所消费的生活资料，所必须的社会必要劳动时间。啥意思啊？你这个劳动者对不对哎？你每天都要生活啊，你要生存下去，那我可以把生产和", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.economics.topic_13','political_theory.marx.economics','行测','政治理论','劳动力商品与剩余价值','concept',1,1,'gongkao.xingce.political_theory.marx.economics.topic_13','课程知识：劳动力商品与剩余价值。，那这种情况之下，它对于整个社会发展会起到一些延缓作用啊，那么同样的，当人口数量过少，同学们。其实他也不行哎，他也不行，因为那个时候对刚才有同学说了，那你就没有劳动力了，没劳动力你整个社会你怎么发展啊，对吧？哎，所以在这种情况之下啊，人口数量过多过少，其实都不行，要保持一个比较。适中的状态，那么再往下就是这个质量的问题了，同学们啊，人口质量这个最显然了，就是我们当然希望人口质量是越高越好了，对不对？唉，人口质量越高，它越能够促进社会的进步与发展。但是同样，如果人口质量哎，这个比较低的话，那它就会阻碍社会的发展啊，所以这个大家能理解就行，这就是第二个人口因素。第三个叫物质生产方式。注意同学们，这','{"source": "fengze_politics_course_catalog", "aliases": ["劳动力"], "course_sources": [{"source_file": "20250823 政治理论5.doc.txt", "source_sha256": "c1bd7da83266d38556cf79fdda140811be125646774b36a9fa477fb8d92fe2f4", "start_char": 41261, "end_char": 41561, "line": 1, "excerpt": "，那这种情况之下，它对于整个社会发展会起到一些延缓作用啊，那么同样的，当人口数量过少，同学们。其实他也不行哎，他也不行，因为那个时候对刚才有同学说了，那你就没有劳动力了，没劳动力你整个社会你怎么发展啊，对吧？哎，所以在这种情况之下啊，人口数量过多过少，其实都不行，要保持一个比较。适中的状态，那么再往下就是这个质量的问题了，同学们啊，人口质量这个最显然了，就是我们当然希望人口质量是越高越好了，对不对？唉，人口质量越高，它越能够促进社会的进步与发展。但是同样，如果人口质量哎，这个比较低的话，那它就会阻碍社会的发展啊，所以这个大家能理解就行，这就是第二个人口因素。第三个叫物质生产方式。注意同学们，这", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 4208, "end_char": 4508, "line": 1, "excerpt": "句话，我们把劳动资料和劳动对象二者合称为叫什么？合称为叫生产资料。所以你看同学们啊，我们现在是不是一直啊？我刚才也给大家说，就是我们在生产的过程当中，除了要投入劳动力之外，还要投入什么笼统的说，就是投入生产资料。啊，那两部分对不对？哎，一部分就是这个劳动资料，一部分就是劳动对象啊，好了，这是在这儿啊，我们给大家去。强调的这个问题啊，强调这个问题，那么来往下同学们看了解完了实体要素之后，紧接着再了解什么叫非实体？非实体要素呢，它主要包括的就是科学技术和经济管理等等，那尤其是科学技术，它的地位非常的重要，你看它说到了把这句话记住啊。科学技术，它是先进生产力的集中体现和主要标志。就记到这儿就行，同学", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 508, "end_char": 808, "line": 3, "excerpt": "所以来吧，同学们。这一节课啊，前半呃前半段的课程就带着大家去了解一下啊，大家之前所说的这种所谓的资本家到底是个什么东西？是不是哎？来看一下啊。首先，第一个先来看劳动力成为商品与货币转化为资本啊，那么劳动力成为商品，看它先说到了。资本主义经济制度是以资本家占有生产资料和以雇佣劳动为基础的经济制度。那么，资本主义雇佣劳动制度的形成，是以劳动力成为商品为前提的啥意思？同学们对吧？哎，掌握这个知识点啊，其实很好理解你，想一想，你既然要雇佣劳动。你是不是首先得有一个前提，就是这个劳动力，它必须是商品，对吧？如果它不是商品，你想想你怎么去雇佣劳动啊？你怎么花钱去雇佣他呀？对不对？唉，这就是一个字面意思上的", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.marx.economics.topic_14','political_theory.marx.economics','行测','政治理论','资本与资本积累','concept',1,1,'gongkao.xingce.political_theory.marx.economics.topic_14','课程知识：资本与资本积累。资本家通过个别劳动生产率来提高，然后实现的，所以它是个别上面那个是整个行业的社会劳动生产率。啊，好了，这是在这儿啊，就给大家讲这么些，那么往下同学们看第三个就是资本积累和资本的有机构成啊。资本积累这一块呢？先看第一个问题，也就是资本主义的再生产啊，资本主义再生产，说到资本家啊瓜分到剩余价值后，如果将其完全用于个人消费，则生产就在原有规模的基础上。重复进行，这叫资本主义的简单再生产。啥意思？同学们来给大家说个案例，大家就明确了啊，我刚才不是说了吗？我是100万投入，对不对？唉，然后我生产出来了150万的豆腐，我把它卖出去了啊，卖出去之后同学们这一段时间我生产出来的剩余价值有多少？是不是就花是就是','{"source": "fengze_politics_course_catalog", "aliases": ["资本积累"], "course_sources": [{"source_file": "20250830 政治理论7.doc.txt", "source_sha256": "1867b57dd46f1cfc73fb712b21018c75be4d802c062389f878361cbadc8741ad", "start_char": 13702, "end_char": 14002, "line": 3, "excerpt": "资本家通过个别劳动生产率来提高，然后实现的，所以它是个别上面那个是整个行业的社会劳动生产率。啊，好了，这是在这儿啊，就给大家讲这么些，那么往下同学们看第三个就是资本积累和资本的有机构成啊。资本积累这一块呢？先看第一个问题，也就是资本主义的再生产啊，资本主义再生产，说到资本家啊瓜分到剩余价值后，如果将其完全用于个人消费，则生产就在原有规模的基础上。重复进行，这叫资本主义的简单再生产。啥意思？同学们来给大家说个案例，大家就明确了啊，我刚才不是说了吗？我是100万投入，对不对？唉，然后我生产出来了150万的豆腐，我把它卖出去了啊，卖出去之后同学们这一段时间我生产出来的剩余价值有多少？是不是就花是就是", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.system.topic_15','political_theory.thought.system','行测','政治理论','十个明确与十四个坚持','concept',1,1,'gongkao.xingce.political_theory.thought.system.topic_15','课程知识：十个明确与十四个坚持。看我们书上具体是怎么表述的啊？好啊，稍微慢点儿是吧？好，稍微慢点儿啊，稍微慢点儿，首先第一个啊，我们在之前讲到关于党的领导的问题，给大家最讲呃，最刚开始的时候讲十个明确，不知道大家还记不记得啊？在讲十个明确的时候，那个时候我们强调第一个明确是不是明确中国特色社会主义最本质的特征是什么？是不是就是党的领导对吧？这也就是这个标题啊，其次它跟着是第二句话，也就是中国特色社会主义制度的最大优势是什么？同学们是不是也是党的领导啊？对吧？唉，那么。当时让大家记得叫本党是大党嘛，哎，本党是大党啊，那么除了这个之外，我们书上还说了两个比较特殊的，第一个强调党呢，是中国特色社会主义事业的坚强领导核心。啊，中国最','{"source": "fengze_politics_course_catalog", "aliases": ["十个明确"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 19046, "end_char": 19346, "line": 1, "excerpt": "看我们书上具体是怎么表述的啊？好啊，稍微慢点儿是吧？好，稍微慢点儿啊，稍微慢点儿，首先第一个啊，我们在之前讲到关于党的领导的问题，给大家最讲呃，最刚开始的时候讲十个明确，不知道大家还记不记得啊？在讲十个明确的时候，那个时候我们强调第一个明确是不是明确中国特色社会主义最本质的特征是什么？是不是就是党的领导对吧？这也就是这个标题啊，其次它跟着是第二句话，也就是中国特色社会主义制度的最大优势是什么？同学们是不是也是党的领导啊？对吧？唉，那么。当时让大家记得叫本党是大党嘛，哎，本党是大党啊，那么除了这个之外，我们书上还说了两个比较特殊的，第一个强调党呢，是中国特色社会主义事业的坚强领导核心。啊，中国最", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.system.topic_16','political_theory.thought.system','行测','政治理论','六个必须坚持','concept',1,1,'gongkao.xingce.political_theory.thought.system.topic_16','课程知识：六个必须坚持。正和创新这个词说了很多遍了，是不是哎，守正有的一些东西是不能变的，像我们上上面提到的党的领导对吧，以人民为中心等等这些东西。都是不能变的，但是在发展的过程当中，必须坚持创新去带动发展好后面啊什么，还有就是效率和公平，因为你想。实现这种共同富裕，对吧？你要激发人民的这种效率啊啊，要让我们提升生产力，对不对？唉，但是同时还要强调什么？要注重公平，因为我们最后要实现共同富裕啊。那么，还有就是活力和秩序哎，你想想同学们这两个关系也很重要，对吧？唉，你想如果我们想要激发大家的活力，那你秩序上是不是可能稍微的就得放松一点儿？对吧哎，但是如果你秩序放的太松了，就你不管，那这个时候他可能太有活力了，同学们那就','{"source": "fengze_politics_course_catalog", "aliases": ["必须坚持"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 17062, "end_char": 17362, "line": 1, "excerpt": "正和创新这个词说了很多遍了，是不是哎，守正有的一些东西是不能变的，像我们上上面提到的党的领导对吧，以人民为中心等等这些东西。都是不能变的，但是在发展的过程当中，必须坚持创新去带动发展好后面啊什么，还有就是效率和公平，因为你想。实现这种共同富裕，对吧？你要激发人民的这种效率啊啊，要让我们提升生产力，对不对？唉，但是同时还要强调什么？要注重公平，因为我们最后要实现共同富裕啊。那么，还有就是活力和秩序哎，你想想同学们这两个关系也很重要，对吧？唉，你想如果我们想要激发大家的活力，那你秩序上是不是可能稍微的就得放松一点儿？对吧哎，但是如果你秩序放的太松了，就你不管，那这个时候他可能太有活力了，同学们那就", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 20661, "end_char": 20961, "line": 1, "excerpt": "理解也行好吗？同学们哎，直接去理解也行啊。那么，往下看，括号一教育是民族振兴，社会进步的基石，那怎么去发展教育？同学们，你看他说到啊，办好中国特色社会主义教育，必须坚持党对教育工作的全面领导。毋庸置疑，对不对？昨天刚讲到党是领导一切的啊，那必须坚持党的教育方针，我们党的教育方针是什么呢？大家可以看一下下面蓝色字体部分给大家拿出来的啊，这个了解就行，不用记同学们啊呃，我把这个划掉好吧，要不然有很多同学。容易引起误会啊，了解就行，你看他说教育必须以社会主义现代化建设服务，对吧？为人民服务必须以生产劳动和社会实践相结合，培养德智体美劳全面发展的社会主义阶。呃，社会主义建设者和接班人。唉，所以这个大家", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy.topic_17','political_theory.thought.economy','行测','政治理论','新发展理念与新发展格局','concept',1,1,'gongkao.xingce.political_theory.thought.economy.topic_17','课程知识：新发展理念与新发展格局。啊。截个图来a啊。好截个图啊，课下其实都会给大家发PPT的啊，大家可以直接看PPT，也更直观好不好嗯？来同学们那么往下来看啊，往下来看第一个完整准确全面的去贯彻新发展理念，新发展理念这一块呢，前面他先讲到了这个地位问题啊。地位问题这一块儿，他说到新发展理念是实现高质量发展的一个指导原则。一会儿，我们会重点去讲它啊，也就是到底什么是新发展理念。来看同学们第一个先理解我国进入新发展阶段啊，这块同学们所谓的新发展阶段不需要你背，你只需要理解就行了，我们过去考试的时候经常有这么一种说法，什么说法呢？他说了。我们的新发展阶段啊，是我们国家走出了社会主义初级阶段之后的一个阶段，同学们这个说法对不对？啊，同','{"source": "fengze_politics_course_catalog", "aliases": ["新发展理念"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 46830, "end_char": 47130, "line": 1, "excerpt": "啊。截个图来a啊。好截个图啊，课下其实都会给大家发PPT的啊，大家可以直接看PPT，也更直观好不好嗯？来同学们那么往下来看啊，往下来看第一个完整准确全面的去贯彻新发展理念，新发展理念这一块呢，前面他先讲到了这个地位问题啊。地位问题这一块儿，他说到新发展理念是实现高质量发展的一个指导原则。一会儿，我们会重点去讲它啊，也就是到底什么是新发展理念。来看同学们第一个先理解我国进入新发展阶段啊，这块同学们所谓的新发展阶段不需要你背，你只需要理解就行了，我们过去考试的时候经常有这么一种说法，什么说法呢？他说了。我们的新发展阶段啊，是我们国家走出了社会主义初级阶段之后的一个阶段，同学们这个说法对不对？啊，同", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11198, "end_char": 11498, "line": 1, "excerpt": "的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样要安全？因为你不能一味的开放，对不对？唉，我们国家在一些领域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 48951, "end_char": 49251, "line": 1, "excerpt": "决的是啥？解决的是保障问题啊。它是确保国家和民族行稳致远的一个坚强助石啊重点。其实记前面这个就行了，发展是动力，对不对？哎，安全是保障。啊，很简单呀，我们之前讲新发展理念，大家还记得吗？新发展理念当中，你看既然强调各个方面创新，协调，绿色，开放，共享，都是在强调如何发展的问题啊。包括习近平总书记之前也说过，这个点发展是解决一切问题的基础和关键，对不对？哎，那发展就是我们的动力啊，发展就是我们的动力。而安全呢？同学们，安全就是保障，对吧？唉，你看我们国家在当前最近这几十年，为什么能够发展的如此迅速？同学们不就是因为我们国家？这个环境是不是维持的非常安全，非常的稳定啊？对不对？唉，你看谁想谁敢对我", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy.topic_18','political_theory.thought.economy','行测','政治理论','共同富裕与收入分配','concept',1,1,'gongkao.xingce.political_theory.thought.economy.topic_18','课程知识：共同富裕与收入分配。点，大家能够明确就行了，然后紧接着啊，和第二个本世纪中叶我们要实现的目标相对应的，有一个点同学们非常重要，我们后面也会讲到就是这个共识。同富裕看到了吗？哎，你看共同富裕的表述在这里面，哎，就不太一样了，因为我们刚才强调了，到二零三五年本世纪中叶的时候，我们的共同富裕要。应该按照正常来讲的话，它应该是基本实现共同富裕，对不对？但是你看他说的是取得更为明显的实质性进展。啊，而到本世纪中叶，他才强调全体人民共同富裕怎么样，基本实现这就是一个区别了，同学们。和大多数表述不一样的地方，是不是哎？所以同学们记住本共同富裕到什么时候才基本实现，是到本世纪中叶，为什么同学们？其实很简单啊，你想想共同富裕的实现','{"source": "fengze_politics_course_catalog", "aliases": ["共同富裕"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10860, "end_char": 11160, "line": 1, "excerpt": "点，大家能够明确就行了，然后紧接着啊，和第二个本世纪中叶我们要实现的目标相对应的，有一个点同学们非常重要，我们后面也会讲到就是这个共识。同富裕看到了吗？哎，你看共同富裕的表述在这里面，哎，就不太一样了，因为我们刚才强调了，到二零三五年本世纪中叶的时候，我们的共同富裕要。应该按照正常来讲的话，它应该是基本实现共同富裕，对不对？但是你看他说的是取得更为明显的实质性进展。啊，而到本世纪中叶，他才强调全体人民共同富裕怎么样，基本实现这就是一个区别了，同学们。和大多数表述不一样的地方，是不是哎？所以同学们记住本共同富裕到什么时候才基本实现，是到本世纪中叶，为什么同学们？其实很简单啊，你想想共同富裕的实现", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11114, "end_char": 11414, "line": 1, "excerpt": "一大市场能理解吗？同学们唉，要建设我们全国的统一大市场啊，然后紧接着再往下，我们说到收入分配，那收入分配的咋样啊？现在是不是得？要公平啊，对不对？唉，我们之前讲共同富裕的时候不是多次给大家说了吗？你先把蛋糕做大，要体现效率，对吧？再把蛋糕分好，要促进公平啊，是这种啊。那城乡区域发展怎么发展啊？很明显就这一个词协调，昨天我们讲到新发展理念的时候，是不是说到唉协调它是？我们经济健康发展的一个什么内在要求，所以城乡发区域发展，那就是协调对吧？唉，协调，然后紧接着绿色发展，你看到这个词对不对？绿色和谁相关？生态环境相关。所以你看资源节约，环境友好，对吧？唉，那么全面开放体系开放应该怎样？同学们应该怎样", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 20553, "end_char": 20853, "line": 1, "excerpt": "为我们在后面还会讲到一个地位和它有点像啊，两者有点像，所以先把它记住啊，收入分配是民生之源。是改善民生，实现发展成果由人民共享最重要最直接的方式分配制度，是促进共同富裕的基础性制度。那我们要来理解一下对不对我们国家现在的分配制度是什么样的？同学们，我们之前是不是在讲经济的时候，同学们还记得吗？唉，我们之前是在讲经济常识的时候，是不是给大家讲过关于我们国家的三次分配的这个问题，对不对？唉，三次分配的问题啊。好，那来看具体的这个收入分配到底怎么分配？初次再分配或第三次分配相协调的，这样的一个协调。协调配套的制度体系啊，那同学们来看一下啊，首先第一个它说要发挥初次分配的基础性作用。啊，因为大家想一想", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.economy.topic_19','political_theory.thought.economy','行测','政治理论','教育科技人才一体发展','concept',1,1,'gongkao.xingce.political_theory.thought.economy.topic_19','课程知识：教育科技人才一体发展。来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强国，人才强国，文化强国，体育强国和健康中国。所以这两个比较特殊的，大家重点去记它，没带基本啊，没带基本好，那除了刚才给大家强调的，对吧？有一些带了基本有一些没带基本，那还有。一个考点非常重要的就是大家要把这六个国要记清楚，同学们，因为我们后面讲到政治理论的时候，经常会给大家强调，对吧？哎，教育强国呀啊，什么文化强国呀等等，这些什么时候建成呢？你看。我们强调，到二零三五年的时候，就要建成教育，科技，人才，文化，体育强国以及健康中国。那这个咋记','{"source": "fengze_politics_course_catalog", "aliases": ["人才"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10225, "end_char": 10525, "line": 1, "excerpt": "来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强国，人才强国，文化强国，体育强国和健康中国。所以这两个比较特殊的，大家重点去记它，没带基本啊，没带基本好，那除了刚才给大家强调的，对吧？有一些带了基本有一些没带基本，那还有。一个考点非常重要的就是大家要把这六个国要记清楚，同学们，因为我们后面讲到政治理论的时候，经常会给大家强调，对吧？哎，教育强国呀啊，什么文化强国呀等等，这些什么时候建成呢？你看。我们强调，到二零三五年的时候，就要建成教育，科技，人才，文化，体育强国以及健康中国。那这个咋记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 14534, "end_char": 14834, "line": 1, "excerpt": "是啥呀？你既然想要让乡村振兴，你必须要坚持农业农村怎么样优先发展？这是很关键的，什么叫优先发展？同学们，比如说你要从资金的，对吧？这种配备上啊，资金的补充上，从人才的配备上，对不对？哎，从各种技术的这种支持上，你都要优先。去支持农业农村的发展，这才是我们强调的它的总方针。哎，好，那么来看第二个总要求是啥？总要求这几个词理解就行了，同学们也不要求大家去记了啊，因为也提了很早了。你看它的总要求是什么？你有没有发现其实这五个词也暗合了我们之前说到五位一体。对吧，你看一看同学们，咱们带着大家一起来看一下啊，说啥呢？第一个产业兴旺，是不是经济层面说的要产业兴旺，第二个生态宜居，那就是生态嘛。而乡风文明是", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 7553, "end_char": 7853, "line": 1, "excerpt": "一个就是我们刚才说的军委主席的负责制，哎，把这两个点重点掌握就行了啊，二和三呢，这个理解就可以啊。好了，那么往下同学们第二个啊，关于这个政治建军改革强军科技强军人才强军和依法治军的这个问题。呃，这块儿呢，我先给大家说一下，就是过去它的一个发展啊，因为最早呢，我们提到这几个军的时候，其实没有这个人才强军。啊，然后过去的时候叫啥呢？叫科技兴军啊，科技兴军，所以过去提到这儿的时候，它强调的叫政治建军。改革强军，科技兴军，依法治军啊，但是你看现在我们把科技兴军改成了强军，对吧？哎，然后又多加了一个人才强军。唉，以及最后说的依法治军，所以现在变成五个了，这有一个改啊，改变了，那先来看第一个同学们政治建军", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.democracy.topic_20','political_theory.thought.democracy','行测','政治理论','国家治理体系和治理能力现代化','concept',1,1,'gongkao.xingce.political_theory.thought.democracy.topic_20','课程知识：国家治理体系和治理能力现代化。先先看就是我们关和这个基本实现社会主义现代化相对应的，它是不是都带了一个基本？看到了吗？同学们，我们讲义当中有很多的内容，说基本实现四化，对吧？哎，基本实现啊，国家治理体系治理能力现代化基本建成法治国家法治政府法治社会。以及后面你看第六个啊和第七个啊，第七个它说美丽中国目标基本实现以及基本实现国防军队现代化，因为我们强调了。二零三五年的时候，它是不是要基本实现社会主义现代化呀？对不对哎？所以很多的目标前面它都带了一个基本。但是在这里面回过头来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强','{"source": "fengze_politics_course_catalog", "aliases": ["国家治理"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 10003, "end_char": 10303, "line": 1, "excerpt": "先先看就是我们关和这个基本实现社会主义现代化相对应的，它是不是都带了一个基本？看到了吗？同学们，我们讲义当中有很多的内容，说基本实现四化，对吧？哎，基本实现啊，国家治理体系治理能力现代化基本建成法治国家法治政府法治社会。以及后面你看第六个啊和第七个啊，第七个它说美丽中国目标基本实现以及基本实现国防军队现代化，因为我们强调了。二零三五年的时候，它是不是要基本实现社会主义现代化呀？对不对哎？所以很多的目标前面它都带了一个基本。但是在这里面回过头来给大家重点强调，同同学们看有两个。它没有强调基本对不对现代化经济体系强调建成，然后。后面这几个强国看到了吗？六个国对不对？唉，也是强调建成教育强国，科技强", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 31725, "end_char": 32025, "line": 1, "excerpt": "社区治理，这里强调的一个点，一定要记住这个啊，包括大家之前学申论的时候应该也学过这个词，对不对？也就是最后一公里的问题啊，什么叫最后一公里啊，你看。说基层治理是国家治理的基石，城乡社区，这是关键啊，是社会治理最基本的单元。是党和政府联系服务群众的最后一公里，因为大家想呀，我们现在是不是很多的人啊？很多的人你是不是都。再不就是生活在我们乡村的农村，对不对？哎，或者说生活在城市的社区里面啊，你都是在这个里面，所以在这种情况之下啊，我们强调它是。党和政府联系服务群众的最后一公里，所以现在你看我们不是经常说嘛，要打通最后一公里对不对？哎，打通最后一公里啊，也就是在强调啥，要密切和人民群众之间的这种联系", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.democracy.topic_21','political_theory.thought.democracy','行测','政治理论','法治与德治相结合','concept',1,1,'gongkao.xingce.political_theory.thought.democracy.topic_21','课程知识：法治与德治相结合。是我们依法治国的主体，然后其次等国际强调等第三个法律面前人人平等，是不是在之前给大家说的我们？这个法律对不对？宪法的原则嘛啊？宪法的原则啊，然后国强调依法治国和以德治国相结合，最后记。从中国的实际出发，这就是我们全面依法治国的基本的原则。好吧，唉，基本的原则啊。好，那么这几个点前面两个一个党，一个人民其实就在强调这个呃，我们主体的问题是不是然后第三个强调的法律面前人人平等，也就是法律上我们的人际关系的问题？紧接着注意，后面他说的这个依法治国和以德治国的问题，给大家说一下啊，为什么在强调法治的时候，它还在强调叫以德治国的问题呢，同学们？其实很简单，你看法律这个东西啊，它是以这种就是成文的法规的形','{"source": "fengze_politics_course_catalog", "aliases": ["以德治国"], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 48717, "end_char": 49017, "line": 1, "excerpt": "是我们依法治国的主体，然后其次等国际强调等第三个法律面前人人平等，是不是在之前给大家说的我们？这个法律对不对？宪法的原则嘛啊？宪法的原则啊，然后国强调依法治国和以德治国相结合，最后记。从中国的实际出发，这就是我们全面依法治国的基本的原则。好吧，唉，基本的原则啊。好，那么这几个点前面两个一个党，一个人民其实就在强调这个呃，我们主体的问题是不是然后第三个强调的法律面前人人平等，也就是法律上我们的人际关系的问题？紧接着注意，后面他说的这个依法治国和以德治国的问题，给大家说一下啊，为什么在强调法治的时候，它还在强调叫以德治国的问题呢，同学们？其实很简单，你看法律这个东西啊，它是以这种就是成文的法规的形", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.party.topic_22','political_theory.thought.party','行测','政治理论','全面从严治党','concept',1,1,'gongkao.xingce.political_theory.thought.party.topic_22','课程知识：全面从严治党。几章就是14，15，16和17讲完啊呃，我估计如果明天要能讲快点儿的话，没准儿明天能提前下课啊，同学们，因为后面剩下的这几章呢？呃，其实最重要的就是最后一章全面从严治党啊，其他那几个章节其实也不是特别的重要好吧哎。','{"source": "fengze_politics_course_catalog", "aliases": ["从严治党"], "course_sources": [{"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 53787, "end_char": 53894, "line": 1, "excerpt": "几章就是14，15，16和17讲完啊呃，我估计如果明天要能讲快点儿的话，没准儿明天能提前下课啊，同学们，因为后面剩下的这几章呢？呃，其实最重要的就是最后一章全面从严治党啊，其他那几个章节其实也不是特别的重要好吧哎。", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 34912, "end_char": 35212, "line": 1, "excerpt": "政策沟通设施连同贸易畅通，资金融通，民心相通啊，好，这是在这儿，所以这道题选的就是啥呀，选的就是b选项啊，选的就是b选项。好了，来，同学们往下来看。第17章全面从严治党打起精神来，同学们啊，这是我们在新思想这一块的最后一个章节，而这个章节。十分之重要，同学们啊，十分之重要，因为它是和我们党的建设相关，也就是我们常提的党建问题，对不对？哎，尤其是从我们啊这个习近平总书记开始啊。他一直在强调加强党的自身建设的这个问题啊，后期你看他还提出了自我革命这个跳出历史周期律的第二个答案，对不对？哎，那到底在新时代，我们应该如何？进行党的建设呢，对不对？来往下看啊，同学们，首先第一个他说到全面建设社会主义现代", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.security.topic_23','political_theory.thought.security','行测','政治理论','总体国家安全观','concept',1,1,'gongkao.xingce.political_theory.thought.security.topic_23','课程知识：总体国家安全观。域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没有说直接全部给你放开啊，所以这个时候你要保证一定的国家安全啊，因为你有很多行业，一旦啊，给它完全放开之后。它这个时候就会受到冲击，那就会就会出现这个问题，而最后一个就是我们一直在说的我们国家的经济体制，对吧？社会主义市场经济体制一方面要发挥市场的决定性作用，对不对？另外一个方面要发挥什么？发挥政府的宏观调控作用啊好，你看其实实际上你这样前后去对着去记，我感觉还是相对来说比较简单的，对不对？哎，还是比较简单的啊，哎呀，我非常我非常欣慰，我看到有一个同学说说，今天听着听着课好像开悟了，是不','{"source": "fengze_politics_course_catalog", "aliases": ["国家安全"], "course_sources": [{"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 11443, "end_char": 11743, "line": 1, "excerpt": "域，现在要不断的去试呃试点儿，能不能后驱？对不对？像这个什么？啊，文化呀，对吧？哎，医疗呀，等等这些你看他并没有说直接全部给你放开啊，所以这个时候你要保证一定的国家安全啊，因为你有很多行业，一旦啊，给它完全放开之后。它这个时候就会受到冲击，那就会就会出现这个问题，而最后一个就是我们一直在说的我们国家的经济体制，对吧？社会主义市场经济体制一方面要发挥市场的决定性作用，对不对？另外一个方面要发挥什么？发挥政府的宏观调控作用啊好，你看其实实际上你这样前后去对着去记，我感觉还是相对来说比较简单的，对不对？哎，还是比较简单的啊，哎呀，我非常我非常欣慰，我看到有一个同学说说，今天听着听着课好像开悟了，是不", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 46954, "end_char": 47254, "line": 1, "excerpt": "对不对哎？以国家公园为主体，然后三生道路，这不都是刚才说的吗？啊，好了，这是在这儿啊，第二题选的是c好吧嗯。然后紧接着同学们来往下看啊，往下看第13章维护和塑造国家安全啊，那么关于国家安全的问题啊，国家安全的问题来看啊来看。脑子塞不下了呀，塞不下也得塞，同学们啊，咱现在也不能下课，知道吧，还有半个小时呢啊，实在不行了，对吧，站起来啊。啊，那个拍拍自己的脸是不是如果感觉还不清醒，那就用点儿力啊，再不清醒再用点儿力是不是到最后你真的把自己？啪一下子对不对哎？就给打醒了，那个时候就行了啊，来吧，同学们先来看啊，总体国家安全观这一块，他说到的这个。坚持总体国家安全观。那安全观到底是什么？咱是不是得了解", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 13225, "end_char": 13525, "line": 1, "excerpt": "后紧接着再往下第二个四体啊，我说了这个东西一般它不会挖坑，对不对哎？所以你大概读完之后没有什么错误的，你就默认它是对的就行了啊。紧接着再往下第二个二零二四年总体国家安全观提出十周年，是不是啊？同学们二零一四年啊，不是二零二四年啊，二零二四年。是不是啊？嗯，是不是啊？是呀，同学们嗯，哎呀。你回去啊，回去去看一看啊，回去去看一看，我们当时说的那个十周年是什么十周年，对吧？而我们当时明确给大家说的是二零一四年的时候，当时习近平总书记提出的。总体的国家安全观能理解吗？哎，然后他把二零呃，这个把那个4月15日哎，二四月十五日在二零一五年的时候，然后给他确定为了这个全民国家安全教育日。能理解吗？然后二五年", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.defense.topic_24','political_theory.thought.defense','行测','政治理论','人民军队与国防建设','concept',1,1,'gongkao.xingce.political_theory.thought.defense.topic_24','课程知识：人民军队与国防建设。14章节啊，我们的这个强大人民军队啊，所以如果之前没有跟着课的同学啊，今天呢呃，这个过来听课对吧？咱们把这个讲义啊打到第14章节好吧？好了，来看啊，在第14章节这一块儿呢，强调这个关于建设巩固国防和强大人民军队的问题。呃，那么今年呢？呃，针对于军队国防的这个问题呃，因为这个九三阅兵的问题是不是呃，所以呢，它呃会是我们在考试过程当中的一个重点内容。能理解吧，好，所以接下来啊啊，接下来我们来看一看啊，首先第一个就是关于这个军队建设，它对于我们的这个重要性在哪？那首先','{"source": "fengze_politics_course_catalog", "aliases": ["人民军队"], "course_sources": [{"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 0, "end_char": 233, "line": 1, "excerpt": "14章节啊，我们的这个强大人民军队啊，所以如果之前没有跟着课的同学啊，今天呢呃，这个过来听课对吧？咱们把这个讲义啊打到第14章节好吧？好了，来看啊，在第14章节这一块儿呢，强调这个关于建设巩固国防和强大人民军队的问题。呃，那么今年呢？呃，针对于军队国防的这个问题呃，因为这个九三阅兵的问题是不是呃，所以呢，它呃会是我们在考试过程当中的一个重点内容。能理解吧，好，所以接下来啊啊，接下来我们来看一看啊，首先第一个就是关于这个军队建设，它对于我们的这个重要性在哪？那首先", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.culture.topic_25','political_theory.thought.culture','行测','政治理论','文化自信与社会主义核心价值观','concept',1,1,'gongkao.xingce.political_theory.thought.culture.topic_25','课程知识：文化自信与社会主义核心价值观。，你就要时刻的把人民放在心里，把国家放在心里啊。好了，这是在这儿啊，这个点就讲到这儿好吧，唉，多余的咱就不讲了啊，好，那紧接着往下来看啊，第三个就是关于社会主义核心价值观的问题了。这个点呢，我只能说它很重要，但是我们现在考试考的少，能理解吗？同学们啊，因为关于社会主义核心价值观的问题啊，我们在前些年的考试当中。啊，尤其是在很多事业单位考试当中啊，他把这个东西基本上考烂了啊，就直接问你啊，考的也非常简单，就直接问你说社会主义核心价值观，它在国家层面的表述是什么？同学们啊，其实就这12个词，你对应记清楚就行了，很简单，国家层面叫什么叫富强，民主，文明，和谐。啊，你多记多背几遍，其实这个马上啊就就记','{"source": "fengze_politics_course_catalog", "aliases": ["核心价值观"], "course_sources": [{"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 4571, "end_char": 4871, "line": 1, "excerpt": "，你就要时刻的把人民放在心里，把国家放在心里啊。好了，这是在这儿啊，这个点就讲到这儿好吧，唉，多余的咱就不讲了啊，好，那紧接着往下来看啊，第三个就是关于社会主义核心价值观的问题了。这个点呢，我只能说它很重要，但是我们现在考试考的少，能理解吗？同学们啊，因为关于社会主义核心价值观的问题啊，我们在前些年的考试当中。啊，尤其是在很多事业单位考试当中啊，他把这个东西基本上考烂了啊，就直接问你啊，考的也非常简单，就直接问你说社会主义核心价值观，它在国家层面的表述是什么？同学们啊，其实就这12个词，你对应记清楚就行了，很简单，国家层面叫什么叫富强，民主，文明，和谐。啊，你多记多背几遍，其实这个马上啊就就记", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 16554, "end_char": 16854, "line": 1, "excerpt": "这个情况之下，你看强化我们的内外联通啊，内外联通啊。啊，那内联外通啊，内联外通内联外通啊，好，这是在这儿啊，往下第四个弘扬核心价值，促进包容和谐，还有我们的这种核心价值观的问题啊。好了，这是在这儿，同学们，你看呃这几句话呢，你可以这样去记啊，叫依法内心啊，依法内心一强调的叫一国之本，对不对？哎，发强调高质量发展，高水平安全嘛。啊，然后内强调内廉外通对不对？新强调弘扬核心价值啊，所以在这一块的时候，同学们你注意啊，因为这这两句话说实话，它四句话加到一起比较长嘛，是不是？所以你就。啊，记一些关键词，把它能够记住就行了啊，所以叫一发内心啊，一发内心好，这是四条经验，那紧接着往下又对新一届的这个澳门特", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.ecology.topic_26','political_theory.thought.ecology','行测','政治理论','生态文明与绿色发展','concept',1,1,'gongkao.xingce.political_theory.thought.ecology.topic_26','课程知识：生态文明与绿色发展。会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？经济，政治，文化，社会，生态文明，按照这个方向去思考，你也不用把这几句话完全背下来，对吧？唉，你也能知道他到底在说什么？然后紧接着发展中特儿就只剩最后一个了，中国特色社会主义对吧？唉，所以我们强调本质要求，强调的是党人按照五位一体发展中特儿。好吧，唉，按照这个去记就可以了啊，好了，这是本质要求，那么回过头来看下面第第三个问题就是重大原则啊。重大原则，这个东西呢，你注意，一般我们后面在讲到关于原则性的问题的时候，就是在实现中国式现代化的过程当中，这些东西是不能变','{"source": "fengze_politics_course_catalog", "aliases": ["生态文明"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15789, "end_char": 16089, "line": 1, "excerpt": "会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？经济，政治，文化，社会，生态文明，按照这个方向去思考，你也不用把这几句话完全背下来，对吧？唉，你也能知道他到底在说什么？然后紧接着发展中特儿就只剩最后一个了，中国特色社会主义对吧？唉，所以我们强调本质要求，强调的是党人按照五位一体发展中特儿。好吧，唉，按照这个去记就可以了啊，好了，这是本质要求，那么回过头来看下面第第三个问题就是重大原则啊。重大原则，这个东西呢，你注意，一般我们后面在讲到关于原则性的问题的时候，就是在实现中国式现代化的过程当中，这些东西是不能变", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 34913, "end_char": 35213, "line": 1, "excerpt": "一定要抓住这些题里面能够出题挖坑的点，然后去思考它有没有挖坑，对不对？有没有改啊？这是主要的。好，这是第二个啊，然后紧接着同学们往下咱们来看第12章建设社会主义生态文明啊，那么生态文明建设这一块呢，来看一下啊，第一个。说到他的地位，这个地位一定要记住的啊，生态文明建设是关系中华民族永续发展的根本大计啊，根本大计，你看你就直接记生根就行了，对吧？哎，正好和这个生态环境相关嘛。而且你直接去理解也行，同学们啊，为什么说生态文明它是永续发展的根本大计啊？其实很简单啊，我们之前多次给大家说到过，就是生态环境问题，它不仅仅关系的是我们一代人的问题，能理解吗？哎。它关系到的是我们子孙后代代代人的问题，所以在", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.thought.diplomacy.topic_27','political_theory.thought.diplomacy','行测','政治理论','人类命运共同体与大国外交','concept',1,1,'gongkao.xingce.political_theory.thought.diplomacy.topic_27','课程知识：人类命运共同体与大国外交。一体发展中特。啥意思呢？你看第一个党坚持党的领导，毕竟别的国家没有中国共产党的领导，对不对？哎，只有我们国家有，然后其次。人强调的是什么？强调的是后是后两个一个人类命运共同体，一个人类文明新形态，所以这是党人啊，然后按照五位一体同学们哪五位一体啊？看从这儿开始啊，第一个标一下经济是不是强调高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。紧接着，从这个社会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？','{"source": "fengze_politics_course_catalog", "aliases": ["人类命运共同体"], "course_sources": [{"source_file": "20250905 政治理论8.doc.txt", "source_sha256": "6f0b9caf0abffbadb48023e389bccfd4850f837268bbe483f89954bd5809ffa6", "start_char": 15557, "end_char": 15857, "line": 1, "excerpt": "一体发展中特。啥意思呢？你看第一个党坚持党的领导，毕竟别的国家没有中国共产党的领导，对不对？哎，只有我们国家有，然后其次。人强调的是什么？强调的是后是后两个一个人类命运共同体，一个人类文明新形态，所以这是党人啊，然后按照五位一体同学们哪五位一体啊？看从这儿开始啊，第一个标一下经济是不是强调高质量发展对吧？哎，然后从政治我换一个颜色吧啊，换一个颜色啊。然后从政治上强调的是什么？强调的是发展全过程，人民民主啊，那么从文化上强调的是丰富人民精神世界。紧接着，从这个社会层面强调实现全体人民共同富裕，最后从生态上强调促进人与自然啊和谐共生。所以你看同学们，只要你了解我们所说的五位一体是哪五个方面，对吧？", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250906 政治理论9.doc.txt", "source_sha256": "2c602a2f6c5e051446eec5a93488d3fed8cea2944daeb7bde682ecce33cdf723", "start_char": 56901, "end_char": 57201, "line": 1, "excerpt": "化是更基础，更广泛，更深厚的自信啊，它是最基本，最深沉，最持久的力量，明确它就行了啊。要不然的话，你想想同学们，你为什么现在习近平总书记在国际的讲话当中经常提叫人类命运共同体，对不对？他提这个东西啊，为什么很多人能信服？对不对？包括我们国家的很多的民众，你去向一些外国友人介绍这个东西的时候对不对？唉，你看你说我们现在正在创建人类命运共同体。你为什么能够很自信的把这个东西说出来，去向他介绍，不就是因为我们一直在说古代文化当中，中国一直在强调大同社会的理念，对吧？唉，这是古人就已经有的这样一种啊观念，我们只不过是现在把它拿出来了，对不对？唉，拿出来介绍给你，这就是中国古人的东西啊。所以你看最后他说", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250913 政治理论11.doc.txt", "source_sha256": "fe20a00240908eec78467dc627acf15aae10ec2d4ce973c93a4afb9f5cee12aa", "start_char": 29255, "end_char": 29555, "line": 1, "excerpt": "？对不对？哎，所有的外交工作其实实际上都是为了啥呀？同学们。不就是为了主权，安全，发展利益嘛，对不对？哎，说了太多遍了啊，好了，然后紧接着往下同学们看第三个构建人类命运共同体的问题。这个人类命共同体这一块儿呢，大家可以看啊呃，首先啊，他提到了说这个构建人类命共同体呢，是当代中国共产党人回答和解决人类前途命运的时代之问的中国方案。哎，也是我们新时代对外工作的一个总目标，了解就行，同学们啊，了解就行，那么往下第一个啊，先明确构建人类命运共同体。它是世界各国人民的前途所在，那什么叫人类命运共同体啊？同学们记住这五个词要有印象啊。五个词强调，持久和平，普遍安全，共同繁荣，开放包容和清洁美丽。看到了吗？", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.rural.topic_28','political_theory.policy.rural','行测','政治理论','粮食安全与农业强国','concept',1,1,'gongkao.xingce.political_theory.policy.rural.topic_28','课程知识：粮食安全与农业强国。紧接着往下两个确保，确保是啥呢？这是过去我们在讲到呃二四年一号文件的时候说到的，我们要确保两条底线。啊，所以我们经常叫两个底线嘛，哪两个底线一个强调的是确保国家粮食安全底线，另外一个是确保不发生规模性返贫置贫底线。看到了吧？哎，这是两条底线啊，也要从整个的这个农业发展上对不对？哎，从三农的这个角度上，我们强调两条底线，一个是粮食安全，一个是哎，不发生规模性返贫置贫的底线。那么，三个提升，三个提升，提升啥？同学们，其实这是过去在二四年一号文件当中提出的，叫三项重点工作。啊三项重点工作，那我们后面讲的很多的举措，同学们，你会发现它都是围绕着两个确保和三个提升来的啊，哪三项重点工作呢？第一个强调。提','{"source": "fengze_politics_course_catalog", "aliases": ["粮食安全"], "course_sources": [{"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 32313, "end_char": 32613, "line": 3, "excerpt": "紧接着往下两个确保，确保是啥呢？这是过去我们在讲到呃二四年一号文件的时候说到的，我们要确保两条底线。啊，所以我们经常叫两个底线嘛，哪两个底线一个强调的是确保国家粮食安全底线，另外一个是确保不发生规模性返贫置贫底线。看到了吧？哎，这是两条底线啊，也要从整个的这个农业发展上对不对？哎，从三农的这个角度上，我们强调两条底线，一个是粮食安全，一个是哎，不发生规模性返贫置贫的底线。那么，三个提升，三个提升，提升啥？同学们，其实这是过去在二四年一号文件当中提出的，叫三项重点工作。啊三项重点工作，那我们后面讲的很多的举措，同学们，你会发现它都是围绕着两个确保和三个提升来的啊，哪三项重点工作呢？第一个强调。提", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 10062, "end_char": 10362, "line": 1, "excerpt": "之外，剩下的同学们都是一样的，和我们之前讲的一号文件的说法是完全一样的，你看比如说我们。之前给大家强调的两条底线，对吧？哎，哪两条底线啊？同学们，一个是确保国家粮食安全底线，另外一个就是确保农业呃，农村人口不发生规模性返贫底线啊。啊，然后紧接着再往下三项重点工作，哪三项重点工作呀？是不是哎？以提升乡村产业发展，乡村建设，乡村治理水平啊？那你可以记按照之前的这个记啊。叫什么叫产建制？看到了吗？产建制啊，你可以按照这个去记好不好？哎，好了啊，这是在这一块儿，然后最后这五个振兴了解就行了，好吧，哎，这个不作为重点啊，产业人才。文化生态组织振兴，这提了太久了啊，提了太久了好了，这是在这儿啊，我们给大家", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.plans.topic_29','political_theory.policy.plans','行测','政治理论','教育强国建设','concept',1,1,'gongkao.xingce.political_theory.policy.plans.topic_29','课程知识：教育强国建设。后紧接着再往下进一步形成人才辈出，人尽其才，人尽其用的生动局面，这就不说了，同学们啊，这三个词。看一看就可以了啊，可出题的点其实不是特别的多，然后往下第二个建设教育强国啊，科技强国，人才强国，必须坚持什么呢？正确的办学方向先理解这个。同学们，还记不记得正确的办学方向是什么方向？同学们非常好，我看到了花生不识数，同学对吧？唉，是社会主义的办学方向。啊，社会主义办学方向千万记住啊，这是我们后面讲新思想的时候，其实会讲到的啊，也就是本身关于正确的办学方向的问题，哪个方向其实就是我们。啊，这个整个大的层面上是要坚持社会主义的办学方向，这个就是啥意思呢？也就是你不要在这个培养人才的过程当中，对不对？哎，','{"source": "fengze_politics_course_catalog", "aliases": ["教育强国"], "course_sources": [{"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 10217, "end_char": 10517, "line": 1, "excerpt": "后紧接着再往下进一步形成人才辈出，人尽其才，人尽其用的生动局面，这就不说了，同学们啊，这三个词。看一看就可以了啊，可出题的点其实不是特别的多，然后往下第二个建设教育强国啊，科技强国，人才强国，必须坚持什么呢？正确的办学方向先理解这个。同学们，还记不记得正确的办学方向是什么方向？同学们非常好，我看到了花生不识数，同学对吧？唉，是社会主义的办学方向。啊，社会主义办学方向千万记住啊，这是我们后面讲新思想的时候，其实会讲到的啊，也就是本身关于正确的办学方向的问题，哪个方向其实就是我们。啊，这个整个大的层面上是要坚持社会主义的办学方向，这个就是啥意思呢？也就是你不要在这个培养人才的过程当中，对不对？哎，", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250907 政治理论(时政)加课4.doc.txt", "source_sha256": "56a19585993b7725bd6296acc5ecd3f3893681b40f699a03a757ae5216055b0a", "start_char": 8508, "end_char": 8808, "line": 3, "excerpt": "一点儿。那么，往下第三个啊，我们强调深入实施科教兴国战略，提升国家创新体系的整体效能，那怎么实行科科教兴国呢？首先，第一个强调了一个数字啊。数字这块说，制定实施教育强国建设的三年行动计划啊，我们之前啊，给大家也说过这个问题，就是如果说在一整道题当中，你会发现啊。呵呵呵，是别骂了，题是我出的，同学们别骂了好吗？哈哈哈，题是我出的啊。就是呃，如果啊，在一个题当中，他所有的一些这个选项都没有去提到这个呃年份的这个问题，知道吗？哎，都没有提到这个年份数字的问题而。只有一个选项提到了年份的问题，你就要重点关注了，知道了吗？同学们哎，那他很有可能，你看把这个三年就改成五年对不对？哎，等等，类似于这种啊，所", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250914 政治理论(时政)加课5.doc.txt", "source_sha256": "023f95f6ae4fc26da41aaf7893e8784969bf053aa909f04dddbb3bfabeb2e63f", "start_char": 73, "end_char": 373, "line": 1, "excerpt": "给大家讲到了第三章对不对哎？第三章呢？然后我们把这个重要的文件。前两个也就是政府工作报告以及中央一号文件给大家讲完了，那么今天呢？我们继续开始讲啊，就是讲第三个教育强国建设规划纲要二零二四到二零。二零三五年，所以之前的时候，如果大家啊没没及时跟课的对吧？然后今天来了那把这个讲义啊，打到咱们这个章节好吧？那么来看啊，在这个章节当中，其实你会发现啊，关于教育强国的很多问题，我们在之前的时候给大家多多少少讲到新思想的时候，其实有一些问题是强调过的，对吧？哎，那先来看第一个啊，在这个规划纲要当中，第一个需要大家掌握的知识点就在这儿了，看到了吧？哎，也就是坚持什么样的一种办学方向，那么我们前面在讲到这个", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform.topic_30','political_theory.policy.reform','行测','政治理论','党史与革命精神','concept',1,1,'gongkao.xingce.political_theory.policy.reform.topic_30','课程知识：党史与革命精神。是遭遇了四一二和七一五的反革命政变之后。啊，然后我们开始南昌对吧？哎，然后这个秋收起义和广州起义等等，他在这些起义最终结果都失败之后。想一想毛主席，他就转战到了井冈山，建立了井冈山革命根据地，然后由此提出了一个非常重要的革命时期的理论什么。农村包围城市武装夺取政权呀，对吧？他为什么提这个？就是因为毛主席当时意识到了。既然我们要让人民群众站在我们这边，对不对？那当时中国社会而言，我们最广大的人民群众就是谁同学们？那不就是在农村待着的农民吗？我们当时中国80%都是农民啊，同学们哎，所以你看我们扎根农村，取得了农民的广泛信任，就代表我们真正的走到了人民群众的心里。对不对？所以你看到最后我们在解放战争','{"source": "fengze_politics_course_catalog", "aliases": ["井冈山"], "course_sources": [{"source_file": "20250829 政治理论6.doc.txt", "source_sha256": "7cca8feb37e3910d37003296b259eb17dcc73b56326d9b1d353020be905a220f", "start_char": 24520, "end_char": 24820, "line": 1, "excerpt": "是遭遇了四一二和七一五的反革命政变之后。啊，然后我们开始南昌对吧？哎，然后这个秋收起义和广州起义等等，他在这些起义最终结果都失败之后。想一想毛主席，他就转战到了井冈山，建立了井冈山革命根据地，然后由此提出了一个非常重要的革命时期的理论什么。农村包围城市武装夺取政权呀，对吧？他为什么提这个？就是因为毛主席当时意识到了。既然我们要让人民群众站在我们这边，对不对？那当时中国社会而言，我们最广大的人民群众就是谁同学们？那不就是在农村待着的农民吗？我们当时中国80%都是农民啊，同学们哎，所以你看我们扎根农村，取得了农民的广泛信任，就代表我们真正的走到了人民群众的心里。对不对？所以你看到最后我们在解放战争", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250912 政治理论10.doc.txt", "source_sha256": "ea070e685688e5ea41ffaa5d84bea0f9186983d157cc2a0cb05a68fe3f5d3629", "start_char": 6304, "end_char": 6604, "line": 1, "excerpt": "神。啊，就这三个方面，其实你主要联系前面就行了，也就是开天辟地，对不对？敢为人先首创嘛，毕竟红船精神是我们党创建的时候啊，创建的时候。然后紧接着后面其他的啊，像井冈山精神这个不做重点介绍啊啊，井冈山呢呃，这个我们之前强调的是在一九二七年还记得吗啊，秋收起义结束之后啊，然后呢？呃秋收起义最终的这个结果不是失败了吗？失败之后，然后啊，毛泽东同志带领着我们当时的起义队伍转战到井冈山，是不是哎？然后成立了井冈山根据地啊。好，这个大家知道，井冈山是我们的第一个革命根据地，其实就行了啊，然后它里面的这些内容简单，看看这个不做一个重点啊。然后往下。第二个重点呢，就是它看到了吗？同学们叫遵义会议精神啊，遵义会", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
INSERT OR IGNORE INTO knowledge_nodes(id,parent_id,subject,module,name,node_type,weight,exam_priority,knowledge_node_code,description,metadata_json) VALUES('political_theory.policy.reform.topic_31','political_theory.policy.reform','行测','政治理论','历史重要会议与政策沿革','concept',1,1,'gongkao.xingce.political_theory.policy.reform.topic_31','课程知识：历史重要会议与政策沿革。全称是什么？看它的这个称呼啊，叫中国共产党第20次全国代表大会。这也就是我们简单意义上来说的什么，同学们。就是党代会。啊，就是党代会，我们所有的党员，我们之前学历史的时候是不是学了，对吧？还记得吗？同学们在一九二一年的时候，中共一大是不是召开了那个一大就是我们现在20大对吧？不断延伸过来的啊。从这开始，那么党代会注意它一般是多少？五年开一次啊，五年开一次，大家注意，这是从我们建国之后啊，建国之后也就是从一九八二年那个时候开始，其实才形成这样的一个。比较规律的啊，时间的啊，因为之前的时间大家学那个历史，我们学党代会的时候，大家也发现了那个时间不是很规律，对不对？哎，所以在这块儿大家知知道，就每五','{"source": "fengze_politics_course_catalog", "aliases": ["历史"], "course_sources": [{"source_file": "20250803  政治理论(时政)加课1.doc.txt", "source_sha256": "b345119d8a9cd86f1868804cf562c00feecdbb548ffa419e4bbb749ed523c0ae", "start_char": 7667, "end_char": 7967, "line": 1, "excerpt": "全称是什么？看它的这个称呼啊，叫中国共产党第20次全国代表大会。这也就是我们简单意义上来说的什么，同学们。就是党代会。啊，就是党代会，我们所有的党员，我们之前学历史的时候是不是学了，对吧？还记得吗？同学们在一九二一年的时候，中共一大是不是召开了那个一大就是我们现在20大对吧？不断延伸过来的啊。从这开始，那么党代会注意它一般是多少？五年开一次啊，五年开一次，大家注意，这是从我们建国之后啊，建国之后也就是从一九八二年那个时候开始，其实才形成这样的一个。比较规律的啊，时间的啊，因为之前的时间大家学那个历史，我们学党代会的时候，大家也发现了那个时间不是很规律，对不对？哎，所以在这块儿大家知知道，就每五", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250810 政治理论(时政)加课2.doc.txt", "source_sha256": "8dbc5b7ef9ecca325dbd36a44e2040fb776c6e9e35e82bd070d71cd12f7304b0", "start_char": 38335, "end_char": 38635, "line": 3, "excerpt": "命这一重大问题上认识更加清醒，行动更加坚定。因为我们之前说过自我革命，这是第几个答案，同学们。之前是不是讲了对吧？前面刚讲完啊，自我革命，这是我们党跳出治乱兴衰历史周期律的第二个答案，对吧？唉，前面说过就不再多说啊，所以你看我们坚持把它作为第二个答案。所以我们对于自我革命这个问题认识更加先行，更加坚定啊，那第二个就是我们在扎实开展党纪学习教育。啊，党纪学习教育那么全党同志遵守唉，遵规守纪的意识更加增强了啊，好，这是党纪，然后紧接着第三。持续加大反腐败力度，铲除腐败滋生的土壤和条件。同学们啊，这个反腐败力度大不大？你就看我们每天的新闻就行了，对吧？哎，每天你看，无论是我们的这个央央视新闻，还是新", "policy_id": null, "course_period": "2025-08至2025-09"}, {"source_file": "20250817 政治理论(时政)加课3.doc.txt", "source_sha256": "acf54011122a3e1ff956f62b3c1d4e7dd100e0fdf59297bac743fb646dbfca31", "start_char": 18988, "end_char": 19288, "line": 1, "excerpt": "国企业，中国公民一样的这种待遇。那你来不来？对吧？唉，是要来的啊，那么往下第八个第八个呢？强调多边主义是解决世界面临困难挑战的必然选择，而经济全球化是不可阻挡的历史潮流。这个注意别。别让这两个词互换位置就行了啊，因为之前我们在强调世界经济发展的时候，一直在说经济全球化，它是一种潮流，对吧？哎，因为现在你看没有哪个国家真正的能够独立于现代经济全球化的。潮流之外啊，没有哪个国家能真正的独立，任何国家的发展对吧？你看或者说有一些，尤其是做这种进出口企业的，它更加依赖于这种经济的发展啊。啊，那么还有就是前面说的多边主义，它是解决世界面临困难挑战的必然选择。当有一些问题出现的时候，对吧？各个国家之间我们", "policy_id": null, "course_period": "2025-08至2025-09"}], "course_period": "2025-08至2025-09"}');
